    @Test
    public void testEncodeBase64PartialOneByteWithPadding() {
        Base64Variant variant = Base64Variants.MIME;
        char[] buffer = new char[4];
        // For 1 byte (0x01), left-align in 24 bits: 0x010000
        // But encodeBase64Partial expects data in the right position
        // 0x01 << 16 = 0x010000 for 1 byte at bit positions 16-23
        int result = variant.encodeBase64Partial(0x010000, 1, buffer, 0);

        // For 1 byte with padding, writes 4 chars: AQ== (position returns 4)
        assertEquals(4, result);
        assertEquals('A', buffer[0]);
        assertEquals('Q', buffer[1]);
        assertEquals('=', buffer[2]);
        assertEquals('=', buffer[3]);
    }

