        MockTokenStreamContext(int type, String name, int index) {
            super(type, index);
            _name = name;
        }

        void setParent(TokenStreamContext parent) {
            _parent = parent;
        }

        @Override
        public TokenStreamContext getParent() {
            return _parent;
        }

        @Override
        public String currentName() {
            return _name;
