            assertTrue(e.getMessage().contains("10"));
            assertTrue(e.getMessage().contains("11"));
        }
    }

    @Test
    public void testRebuildCreatesBuilderWithCurrentSettings() {
        StreamWriteConstraints original = StreamWriteConstraints.builder()
                .maxNestingDepth(42)
                .build();
