        assertEquals(original.getMaxNestingDepth(), rebuilt.getMaxNestingDepth());
    }

    @Test
    public void testOverrideDefaultStreamWriteConstraints() {
        StreamWriteConstraints newDefault = StreamWriteConstraints.builder()
                .maxNestingDepth(999)
                .build();

