package tools.jackson.core.exc;

import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonToken;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class InputCoercionExceptionTest {

    @Mock
    private JsonParser mockParser;

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
    }

    @Test
    public void testConstructionWithValidParser() {
        String msg = "Input value '123' cannot be coerced to Integer";
        JsonToken inputType = JsonToken.VALUE_STRING;
        Class<?> targetType = Integer.class;

        InputCoercionException exception = new InputCoercionException(mockParser, msg, inputType, targetType);

        assertEquals(msg, exception.getMessage());
        assertEquals(inputType, exception.getInputType());
        assertEquals(targetType, exception.getTargetType());
        assertSame(mockParser, exception.processor());
    }

    @Test
    public void testConstructionWithNullParser() {
        String msg = "Error";
        JsonToken inputType = JsonToken.VALUE_NUMBER_INT;
        Class<?> targetType = Long.class;

        InputCoercionException exception = new InputCoercionException(null, msg, inputType, targetType);

        assertEquals(msg, exception.getMessage());
        assertEquals(inputType, exception.getInputType());
        assertEquals(targetType, exception.getTargetType());
        assertNull(exception.processor());
    }

    @Test
    public void testWithParserUpdatesProcessor() {
        JsonParser newParser = mock(JsonParser.class);
        InputCoercionException exception = new InputCoercionException(null, "msg", JsonToken.VALUE_NULL, Object.class);

        InputCoercionException result = exception.withParser(newParser);

        assertSame(exception, result); // Fluent API check
        assertSame(newParser, exception.processor());
    }

    @Test
    public void testInheritanceFromStreamReadException() {
        InputCoercionException exception = new InputCoercionException(mockParser, "msg", JsonToken.VALUE_TRUE, Boolean.class);
        assertTrue(exception instanceof StreamReadException);
    }

    @Test
    public void testDifferentInputAndTargetTypes() {
        JsonToken token = JsonToken.VALUE_NUMBER_FLOAT;
        Class<?> clazz = Double.class;

        InputCoercionException exception = new InputCoercionException(mockParser, "float error", token, clazz);

        assertEquals(token, exception.getInputType());
        assertEquals(clazz, exception.getTargetType());
    }
}

