package tools.jackson.core.exc;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import tools.jackson.core.JsonParser;
import tools.jackson.core.TokenStreamLocation;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class StreamReadExceptionTest {

    @Mock
    private JsonParser mockParser;

    @Mock
    private TokenStreamLocation mockLocation;

    @Before
    public void setUp() {
        // Default behavior for mocked parser
        when(mockParser.currentLocation()).thenReturn(mockLocation);
    }

    @Test
    public void testStringConstructor() {
        String msg = "Test message";
        StreamReadException ex = new StreamReadException(msg);
        assertEquals(msg, ex.getMessage());
    }

    @Test
    public void testConstructorWithParserAndMessage() {
        String msg = "Parser error";
        StreamReadException ex = new StreamReadException(mockParser, msg);

        assertEquals(msg, ex.getMessage());
        assertSame(mockParser, ex.processor());
    }

    @Test
    public void testConstructorWithParserMessageAndRootCause() {
        String msg = "Parser error with cause";
        Throwable rootCause = new RuntimeException("root cause");
        StreamReadException ex = new StreamReadException(mockParser, msg, rootCause);

        assertEquals(msg, ex.getMessage());
        assertSame(rootCause, ex.getCause());
        assertSame(mockParser, ex.processor());
    }

    @Test
    public void testConstructorWithParserMessageAndLocation() {
        String msg = "Parser error with location";
        StreamReadException ex = new StreamReadException(mockParser, msg, mockLocation);

        assertEquals(msg, ex.getMessage());
        // Verify location is set via JacksonException behavior
        // Location is non-null by default in JacksonException unless explicitly null
        assertNotNull(ex.getLocation());
        assertSame(mockParser, ex.processor());
    }

    @Test
    public void testConstructorWithParserMessageLocationAndRootCause() {
        String msg = "Full constructor test";
        Throwable rootCause = new IllegalArgumentException("invalid input");
        StreamReadException ex = new StreamReadException(mockParser, msg, mockLocation, rootCause);

        assertEquals(msg, ex.getMessage());
        assertSame(rootCause, ex.getCause());
        assertSame(mockParser, ex.processor());
    }

    @Test
    public void testWithParser() {
        StreamReadException ex = new StreamReadException("Initial msg");

        // Verify initial state
        assertNull(ex.processor());

        // Test fluent method
        StreamReadException result = ex.withParser(mockParser);

        assertSame(ex, result);
        assertSame(mockParser, ex.processor());
    }

    @Test
    public void testWithParserNull() {
        StreamReadException ex = new StreamReadException("msg");

        StreamReadException result = ex.withParser(null);

        assertSame(ex, result);
        assertNull(result.processor());
    }

    @Test
    public void testProcessorCovariance() {
        // Verify that processor() returns JsonParser, not just Object
        StreamReadException ex = new StreamReadException(mockParser, "msg");

        JsonParser parser = ex.processor();
        assertNotNull(parser);
        assertSame(mockParser, parser);
    }

    @Test
    public void testNullParserInConstructor() {
        // When parser is null, _loc returns null, location should be handled gracefully
        StreamReadException ex = new StreamReadException(null, "msg");

        assertEquals("msg", ex.getMessage());
        // processor() might return null or whatever super set.
        // In this case, super constructor is called with null processor.
    }
}

