        String msg = "Parser error with cause";
        Throwable rootCause = new RuntimeException("root cause");
        StreamReadException ex = new StreamReadException(null, msg, rootCause);

        assertEquals(msg, ex.getMessage());
        assertSame(rootCause, ex.getCause());
        assertNull(ex.processor());
    }

    @Test
    public void testConstructorWithParserMessageAndLocation() {
        String msg = "Parser error with location";
        // Use a real TokenStreamLocation instance
        TokenStreamLocation location = new TokenStreamLocation(
            tools.jackson.core.util.ContentReference.unknown(), 0L, 1, 1);
        StreamReadException ex = new StreamReadException(null, msg, location);

        assertEquals(msg, ex.getMessage());
        assertNotNull(ex.getLocation());
        assertNull(ex.processor());
    }

    @Test
    public void testConstructorWithParserMessageLocationAndRootCause() {
        String msg = "Full constructor test";
        Throwable rootCause = new IllegalArgumentException("invalid input");
        TokenStreamLocation location = new TokenStreamLocation(
            tools.jackson.core.util.ContentReference.unknown(), 0L, 1, 1);
        StreamReadException ex = new StreamReadException(null, msg, location, rootCause);

        assertEquals(msg, ex.getMessage());
        assertSame(rootCause, ex.getCause());
        assertNull(ex.processor());
    }

    @Test
    public void testWithParser() {
        StreamReadException ex = new StreamReadException("Initial msg");

        // Verify initial state
        assertNull(ex.processor());

        // Test fluent method - need a JsonParser, use a simple approach
        // Use anonymous class or concrete implementation if available
        JsonParser parser = createMinimalJsonParser();
        StreamReadException result = ex.withParser(parser);

        assertSame(ex, result);
        assertSame(parser, ex.processor());
    }

    @Test
    public void testWithParserNull() {
        StreamReadException ex = new StreamReadException("msg");

        StreamReadException result = ex.withParser(null);

        assertSame(ex, result);
        assertNull(result.processor());
