import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

import tools.jackson.core.JsonGenerator;

@RunWith(MockitoJUnitRunner.class)
public class StreamWriteExceptionTest {

    @Test
    public void testConstructorWithRootCause() {
        Throwable rootCause = new RuntimeException("root cause");

        StreamWriteException exc = new StreamWriteException(null, rootCause);

        assertNull(exc.processor());
        assertSame(rootCause, exc.getCause());
    }

    @Test
    public void testConstructorWithMessage() {
        String msg = "test error message";

        StreamWriteException exc = new StreamWriteException(null, msg);

        assertEquals(msg, exc.getMessage());
        assertNull(exc.processor());
    }

    @Test
    public void testConstructorWithMessageAndRootCause() {
        String msg = "test error message";
        Throwable rootCause = new RuntimeException("root cause");

        StreamWriteException exc = new StreamWriteException(null, msg, rootCause);

        assertEquals(msg, exc.getMessage());
        assertSame(rootCause, exc.getCause());
        assertNull(exc.processor());
    }

    @Test
    public void testWithGenerator() {
        JsonGenerator newGenerator = mock(JsonGenerator.class);

        StreamWriteException exc = new StreamWriteException(null, "initial message");
        assertNull(exc.processor());

        StreamWriteException result = exc.withGenerator(newGenerator);

        assertSame(newGenerator, exc.processor());
        assertSame(exc, result); // fluent method returns this
    }

    @Test
    public void testProcessorReturnsJsonGenerator() {
        JsonGenerator generator = mock(JsonGenerator.class);

        StreamWriteException exc = new StreamWriteException(generator, "message");

        // Verify that processor() returns the same instance and is of type JsonGenerator
        Object processor = exc.processor();
        assertSame(generator, processor);
    }

    @Test
    public void testProcessorAfterWithGenerator() {
        JsonGenerator originalGenerator = mock(JsonGenerator.class);
        JsonGenerator newGenerator = mock(JsonGenerator.class);

        StreamWriteException exc = new StreamWriteException(originalGenerator, "message");
        exc.withGenerator(newGenerator);

        // Verify processor returns the new generator
        Object processor = exc.processor();
        assertSame(newGenerator, processor);
    }

    @Test
    public void testWithGeneratorChaining() {
        JsonGenerator g1 = mock(JsonGenerator.class);
        JsonGenerator g2 = mock(JsonGenerator.class);
        JsonGenerator g3 = mock(JsonGenerator.class);

        StreamWriteException exc = new StreamWriteException(g1, "message");

        // Test fluent method chaining
        StreamWriteException result = exc.withGenerator(g2).withGenerator(g3);

        assertSame(g3, exc.processor());
        assertSame(exc, result);
    }

    @Test
    public void testConstructorWithNullGenerator() {
        String msg = "error without generator";

        StreamWriteException exc = new StreamWriteException(null, msg);

        assertEquals(msg, exc.getMessage());
        assertNull(exc.processor());
    }

    @Test
    public void testConstructorWithNullMessageAndRootCause() {
        Throwable rootCause = new RuntimeException("root cause");

        StreamWriteException exc = new StreamWriteException(null, rootCause);

        assertSame(rootCause, exc.getCause());
        assertNull(exc.processor());
    }
}

