package tools.jackson.core.filter;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import tools.jackson.core.JsonGenerator;
import tools.jackson.core.TokenStreamContext;
import tools.jackson.core.filter.TokenFilter.Inclusion;

public class FilteringGeneratorDelegateTest {

    private JsonGenerator mockDelegate;
    private TokenFilter mockFilter;
    private FilteringGeneratorDelegate filteringDelegate;

    @Before
    public void setUp() {
        mockDelegate = mock(JsonGenerator.class);
        mockFilter = mock(TokenFilter.class);

        // Default mock behavior to support "Include All" path for easier testing of delegation
        when(mockFilter.filterStartObject()).thenReturn(mockFilter);
        when(mockFilter.filterStartArray()).thenReturn(mockFilter);
        when(mockFilter.includeProperty(anyString())).thenReturn(mockFilter);
        when(mockFilter.includeString(anyString())).thenReturn(true);
        when(mockFilter.includeNumber(anyInt())).thenReturn(true);
        when(mockFilter.includeBoolean(anyBoolean())).thenReturn(true);
        when(mockFilter.includeNull()).thenReturn(true);

        filteringDelegate = new FilteringGeneratorDelegate(
            mockDelegate, 
            mockFilter, 
            Inclusion.INCLUDE_ALL_AND_PATH, 
            true // allowMultipleMatches
        );
    }

    @Test
    public void testGetMatchCountInitiallyZero() {
        assertEquals(0, filteringDelegate.getMatchCount());
    }

    @Test
    public void testGetFilterReturnsRootFilter() {
        assertSame(mockFilter, filteringDelegate.getFilter());
    }

    @Test
    public void testStreamWriteContextReturnsFilterContext() {
