public class TokenFilterContextTest {

    private MockTokenFilter mockFilter;

    @Before
    public void setUp() {
        mockFilter = new MockTokenFilter();
    }

    @Test
    public void testCreateRootContext() {
        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);

        assertNotNull(root);
        assertEquals(TokenStreamContext.TYPE_ROOT, root.typeDesc());
        assertNull(root.getParent());
        assertTrue(root.isStartHandled());
        assertSame(mockFilter, root.getFilter());
        assertEquals(0, root.getNestingDepth());
    }

    @Test
    public void testCreateChildArrayContext() {
        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);
        TokenFilterContext child = root.createChildArrayContext(mockFilter, null, true);

        assertNotNull(child);
        assertSame(root, child.getParent());
        assertEquals(TokenStreamContext.TYPE_ARRAY, child.typeDesc());
        assertTrue(child.isStartHandled());
        assertSame(mockFilter, child.getFilter());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testCreateChildArrayContextReuse() {
        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);
        TokenFilterContext child1 = root.createChildArrayContext(mockFilter, null, true);
        TokenFilterContext child2 = root.createChildArrayContext(mockFilter, null, true);

        assertSame(child1, child2);
    }

    @Test
    public void testCreateChildObjectContext() {
        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);
        TokenFilterContext child = root.createChildObjectContext(mockFilter, null, false);

        assertNotNull(child);
        assertSame(root, child.getParent());
        assertEquals(TokenStreamContext.TYPE_OBJECT, child.typeDesc());
        assertFalse(child.isStartHandled());
        assertSame(mockFilter, child.getFilter());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testCreateChildObjectContextReuse() {
        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);
        TokenFilterContext child1 = root.createChildObjectContext(mockFilter, null, false);
        TokenFilterContext child2 = root.createChildObjectContext(mockFilter, null, false);

        assertSame(child1, child2);
    }

