        TokenFilterContext root = TokenFilterContext.createRootContext(mockFilter);
        TokenFilterContext objectContext = root.createChildObjectContext(mockFilter, null, false);

        TokenFilter result = objectContext.setPropertyName("testProperty");

        assertSame(mockFilter, result);
        assertEquals("testProperty", objectContext.currentName());
        assertTrue(objectContext.hasCurrentName());
    }

