        assertEquals('n', escapes[0x0A]); // newline - 'n' (110)
        assertEquals('r', escapes[0x0D]); // carriage return - 'r' (114)

        // Rest of control chars 14-31 should be ESCAPE_STANDARD
        for (int i = 14; i < 32; i++) {
