    @Test
    public void testAllocAndReleaseRoundTrip() {
        byte[] readBuffer = new byte[100];
        byte[] writeBuffer = new byte[100];
        byte[] base64Buffer = new byte[100];
        char[] tokenBuffer = new char[100];
        char[] concatBuffer = new char[100];
        char[] nameCopyBuffer = new char[100];

        when(bufferRecycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER)).thenReturn(readBuffer);
        when(bufferRecycler.allocByteBuffer(BufferRecycler.BYTE_WRITE_ENCODING_BUFFER)).thenReturn(writeBuffer);
        when(bufferRecycler.allocByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER)).thenReturn(base64Buffer);
        when(bufferRecycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER)).thenReturn(tokenBuffer);
        when(bufferRecycler.allocCharBuffer(BufferRecycler.CHAR_CONCAT_BUFFER)).thenReturn(concatBuffer);
        when(bufferRecycler.allocCharBuffer(BufferRecycler.CHAR_NAME_COPY_BUFFER, 100)).thenReturn(nameCopyBuffer);

        byte[] allocatedRead = ioContext.allocReadIOBuffer();
        byte[] allocatedWrite = ioContext.allocWriteEncodingBuffer();
        byte[] allocatedBase64 = ioContext.allocBase64Buffer();
        char[] allocatedToken = ioContext.allocTokenBuffer();
        char[] allocatedConcat = ioContext.allocConcatBuffer();
        char[] allocatedNameCopy = ioContext.allocNameCopyBuffer(100);

        ioContext.releaseReadIOBuffer(allocatedRead);
        ioContext.releaseWriteEncodingBuffer(allocatedWrite);
        ioContext.releaseBase64Buffer(allocatedBase64);
        ioContext.releaseTokenBuffer(allocatedToken);
        ioContext.releaseConcatBuffer(allocatedConcat);
        ioContext.releaseNameCopyBuffer(allocatedNameCopy);

        verify(bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER, readBuffer);
        verify(bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_WRITE_ENCODING_BUFFER, writeBuffer);
        verify(bufferRecycler).releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, base64Buffer);
        verify(bufferRecycler).releaseCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER, tokenBuffer);
        verify(bufferRecycler).releaseCharBuffer(BufferRecycler.CHAR_CONCAT_BUFFER, concatBuffer);
        verify(bufferRecycler).releaseCharBuffer(BufferRecycler.CHAR_NAME_COPY_BUFFER, nameCopyBuffer);
    }

    @Test
    public void testAllocBufferAfterCloseThrows() {
        ioContext.close();

        try {
            ioContext.allocReadIOBuffer();
            fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            assertTrue(e.getMessage().contains("second time"));
        }
    }

    @Test
    public void testContentReferenceAccessor() {
        assertSame(contentReference, ioContext.contentReference());
    }

    @Test
    public void testStreamReadConstraintsAccessor() {
