package tools.jackson.core.io;

import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.*;

public class JsonStringEncoderTest {

    private final JsonStringEncoder encoder = JsonStringEncoder.getInstance();

    // Tests for quoteAsCharArray

    @Test
    public void testQuoteAsCharArrayEmpty() {
        char[] result = encoder.quoteAsCharArray("");
        assertArrayEquals(new char[0], result);
    }

    @Test
    public void testQuoteAsCharArrayNoEscaping() {
        char[] result = encoder.quoteAsCharArray("Abc123");
        assertArrayEquals("Abc123".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayQuotes() {
        char[] result = encoder.quoteAsCharArray("a\"b");
        assertArrayEquals("a\\\"b".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayBackslash() {
        char[] result = encoder.quoteAsCharArray("a\\b");
        assertArrayEquals("a\\\\b".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayNewline() {
        // JSON newline escape
        char[] result = encoder.quoteAsCharArray("a\nb");
        assertArrayEquals("a\\nb".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayTab() {
        // JSON tab escape
        char[] result = encoder.quoteAsCharArray("a\tb");
        assertArrayEquals("a\\tb".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayControlChar() {
        // JSON unicode control char escape (e.g. 0x01)
        char[] result = encoder.quoteAsCharArray("a\u0001b");
        assertArrayEquals("a\\u0001b".toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArrayMixed() {
        String input = "Hello \"World\"\\\n!";
        String expected = "Hello \\\"World\\\"\\\\\\n!";
        char[] result = encoder.quoteAsCharArray(input);
        assertArrayEquals(expected.toCharArray(), result);
    }

    @Test
    public void testQuoteAsCharArraySurrogates() {
        // Surrogates should be preserved in char array output
        String input = "😀";
        char[] result = encoder.quoteAsCharArray(input);
        assertEquals(input, new String(result));
    }

    // Tests for quoteAsString

    @Test
    public void testQuoteAsStringBasic() {
        StringBuilder sb = new StringBuilder();
        encoder.quoteAsString("test", sb);
        assertEquals("test", sb.toString());
    }

    @Test
    public void testQuoteAsStringEscaping() {
        StringBuilder sb = new StringBuilder();
        encoder.quoteAsString("a\"b\nc", sb);
        assertEquals("a\\\"b\\nc", sb.toString());
    }

    // Tests for quoteAsUTF8

    @Test
    public void testQuoteAsUTF8Empty() {
        byte[] result = encoder.quoteAsUTF8("");
        assertEquals(0, result.length);
    }

    @Test
    public void testQuoteAsUTF8Ascii() {
        byte[] result = encoder.quoteAsUTF8("abc");
        assertEquals("abc", new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testQuoteAsUTF8Escaped() {
        byte[] result = encoder.quoteAsUTF8("a\"b");
        assertEquals("a\\\"b", new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testQuoteAsUTF8Unicode() {
        // 2-byte UTF-8 char (e.g. Euro sign)
        String input = "€";
        byte[] result = encoder.quoteAsUTF8(input);
        // Should be UTF-8 encoded content (not escaped to unicode code points)
        assertEquals(input, new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testQuoteAsUTF8Surrogate() {
        // 4-byte UTF-8 char (Emoji)
        String input = "😀";
        byte[] result = encoder.quoteAsUTF8(input);
        assertEquals(input, new String(result, StandardCharsets.UTF_8));
    }

    // Tests for encodeAsUTF8

    @Test
    public void testEncodeAsUTF8Empty() {
        byte[] result = encoder.encodeAsUTF8("");
        assertEquals(0, result.length);
    }

    @Test
    public void testEncodeAsUTF8Ascii() {
        byte[] result = encoder.encodeAsUTF8("abc");
        assertEquals("abc", new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testEncodeAsUTF8DoesNotEscapeQuotes() {
        // Key difference from quote*: does NOT escape quotes
        byte[] result = encoder.encodeAsUTF8("a\"b");
        assertEquals("a\"b", new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testEncodeAsUTF8Unicode() {
        String input = "日本語";
        byte[] result = encoder.encodeAsUTF8(input);
        assertEquals(input, new String(result, StandardCharsets.UTF_8));
    }

    @Test
    public void testEncodeAsUTF8Surrogate() {
        String input = "😀";
        byte[] result = encoder.encodeAsUTF8(input);
        assertEquals(input, new String(result, StandardCharsets.UTF_8));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEncodeAsUTF8UnpairedSurrogateThrows() {
        // Unpaired high surrogate should throw
        encoder.encodeAsUTF8("\uD800");
    }

    // Tests for buffer size calculations

    @Test
    public void testInitialCharBufSizeMin() {
        // Very small string should return MIN_CHAR_BUFFER_SIZE
        int size = JsonStringEncoder._initialCharBufSize(1);
        assertEquals(JsonStringEncoder.MIN_CHAR_BUFFER_SIZE, size);
    }

    @Test
    public void testInitialCharBufSizeGrowth() {
        // String large enough to expand but under max
        int size = JsonStringEncoder._initialCharBufSize(1000);
        assertTrue(size > 1000);
        assertTrue(size <= JsonStringEncoder.MAX_CHAR_BUFFER_SIZE);
    }

    @Test
    public void testInitialCharBufSizeMax() {
        // String huge should be capped
        int size = JsonStringEncoder._initialCharBufSize(100000);
        assertEquals(JsonStringEncoder.MAX_CHAR_BUFFER_SIZE, size);
    }

    @Test
    public void testInitialByteBufSizeMin() {
        int size = JsonStringEncoder._initialByteBufSize(1);
        assertEquals(JsonStringEncoder.MIN_BYTE_BUFFER_SIZE, size);
    }

    @Test
    public void testInitialByteBufSizeGrowth() {
        int size = JsonStringEncoder._initialByteBufSize(1000);
        assertTrue(size > 1000);
        assertTrue(size <= JsonStringEncoder.MAX_BYTE_BUFFER_SIZE);
    }

    @Test
    public void testInitialByteBufSizeMax() {
        int size = JsonStringEncoder._initialByteBufSize(100000);
        assertEquals(JsonStringEncoder.MAX_BYTE_BUFFER_SIZE, size);
    }
}

