package tools.jackson.core.io;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.IOException;
import java.io.InputStream;

import org.junit.Before;
import org.junit.Test;

public class MergedStreamTest {

    private IOContext mockContext;
    private InputStream mockInnerStream;
    private byte[] buffer;

    @Before
    public void setUp() {
        mockContext = mock(IOContext.class);
        mockInnerStream = mock(InputStream.class);
        buffer = new byte[]{1, 2, 3, 4, 5};
    }

    @Test
    public void testReadFromBufferUntilExhausted() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 5);

        assertEquals(5, stream.available());
        assertEquals(1, stream.read());
        assertEquals(4, stream.available());
        assertEquals(2, stream.read());
        assertEquals(3, stream.read());
        assertEquals(2, stream.read());
        assertEquals(1, stream.read());
        assertEquals(0, stream.available());
    }

    @Test
    public void testSwitchToUnderlyingStreamAfterBufferExhausted() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 3);

        assertEquals(1, stream.read());
        assertEquals(2, stream.read());
        assertEquals(3, stream.read());

        when(mockInnerStream.read()).thenReturn(10);
        assertEquals(10, stream.read());
    }

    @Test
    public void testReadByteArrayFromBuffer() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 5);
        byte[] dest = new byte[3];

        int read = stream.read(dest);

        assertEquals(3, read);
        assertEquals(1, dest[0]);
        assertEquals(2, dest[1]);
        assertEquals(2, dest[2]);
    }

