    @Test
    public void testBufferNotReleasedUntilExhausted() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 5);

        stream.read();
        stream.read();

        verify(mockContext, never()).releaseReadIOBuffer(buffer);
    }

    @Test
    public void testBufferReleasedWhenExhausted() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 2);

        stream.read();
        stream.read();

        verify(mockContext).releaseReadIOBuffer(buffer);
    }

    @Test
    public void testBufferReleasedAfterPartialRead() throws IOException {
        byte[] buf = new byte[]{1, 2, 3};
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buf, 0, 3);
        byte[] dest = new byte[3];

        stream.read(dest);

        verify(mockContext).releaseReadIOBuffer(buf);
    }

    @Test
    public void testNullContextDoesNotCrash() throws IOException {
        MergedStream stream = new MergedStream(null, mockInnerStream, buffer, 0, 2);

        stream.close();

        verify(mockInnerStream).close();
    }

    @Test
    public void testReadFromNonZeroStart() throws IOException {
        byte[] buf = new byte[]{0, 1, 2, 3, 4};
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buf, 2, 4);

        assertEquals(2, stream.available());
        assertEquals(2, stream.read());
        assertEquals(3, stream.read());

        when(mockInnerStream.read()).thenReturn(-1);
        assertEquals(-1, stream.read());
        assertEquals(0, stream.available());
    }

    @Test
    public void testCloseMultipleTimesIsIdempotent() throws IOException {
        MergedStream stream = new MergedStream(mockContext, mockInnerStream, buffer, 0, 5);

        stream.close();
        stream.close();

        verify(mockContext).releaseReadIOBuffer(buffer);
        verify(mockInnerStream, times(2)).close();
    }
}

