    // Test toString for double and float
    @Test
    public void testToStringDoubleDefault() {
        assertEquals(Double.toString(0.0), toString(0.0));
        assertEquals(Double.toString(1.0), toString(1.0));
        assertEquals(Double.toString(-1.0), toString(-1.0));
        assertEquals(Double.toString(123.456), toString(123.456));
        assertEquals(Double.toString(Double.POSITIVE_INFINITY), toString(Double.POSITIVE_INFINITY));
        assertEquals(Double.toString(Double.NEGATIVE_INFINITY), toString(Double.NEGATIVE_INFINITY));
        assertEquals(Double.toString(Double.NaN), toString(Double.NaN));
        assertEquals(Double.toString(-0.0), toString(-0.0));
    }

    @Test
    public void testToStringDoubleUseFastWriter() {
        double[] values = {0.0, 1.0, -1.0, 123.456, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, Double.NaN, -0.0};
        for (double v : values) {
            String result = toString(v, true);
            assertNotNull(result);
            assertFalse(result.isEmpty());
            // verify that parsing yields the same value (NaN != NaN so handle separately)
            if (Double.isNaN(v)) {
                assertTrue(Double.isNaN(Double.parseDouble(result)));
            } else {
                assertEquals(v, Double.parseDouble(result), 0.0);
            }
        }
    }

    @Test
    public void testToStringFloatDefault() {
        assertEquals(Float.toString(0.0f), toString(0.0f));
        assertEquals(Float.toString(1.0f), toString(1.0f));
        assertEquals(Float.toString(-1.0f), toString(-1.0f));
        assertEquals(Float.toString(123.456f), toString(123.456f));
        assertEquals(Float.toString(Float.POSITIVE_INFINITY), toString(Float.POSITIVE_INFINITY));
        assertEquals(Float.toString(Float.NEGATIVE_INFINITY), toString(Float.NEGATIVE_INFINITY));
        assertEquals(Float.toString(Float.NaN), toString(Float.NaN));
        assertEquals(Float.toString(-0.0f), toString(-0.0f));
    }

    @Test
    public void testToStringFloatUseFastWriter() {
        float[] values = {0.0f, 1.0f, -1.0f, 123.456f, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.NaN, -0.0f};
        for (float v : values) {
            String result = toString(v, true);
            assertNotNull(result);
            assertFalse(result.isEmpty());
            if (Float.isNaN(v)) {
                assertTrue(Float.isNaN(Float.parseFloat(result)));
            } else {
                assertEquals(v, Float.parseFloat(result), 0.0f);
            }
        }
    }

    // Test notFinite
    @Test
    public void testNotFiniteDouble() {
        assertTrue(notFinite(Double.POSITIVE_INFINITY));
        assertTrue(notFinite(Double.NEGATIVE_INFINITY));
        assertTrue(notFinite(Double.NaN));
        assertFalse(notFinite(0.0));
        assertFalse(notFinite(1.0));
        assertFalse(notFinite(-123.456));
    }

    @Test
    public void testNotFiniteFloat() {
        assertTrue(notFinite(Float.POSITIVE_INFINITY));
        assertTrue(notFinite(Float.NEGATIVE_INFINITY));
        assertTrue(notFinite(Float.NaN));
        assertFalse(notFinite(0.0f));
        assertFalse(notFinite(1.0f));
        assertFalse(notFinite(-123.456f));
    }

    // Helper methods
    private void assertIntToCharArray(int value, String expected) {
        char[] buf = new char[30];
        int off = outputInt(value, buf, 0);
        String result = new String(buf, 0, off);
        assertEquals(expected, result);
        assertEquals(off, result.length());
    }

    private void assertIntToByteArray(int value, String expected) {
        byte[] buf = new byte[30];
        int off = outputInt(value, buf, 0);
        String result = new String(buf, 0, off, StandardCharsets.US_ASCII);
        assertEquals(expected, result);
        assertEquals(off, result.length());
    }

    private void assertLongToCharArray(long value, String expected) {
        char[] buf = new char[40];
        int off = outputLong(value, buf, 0);
        String result = new String(buf, 0, off);
        assertEquals(expected, result);
        assertEquals(off, result.length());
    }

    private void assertLongToByteArray(long value, String expected) {
        byte[] buf = new byte[40];
        int off = outputLong(value, buf, 0);
        String result = new String(buf, 0, off, StandardCharsets.US_ASCII);
        assertEquals(expected, result);
        assertEquals(off, result.length());
