package tools.jackson.core.io;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;

import org.junit.Before;
import org.junit.Test;

public class UTF32ReaderTest {

    private static final int BUFFER_SIZE = 4000;

    private IOContext mockContext;
    private byte[] buffer;

    @Before
    public void setUp() {
        mockContext = mock(IOContext.class);
        buffer = new byte[BUFFER_SIZE];
    }

    private UTF32Reader createReader(InputStream in, boolean bigEndian) {
        return new UTF32Reader(mockContext, in, true, buffer, 0, 0, bigEndian);
    }

    private UTF32Reader createReader(InputStream in, boolean bigEndian, boolean autoClose) {
        return new UTF32Reader(mockContext, in, autoClose, buffer, 0, 0, bigEndian);
    }

    @Test
    public void testReadSingleCharBigEndian() throws IOException {
        // 'A' = 0x00000041
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 1);

        assertEquals(1, len);
        assertEquals('A', cbuf[0]);

        reader.close();
    }

    @Test
    public void testReadSingleCharLittleEndian() throws IOException {
        // 'A' = 0x00000041
        byte[] data = new byte[] {0x41, 0x00, 0x00, 0x00};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, false);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 1);

        assertEquals(1, len);
        assertEquals('A', cbuf[0]);

        reader.close();
    }

    @Test
    public void testReadMultipleChars() throws IOException {
        // "ABC" = 0x00000041 0x00000042 0x00000043
        byte[] data = new byte[] {
            0x00, 0x00, 0x00, 0x41,
            0x00, 0x00, 0x00, 0x42,
            0x00, 0x00, 0x00, 0x43
        };
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 3);

        assertEquals(3, len);
        assertEquals('A', cbuf[0]);
        assertEquals('B', cbuf[1]);
        assertEquals('C', cbuf[2]);

        reader.close();
    }

    @Test
    public void testReadReturnsMinusOneOnEOF() throws IOException {
        // Empty input
        byte[] data = new byte[0];
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 1);

        assertEquals(-1, len);

        reader.close();
    }

    @Test
    public void testReadSurrogatePair() throws IOException {
        // U+1D11E = MUSICAL SYMBOL G CLEF, requires surrogate pair
        // Encoded as: 0x0001D11E
        // High surrogate: 0xD834, Low surrogate: 0xDD1E
        byte[] data = new byte[] {0x00, 0x01, (byte) 0xD1, 0x1E};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 2);

        assertEquals(2, len);
        // High surrogate
        assertEquals(0xD834, cbuf[0]);
        // Low surrogate
        assertEquals(0xDD1E, cbuf[1]);

        reader.close();
    }

    @Test
    public void testReadSurrogatePairPartial() throws IOException {
        // Same as above but only room for one char in output
        byte[] data = new byte[] {0x00, 0x01, (byte) 0xD1, 0x1E};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 1);

        assertEquals(1, len);
        // High surrogate stored, low surrogate in buffer
        assertEquals(0xD834, cbuf[0]);

        // Read second character
        len = reader.read(cbuf, 0, 1);
        assertEquals(1, len);
        assertEquals(0xDD1E, cbuf[0]);

        reader.close();
    }

    @Test(expected = CharConversionException.class)
    public void testInvalidCharBeyondMaxUnicode() throws IOException {
        // U+110000 - beyond 0x10FFFF
        byte[] data = new byte[] {0x00, 0x11, 0x00, 0x00};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        reader.read(cbuf, 0, 1);

        reader.close();
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testReadWithInvalidStart() throws IOException {
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        reader.read(cbuf, -1, 1);

        reader.close();
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testReadWithInvalidLength() throws IOException {
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        reader.read(cbuf, 0, -1);

        reader.close();
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testReadBeyondBuffer() throws IOException {
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        char[] cbuf = new char[10];
        reader.read(cbuf, 8, 3);

        reader.close();
    }

    @Test
    public void testReadZeroLength() throws IOException {
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

