    }

    @Test
    public void testReadWithInitialBufferData() throws IOException {
        // Pre-populate buffer with data
        byte[] initialBuffer = new byte[8];
        initialBuffer[0] = 0;
        initialBuffer[1] = 0;
        initialBuffer[2] = 0;
        initialBuffer[3] = 0x41; // 'A'
        initialBuffer[4] = 0;
        initialBuffer[5] = 0;
        initialBuffer[6] = 0;
        initialBuffer[7] = 0x42; // 'B'

        UTF32Reader reader = new UTF32Reader(mockContext, null, false, initialBuffer, 0, 8, true);

        char[] cbuf = new char[10];
        int len = reader.read(cbuf, 0, 2);

        assertEquals(2, len);
        assertEquals('A', cbuf[0]);
        assertEquals('B', cbuf[1]);

        reader.close();
    }

    @Test
    public void testCloseWithAutoCloseTrue() throws IOException {
        InputStream mockIn = mock(InputStream.class);

        UTF32Reader reader = createReader(mockIn, true, true);

        reader.close();

        verify(mockIn).close();
    }

    @Test
    public void testCloseWithAutoCloseFalse() throws IOException {
        InputStream mockIn = mock(InputStream.class);

        UTF32Reader reader = createReader(mockIn, true, false);

        reader.close();

        verify(mockIn, never()).close();
    }

    @Test
    public void testCloseMultipleTimes() throws IOException {
        byte[] data = new byte[] {0x00, 0x00, 0x00, 0x41};
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        reader.close();
        // Second close should not throw
