    @Test
    public void testReadSingleCharMethodReturnsMinusOneAtEOF() throws IOException {
        byte[] data = new byte[0];
        ByteArrayInputStream inputStream = new ByteArrayInputStream(data);

        UTF32Reader reader = createReader(inputStream, true);

        int ch = reader.read();

        assertEquals(-1, ch);

        reader.close();
    }

    @Test
    public void testBufferLoadWhenDataSpansMultipleReads() throws IOException {
        // Create more data than fits in initial buffer
        byte[] data = new byte[100];
        for (int i = 0; i < 25; i++) {
            data[i * 4] = 0;
            data[i * 4 + 1] = 0;
            data[i * 4 + 2] = 0;
            data[i * 4 + 3] = (byte) ('A' + i);
