import java.io.Writer;

import org.junit.Before;
import org.junit.Test;

public class UTF8WriterTest {

    private IOContext mockContext;
    private ByteArrayOutputStream outputStream;
    private byte[] allocatedBuffer;
    private UTF8Writer writer;

    @Before
    public void setUp() {
        mockContext = mock(IOContext.class);
        outputStream = new ByteArrayOutputStream();
        // Allocate a reasonable buffer size for testing
        allocatedBuffer = new byte[1024];
        when(mockContext.allocWriteEncodingBuffer()).thenReturn(allocatedBuffer);
    }

    private void createWriter() throws IOException {
        writer = new UTF8Writer(mockContext, outputStream);
    }

    @Test
    public void testWriteAsciiCharacter() throws IOException {
        createWriter();
        writer.write('A');
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x41}, result);
    }

    @Test
    public void testWriteAsciiString() throws IOException {
        createWriter();
        writer.write("Hello");
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x48, 0x65, 0x6C, 0x6C, 0x6F}, result);
    }

    @Test
    public void testWriteTwoByteCharacter() throws IOException {
        createWriter();
        // Character 0x00A9 (copyright sign) - 2-byte UTF-8: 0xC2 0xA9
        writer.write('\u00A9');
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{(byte)0xC2, (byte)0xA9}, result);
    }

    @Test
    public void testWriteThreeByteCharacter() throws IOException {
        createWriter();
        // Character 0x20AC (euro sign) - 3-byte UTF-8: 0xE2 0x82 0xAC
        writer.write('\u20AC');
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{(byte)0xE2, (byte)0x82, (byte)0xAC}, result);
    }

    @Test
    public void testWriteSurrogatePair() throws IOException {
        createWriter();
        // Character 0x1D11E (musical G clef) - surrogate pair in UTF-16
        // Encodes as 4-byte UTF-8: 0xF0 0x9D 0x84 0x9E
        char[] chars = Character.toChars(0x1D11E);
        writer.write(chars);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{(byte)0xF0, (byte)0x9D, (byte)0x84, (byte)0x9E}, result);
    }

    @Test
    public void testWriteSurrogatePairFromString() throws IOException {
        createWriter();
        String str = new String(Character.toChars(0x1D11E));
        writer.write(str);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{(byte)0xF0, (byte)0x9D, (byte)0x84, (byte)0x9E}, result);
    }

    @Test
    public void testWriteCharArray() throws IOException {
        createWriter();
        char[] chars = new char[]{'A', 'B', 'C'};
        writer.write(chars);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x41, 0x42, 0x43}, result);
    }

    @Test
    public void testWriteCharArrayPortion() throws IOException {
        createWriter();
        char[] chars = new char[]{'A', 'B', 'C', 'D', 'E'};
        writer.write(chars, 1, 3);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x42, 0x43, 0x44}, result);
    }

    @Test
    public void testWriteStringPortion() throws IOException {
        createWriter();
        writer.write("ABCDE", 1, 3);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x42, 0x43, 0x44}, result);
    }

    @Test
    public void testWriteSingleCharString() throws IOException {
        createWriter();
        writer.write("A");
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x41}, result);
    }

    @Test
    public void testAppendChar() throws IOException {
        createWriter();
        Writer result = writer.append('X');
        assertSame(writer, result);
        writer.flush();
        byte[] bytes = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x58}, bytes);
    }

    @Test
    public void testFlushWithoutWriting() throws IOException {
        createWriter();
        writer.flush();
        // Should not throw any exception
    }

    @Test
    public void testCloseWithoutWriting() throws IOException {
        createWriter();
        writer.close();
        verify(mockContext).close();
    }

    @Test
    public void testCloseAfterWriting() throws IOException {
        createWriter();
        writer.write("Test");
        writer.close();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x54, 0x65, 0x73, 0x74}, result);
    }

    @Test(expected = IOException.class)
    public void testInvalidSurrogateSecondPart() throws IOException {
        createWriter();
        // Write first surrogate (0xD800) then try to write an invalid second part (0x0041)
        writer.write(0xD800); // First part of surrogate
        writer.write(0x0041); // Invalid second part - not in surrogate range
    }

    @Test(expected = IOException.class)
    public void testInvalidSurrogateSecondPartTooHigh() throws IOException {
        createWriter();
        // Write first surrogate then try to write second part outside valid range
        writer.write(0xD800);
        writer.write(0xE000); // Not a valid second surrogate
    }

    @Test(expected = IOException.class)
    public void testSecondSurrogateWithoutFirst() throws IOException {
        createWriter();
        // Try to write a second surrogate without a first
        writer.write(0xDC00);
    }

    @Test(expected = IOException.class)
    public void testCodePointBeyondMax() throws IOException {
        createWriter();
        // Write code point beyond 0x10FFFF
        writer.write(0x110000);
    }

    @Test
    public void testBufferExpansion() throws IOException {
        // Create a small buffer to force buffer writes
        when(mockContext.allocWriteEncodingBuffer()).thenReturn(new byte[8]);
        createWriter();
        // Write more than 4 bytes (buffer size minus 4)
        writer.write("ABCDEFGHIJKLMNOP"); // 16 chars, all ASCII
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertEquals(16, result.length);
        for (int i = 0; i < 16; i++) {
            assertEquals((byte)('A' + i), result[i]);
        }
    }

    @Test
    public void testMixedAsciiAndMultiByte() throws IOException {
        createWriter();
        writer.write("A\u00A9B"); // ASCII, 2-byte, ASCII
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // A (0x41) + © (0xC2 0xA9) + B (0x42)
        assertArrayEquals(new byte[]{0x41, (byte)0xC2, (byte)0xA9, 0x42}, result);
    }

    @Test
    public void testSurrogatePairInMiddleOfString() throws IOException {
        createWriter();
        String str = "A" + new String(Character.toChars(0x1D11E)) + "B";
        writer.write(str);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // A (0x41) + 𝄞 (0xF0 0x9D 0x84 0x9E) + B (0x42)
        byte[] expected = new byte[]{0x41, (byte)0xF0, (byte)0x9D, (byte)0x84, (byte)0x9E, 0x42};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testWriteIntZero() throws IOException {
        createWriter();
        writer.write(0);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte[]{0x00}, result);
    }

    @Test
    public void testWriteInt127() throws IOException {
        createWriter();
        writer.write(127);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        assertArrayEquals(new byte{(byte)0x7F}, result);
    }

    @Test
    public void testWriteInt128() throws IOException {
        createWriter();
        writer.write(128);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 128 = 0x80, 2-byte UTF-8: 0xC2 0x80
        assertArrayEquals(new byte[]{(byte)0xC2, (byte)0x80}, result);
    }

    @Test
    public void testWriteInt2047() throws IOException {
        createWriter();
        writer.write(2047);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 2047 = 0x7FF, 2-byte UTF-8: 0xDF 0xBF
        assertArrayEquals(new byte[]{(byte)0xDF, (byte)0xBF}, result);
    }

    @Test
    public void testWriteInt2048() throws IOException {
        createWriter();
        writer.write(2048);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 2048 = 0x800, 3-byte UTF-8: 0xE0 0xA0 0x80
        assertArrayEquals(new byte[]{(byte)0xE0, (byte)0xA0, (byte)0x80}, result);
    }

    @Test
    public void testWriteInt65535() throws IOException {
        createWriter();
        writer.write(65535);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 65535 = 0xFFFF, 3-byte UTF-8: 0xEF 0xBF 0xBF
        assertArrayEquals(new byte[]{(byte)0xEF, (byte)0xBF, (byte)0xBF}, result);
    }

    @Test
    public void testWriteInt65536() throws IOException {
        createWriter();
        writer.write(65536);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 65536 = 0x10000, 4-byte UTF-8: 0xF0 0x90 0x80 0x80
        assertArrayEquals(new byte[]{(byte)0xF0, (byte)0x90, (byte)0x80, (byte)0x80}, result);
    }

    @Test
    public void testWriteIntMaxCodepoint() throws IOException {
        createWriter();
        writer.write(0x10FFFF);
        writer.flush();
        byte[] result = outputStream.toByteArray();
        // 0x10FFFF, 4-byte UTF-8: 0xF4 0x8F 0xBF 0xBF
        assertArrayEquals(new byte[]{(byte)0xF4, (byte)0x8F, (byte)0xBF, (byte)0xBF}, result);
    }

    @Test
    public void testSurrogateConstants() {
        assertEquals(0xD800, UTF8Writer.SURR1_FIRST);
        assertEquals(0xDBFF, UTF8Writer.SURR1_LAST);
        assertEquals(0xDC00, UTF8Writer.SURR2_FIRST);
        assertEquals(0xDFFF, UTF8Writer.SURR2_LAST);
    }

    @Test
    public void testCloseReleasesBuffer() throws IOException {
        createWriter();
        writer.close();
        verify(mockContext).releaseWriteEncodingBuffer(allocatedBuffer);
    }
}

