import org.junit.Test;
import static org.junit.Assert.*;

public class DoubleToDecimalTest {

    @Test
    public void testPositiveZero() {
        assertEquals("0.0", DoubleToDecimal.toString(0.0));
    }

    @Test
    public void testNegativeZero() {
        assertEquals("-0.0", DoubleToDecimal.toString(-0.0));
    }

    @Test
    public void testPositiveInfinity() {
        assertEquals("Infinity", DoubleToDecimal.toString(Double.POSITIVE_INFINITY));
    }

    @Test
    public void testNegativeInfinity() {
        assertEquals("-Infinity", DoubleToDecimal.toString(Double.NEGATIVE_INFINITY));
    }

    @Test
    public void testNaN() {
        assertEquals("NaN", DoubleToDecimal.toString(Double.NaN));
    }

    @Test
    public void testIntegerOne() {
        assertEquals("1.0", DoubleToDecimal.toString(1.0));
    }

    @Test
    public void testNegativeInteger() {
        assertEquals("-1.0", DoubleToDecimal.toString(-1.0));
    }

    @Test
    public void testTen() {
        assertEquals("10.0", DoubleToDecimal.toString(10.0));
    }

    @Test
    public void testHundred() {
        assertEquals("100.0", DoubleToDecimal.toString(100.0));
    }

    @Test
    public void testOneTenth() {
        assertEquals("0.1", DoubleToDecimal.toString(0.1));
    }

    @Test
    public void testOneFifth() {
        assertEquals("0.2", DoubleToDecimal.toString(0.2));
    }

    @Test
    public void testOneThird() {
        // 1/3 is 0.33333...
        // Double representation is approximate.
        // Standard output is "0.3333333333333333"
        assertEquals("0.3333333333333333", DoubleToDecimal.toString(1.0 / 3.0));
    }

    @Test
    public void testLargePlain() {
        // 10^6
        assertEquals("1000000.0", DoubleToDecimal.toString(1e6));
    }

    @Test
    public void testLargeScientificBoundary() {
        // 10^7
        assertEquals("1.0E7", DoubleToDecimal.toString(1e7));
    }

    @Test
    public void testLargeScientific() {
        // 10^20
        assertEquals("1.0E20", DoubleToDecimal.toString(1e20));
    }

    @Test
    public void testSmallPlain() {
        // 10^-3
        assertEquals("0.001", DoubleToDecimal.toString(1e-3));
    }

    @Test
    public void testSmallScientificBoundary() {
        // 10^-4
        assertEquals("1.0E-4", DoubleToDecimal.toString(1e-4));
    }

    @Test
    public void testSmallScientific() {
        // 10^-20
        assertEquals("1.0E-20", DoubleToDecimal.toString(1e-20));
    }

    @Test
    public void testMaxValue() {
        assertEquals("1.7976931348623157E308", DoubleToDecimal.toString(Double.MAX_VALUE));
    }

    @Test
    public void testMinValue() {
        assertEquals("4.9E-324", DoubleToDecimal.toString(Double.MIN_VALUE));
    }

    @Test
    public void testMinNormal() {
        assertEquals("2.2250738585072014E-308", DoubleToDecimal.toString(Double.MIN_NORMAL));
    }

    @Test
    public void testPrecisionLimit() {
        double v = 1.234567890123456789;
        assertEquals("1.2345678901234567", DoubleToDecimal.toString(v));
    }

    @Test
    public void testVeryLargeNumber() {
        // Near Max Value
        double v = 1.7976931348623157E308;
        assertEquals("1.7976931348623157E308", DoubleToDecimal.toString(v));
    }
}

