package tools.jackson.core.io.schubfach;

import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtilsTest {

    @Test
    public void testPow10() {
        assertEquals(1L, MathUtils.pow10(0));
        assertEquals(10L, MathUtils.pow10(1));
        assertEquals(100L, MathUtils.pow10(2));
        assertEquals(1000L, MathUtils.pow10(3));
        assertEquals(10000L, MathUtils.pow10(4));
        assertEquals(100000L, MathUtils.pow10(5));
        assertEquals(1000000L, MathUtils.pow10(6));
        assertEquals(10000000L, MathUtils.pow10(7));
        assertEquals(100000000L, MathUtils.pow10(8));
        assertEquals(1000000000L, MathUtils.pow10(9));
        assertEquals(10000000000L, MathUtils.pow10(10));
        assertEquals(100000000000L, MathUtils.pow10(11));
        assertEquals(1000000000000L, MathUtils.pow10(12));
        assertEquals(10000000000000L, MathUtils.pow10(13));
        assertEquals(100000000000000L, MathUtils.pow10(14));
        assertEquals(1000000000000000L, MathUtils.pow10(15));
        assertEquals(10000000000000000L, MathUtils.pow10(16));
        assertEquals(100000000000000000L, MathUtils.pow10(17));
    }

    @Test
    public void testFlog10pow2() {
        // Test some known values
        // e=0: floor(log10(1)) = 0
        assertEquals(0, MathUtils.flog10pow2(0));
        // e=1: floor(log10(2)) = 0
        assertEquals(0, MathUtils.flog10pow2(1));
        // e=2: floor(log10(4)) = 0
        assertEquals(0, MathUtils.flog10pow2(2));
        // e=3: floor(log10(8)) = 0
        assertEquals(0, MathUtils.flog10pow2(3));
        // e=10: floor(log10(1024)) = 3
        assertEquals(3, MathUtils.flog10pow2(10));
        // e=-1: floor(log10(0.5)) = -1
        assertEquals(-1, MathUtils.flog10pow2(-1));
    }

    @Test
    public void testFlog10threeQuartersPow2() {
        // e=0: floor(log10(0.75)) = -1
        assertEquals(-1, MathUtils.flog10threeQuartersPow2(0));
        // e=1: floor(log10(1.5)) = 0
        assertEquals(0, MathUtils.flog10threeQuartersPow2(1));
        // e=2: floor(log10(3)) = 0
        assertEquals(0, MathUtils.flog10threeQuartersPow2(2));
    }

    @Test
    public void testFlog2pow10() {
        // e=0: floor(log2(1)) = 0
        assertEquals(0, MathUtils.flog2pow10(0));
        // e=1: floor(log2(10)) = 3
        assertEquals(3, MathUtils.flog2pow10(1));
        // e=2: floor(log2(100)) = 6
        assertEquals(6, MathUtils.flog2pow10(2));
        // e=3: floor(log2(1000)) = 9
        assertEquals(9, MathUtils.flog2pow10(3));
        // e=-1: floor(log2(0.1)) = -4
        assertEquals(-4, MathUtils.flog2pow10(-1));
    }

    @Test
    public void testG1AndG0Boundaries() {
        // Test K_MIN
        long g1_min = MathUtils.g1(MathUtils.K_MIN);
        long g0_min = MathUtils.g0(MathUtils.K_MIN);
        assertTrue("g1 at K_MIN should be non-zero", g1_min != 0);
        assertTrue("g0 at K_MIN should be non-zero", g0_min != 0);

        // Test K_MAX
        long g1_max = MathUtils.g1(MathUtils.K_MAX);
        long g0_max = MathUtils.g0(MathUtils.K_MAX);
        assertTrue("g1 at K_MAX should be non-zero", g1_max != 0);
        assertTrue("g0 at K_MAX should be non-zero", g0_max != 0);

        // Test middle value k=0
        long g1_0 = MathUtils.g1(0);
        long g0_0 = MathUtils.g0(0);
        assertTrue("g1 at 0 should be non-zero", g1_0 != 0);
        assertTrue("g0 at 0 should be non-zero", g0_0 != 0);
    }

    // Check constants
    @Test
    public void testConstants() {
        assertEquals(-324, MathUtils.K_MIN);
        assertEquals(292, MathUtils.K_MAX);
        assertEquals(17, MathUtils.H);
    }
}

