package tools.jackson.core.json;

import tools.jackson.core.*;
import tools.jackson.core.exc.JacksonException;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.ByteQuadsCanonicalizer;
import tools.jackson.core.sym.CharsToNameCanonicalizer;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.IOException;
import java.io.InputStream;
import java.io.Reader;
import java.io.StringReader;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class ByteSourceJsonBootstrapperTest {

    private IOContext _context;
    private ByteArrayInputStream _inputStream;
    private static final int BUFFER_SIZE = 8000;

    @Before
    public void setUp() {
        _context = mock(IOContext.class);
        when(_context.allocReadIOBuffer()).thenReturn(new byte[BUFFER_SIZE]);
        when(_context.getEncoding()).thenReturn(JsonEncoding.UTF8);
    }

    // Tests for detectEncoding

    @Test
    public void testDetectEncodingWithEmptyInput() throws JacksonException {
        _inputStream = new ByteArrayInputStream(new byte[0]);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF8, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf8Bom() throws JacksonException {
        // UTF-8 BOM: 0xEF 0xBB 0xBF
        byte[] input = new byte[] {(byte) 0xEF, (byte) 0xBB, (byte) 0xBF, '{'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF8, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf16BeBom() throws JacksonException {
        // UTF-16 BE BOM: 0xFE 0xFF
        byte[] input = new byte[] {(byte) 0xFE, (byte) 0xFF, '{', '}'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF16_BE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf16LeBom() throws JacksonException {
        // UTF-16 LE BOM: 0xFF 0xFE
        byte[] input = new byte[] {(byte) 0xFF, (byte) 0xFE, '{', '}'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF16_LE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf32BeBom() throws JacksonException {
        // UTF-32 BE BOM: 0x00 0x00 0xFE 0xFF
        byte[] input = new byte[] {0x00, 0x00, (byte) 0xFE, (byte) 0xFF};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF32_BE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf32LeBom() throws JacksonException {
        // UTF-32 LE BOM: 0xFF 0xFE 0x00 0x00
        byte[] input = new byte[] {(byte) 0xFF, (byte) 0xFE, 0x00, 0x00};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF32_LE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf32BeNoBom() throws JacksonException {
        // UTF-32 BE without BOM: 0x00 0x00 0x00 ?? (first char is ASCII)
        byte[] input = new byte[] {0x00, 0x00, 0x00, '{'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF32_BE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf32LeNoBom() throws JacksonException {
        // UTF-32 LE without BOM: ?? 0x00 0x00 0x00 (first char is ASCII)
        byte[] input = new byte[] {'{', 0x00, 0x00, 0x00};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF32_LE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf16BeNoBom() throws JacksonException {
        // UTF-16 BE without BOM: 0x00 ?? (first char is ASCII)
        byte[] input = new byte[] {0x00, '{'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF16_BE, encoding);
    }

    @Test
    public void testDetectEncodingWithUtf16LeNoBom() throws JacksonException {
        // UTF-16 LE without BOM: ?? 0x00 (first char is ASCII)
        byte[] input = new byte[] {'{', 0x00};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        assertEquals(JsonEncoding.UTF16_LE, encoding);
    }

    @Test
    public void testDetectEncodingWithValidUtf8NoBom() throws JacksonException {
        // Valid UTF-8 JSON content with no BOM
        byte[] input = "{ \"key\" : \"value\" }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        // Should default to UTF-8
        assertEquals(JsonEncoding.UTF8, encoding);
    }

    // Tests for skipUTF8BOM

    @Test
    public void testSkipUtf8BomWithBom() throws Exception {
        DataInput dataInput = mock(DataInput.class);
        when(dataInput.readUnsignedByte())
            .thenReturn(0xEF)  // First byte of BOM
            .thenReturn(0xBB)  // Second byte of BOM  
            .thenReturn(0xBF)  // Third byte of BOM
            .thenReturn('{');  // Actual content

        int result = ByteSourceJsonBootstrapper.skipUTF8BOM(dataInput);

        assertEquals('{', result);
    }

    @Test
    public void testSkipUtf8BomWithoutBom() throws Exception {
        DataInput dataInput = mock(DataInput.class);
        when(dataInput.readUnsignedByte()).thenReturn('{');  // No BOM, just content

        int result = ByteSourceJsonBootstrapper.skipUTF8BOM(dataInput);

        assertEquals('{', result);
    }

    @Test(expected = JacksonException.class)
    public void testSkipUtf8BomWithInvalidBomFirstByte() throws Exception {
        DataInput dataInput = mock(DataInput.class);
        when(dataInput.readUnsignedByte())
            .thenReturn(0xFF)  // Invalid first byte
            .thenReturn(0xBB); // Second byte

        ByteSourceJsonBootstrapper.skipUTF8BOM(dataInput);
    }

    @Test(expected = JacksonException.class)
    public void testSkipUtf8BomWithInvalidBomSecondByte() throws Exception {
        DataInput dataInput = mock(DataInput.class);
        when(dataInput.readUnsignedByte())
            .thenReturn(0xEF)  // First byte of BOM
            .thenReturn(0xCC)  // Invalid second byte
            .thenReturn(0xBF); // Third byte

        ByteSourceJsonBootstrapper.skipUTF8BOM(dataInput);
    }

    @Test(expected = JacksonException.class)
    public void testSkipUtf8BomWithInvalidBomThirdByte() throws Exception {
        DataInput dataInput = mock(DataInput.class);
        when(dataInput.readUnsignedByte())
            .thenReturn(0xEF)  // First byte of BOM
            .thenReturn(0xBB)  // Second byte of BOM
            .thenReturn(0xCC); // Invalid third byte

        ByteSourceJsonBootstrapper.skipUTF8BOM(dataInput);
    }

    // Tests for constructReader

    @Test
    public void testConstructReaderWithUtf8() throws JacksonException {
        byte[] buffer = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        Reader reader = bootstrapper.constructReader();

        assertNotNull(reader);
        assertTrue(reader instanceof StringReader);
    }

    @Test
    public void testConstructReaderWithSmallInputUsesStringReader() throws JacksonException {
        // Small input (under 8192 bytes) should use StringReader
        byte[] buffer = new byte[100];
        buffer[0] = '{';
        buffer[1] = '}';

        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        Reader reader = bootstrapper.constructReader();

        assertNotNull(reader);
        assertTrue(reader instanceof StringReader);
    }

    @Test
    public void testConstructReaderWithLargeInputUsesInputStreamReader() throws JacksonException {
        // Large input (over 8192 bytes) should use InputStreamReader
        byte[] buffer = new byte[10000];
        buffer[0] = '{';
        buffer[1] = '}';

        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        Reader reader = bootstrapper.constructReader();

        assertNotNull(reader);
        assertTrue(reader instanceof java.io.InputStreamReader);
    }

    @Test
    public void testConstructReaderWithInputStream() throws JacksonException {
        byte[] content = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        _inputStream = new ByteArrayInputStream(content);

        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        Reader reader = bootstrapper.constructReader();

        assertNotNull(reader);
    }

    // Tests for constructParser

    @Test
    public void testConstructParserWithCharsetDetectionEnabled() throws JacksonException {
        byte[] buffer = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        JsonParser parser = bootstrapper.constructParser(
            ObjectReadContext.empty(),
            0,
            JsonFactory.Feature.CHARSET_DETECTION.getMask(),
            ByteQuadsCanonicalizer.createRoot(),
            CharsToNameCanonicalizer.createRoot(),
            0);

        assertNotNull(parser);
    }

    @Test
    public void testConstructParserWithCharsetDetectionDisabled() throws JacksonException {
        byte[] buffer = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        JsonParser parser = bootstrapper.constructParser(
            ObjectReadContext.empty(),
            0,
            0, // CHARSET_DETECTION disabled
            ByteQuadsCanonicalizer.createRoot(),
            CharsToNameCanonicalizer.createRoot(),
            0);

        assertNotNull(parser);
        // Without charset detection, default is UTF-8
    }

    @Test
    public void testConstructParserWithCanonicalizationEnabled() throws JacksonException {
        byte[] buffer = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        JsonParser parser = bootstrapper.constructParser(
            ObjectReadContext.empty(),
            JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask(),
            0,
            ByteQuadsCanonicalizer.createRoot(),
            CharsToNameCanonicalizer.createRoot(),
            0);

        assertNotNull(parser);
        // With UTF-8 and canonicalization enabled, should get UTF8StreamJsonParser
    }

    @Test
    public void testConstructParserReturnsCorrectParserType() throws JacksonException {
        byte[] buffer = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, buffer.length);

        // Without canonicalization, should return ReaderBasedJsonParser for UTF-8
        JsonParser parser = bootstrapper.constructParser(
            ObjectReadContext.empty(),
            0, // No canonicalization
            0,
            ByteQuadsCanonicalizer.createRoot(),
            CharsToNameCanonicalizer.createRoot(),
            0);

        assertNotNull(parser);
        assertTrue(parser instanceof ReaderBasedJsonParser);
    }

    // Tests for constructor with byte array

    @Test
    public void testConstructorWithByteArray() {
        byte[] buffer = new byte[100];
        buffer[0] = '{';
        buffer[1] = '}';

        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 0, 2);

        assertNotNull(bootstrapper);
    }

    @Test
    public void testConstructorWithByteArrayNonZeroOffset() {
        byte[] buffer = new byte[100];
        buffer[10] = '{';
        buffer[11] = '}';

        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(
            _context, buffer, 10, 2);

        assertNotNull(bootstrapper);
    }

    // Tests for context encoding setting

    @Test
    public void testDetectEncodingSetsContextEncoding() throws JacksonException {
        byte[] input = "{ }".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        bootstrapper.detectEncoding();

        verify(_context).setEncoding(JsonEncoding.UTF8);
    }

    @Test
    public void testDetectEncodingWithUtf16SetsContextEncoding() throws JacksonException {
        // UTF-16 LE BOM
        byte[] input = new byte[] {(byte) 0xFF, (byte) 0xFE, '{', '}'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        bootstrapper.detectEncoding();

        verify(_context).setEncoding(JsonEncoding.UTF16_LE);
    }

    // Edge case tests

    @Test
    public void testDetectEncodingWithInsufficientBytes() throws JacksonException {
        // Only 1 byte available
        byte[] input = new byte[] {'{'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        // Should default to UTF-8
        assertEquals(JsonEncoding.UTF8, encoding);
    }

    @Test
    public void testDetectEncodingWithTwoBytesNoBom() throws JacksonException {
        // 2 bytes that don't form a valid UTF-16 BOM but could be UTF-16 content
        byte[] input = new byte[] {0x00, '{'};
        _inputStream = new ByteArrayInputStream(input);
        ByteSourceJsonBootstrapper bootstrapper = new ByteSourceJsonBootstrapper(_context, _inputStream);

        JsonEncoding encoding = bootstrapper.detectEncoding();

        // Should detect as UTF-16 BE
        assertEquals(JsonEncoding.UTF16_BE, encoding);
    }
}

