    public void testIsDupFirstNameReturnsFalse() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        boolean result = detector.isDup("firstName");

        assertFalse(result);
    }

    @Test
    public void testIsDupSecondNameReturnsFalse() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        detector.isDup("firstName");
        boolean result = detector.isDup("secondName");

        assertFalse(result);
    }

    @Test
    public void testIsDupDuplicateFirstNameReturnsTrue() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        detector.isDup("firstName");
        boolean result = detector.isDup("firstName");

        assertTrue(result);
    }

    @Test
    public void testIsDupDuplicateSecondNameReturnsTrue() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        detector.isDup("firstName");
        detector.isDup("secondName");
        boolean result = detector.isDup("secondName");

        assertTrue(result);
    }

    @Test
    public void testIsDupThirdUniqueNameReturnsFalse() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        detector.isDup("firstName");
        detector.isDup("secondName");
        boolean result = detector.isDup("thirdName");

        assertFalse(result);
    }

    @Test
    public void testIsDupDuplicateThirdNameReturnsTrue() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        detector.isDup("firstName");
        detector.isDup("secondName");
        detector.isDup("thirdName");
        boolean result = detector.isDup("thirdName");

        assertTrue(result);
    }

    @Test
    public void testIsDupManyUniqueNames() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        // First two names go to firstName and secondName
        assertFalse(detector.isDup("a"));
        assertFalse(detector.isDup("b"));

        // Third name creates the HashSet
        assertFalse(detector.isDup("c"));

        // More unique names
        assertFalse(detector.isDup("d"));
        assertFalse(detector.isDup("e"));
        assertFalse(detector.isDup("f"));

        // Duplicate should be detected
        assertTrue(detector.isDup("a"));
        assertTrue(detector.isDup("b"));
        assertTrue(detector.isDup("c"));
    }

    @Test
    public void testFindLocationWithParser() {
        TokenStreamLocation mockLocation = mock(TokenStreamLocation.class);
        when(mockParser.currentLocation()).thenReturn(mockLocation);

        DupDetector detector = DupDetector.rootDetector(mockParser);
        TokenStreamLocation result = detector.findLocation();

        assertEquals(mockLocation, result);
    }

    @Test
    public void testFindLocationWithGenerator() {
        DupDetector detector = DupDetector.rootDetector(mockGenerator);
        TokenStreamLocation result = detector.findLocation();

        // Generators don't have a location method, so should return null
        assertNull(result);
    }

    @Test
    public void testFindLocationWithChildDetector() {
        TokenStreamLocation mockLocation = mock(TokenStreamLocation.class);
        when(mockParser.currentLocation()).thenReturn(mockLocation);

        DupDetector parent = DupDetector.rootDetector(mockParser);
        DupDetector child = parent.child();

        TokenStreamLocation result = child.findLocation();

        assertEquals(mockLocation, result);
    }

    @Test
    public void testIsDupWithNullName() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        // First call with null - should set _firstName to null
        boolean result1 = detector.isDup(null);
        assertFalse(result1);

        // Second call with null - should detect as duplicate of first null
        boolean result2 = detector.isDup(null);
        assertTrue(result2);
    }

    @Test
    public void testIsDupSwitchingBetweenNames() {
        DupDetector detector = DupDetector.rootDetector(mockParser);

        assertFalse(detector.isDup("a"));
        assertFalse(detector.isDup("b"));

        // a is duplicate
        assertTrue(detector.isDup("a"));

        // b is duplicate
        assertTrue(detector.isDup("b"));

        // c is new
        assertFalse(detector.isDup("c"));

        // a is still duplicate
        assertTrue(detector.isDup("a"));
    }
}

package tools.jackson.core.json;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

import org.junit.Test;

import tools.jackson.core.JsonGenerator;
import tools.jackson.core.JsonParser;
import tools.jackson.core.JsonReadFeature;
import tools.jackson.core.JsonToken;
import tools.jackson.core.JsonWriteFeature;
import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.Version;
import tools.jackson.core.util.Named;

import static org.junit.Assert.*;

public class JsonFactoryTest {

    @Test
    public void testDefaultValues() {
        JsonFactory factory = new JsonFactory();

        // Verify Format Name
        assertEquals("JSON", factory.getFormatName());

        // Verify Async Support
        assertTrue(factory.canParseAsync());

        // Verify Schema Support (always false for JSON)
        assertFalse(factory.canUseSchema(null));

        // Verify Default Root Value Separator (space)
        assertEquals(" ", factory.getRootValueSeparator());

        // Verify Character Escapes (null by default)
        assertNull(factory.getCharacterEscapes());

        // Verify Feature Types
        assertEquals(JsonReadFeature.class, factory.getFormatReadFeatureType());
        assertEquals(JsonWriteFeature.class, factory.getFormatWriteFeatureType());
    }

    @Test
    public void testVersion() {
        JsonFactory factory = new JsonFactory();
        Version v = factory.version();
        assertNotNull(v);
        // Verify it returns the package version
        assertNotNull(v.getVersion());
    }

    @Test
    public void testCopy() {
        JsonFactory original = new JsonFactory();
        JsonFactory copy = original.copy();

        assertNotSame(original, copy);
        assertEquals(original.getFormatName(), copy.getFormatName());
        assertEquals(original.getRootValueSeparator(), copy.getRootValueSeparator());
    }

    @Test
    public void testSnapshot() {
        JsonFactory original = new JsonFactory();
        // snapshot() returns 'this' for JsonFactory
        assertSame(original, original.snapshot());
    }

    @Test
    public void testBuilder() {
        JsonFactory factory = JsonFactory.builder()
                .rootValueSeparator("|")
                .build();

        assertEquals("|", factory.getRootValueSeparator());
    }

    @Test
    public void testBuilderWithJackson2Defaults() {
        // Verify builderWithJackson2Defaults returns a builder configured for Jackson 2
        // It disables ESCAPE_FORWARD_SLASHES and COMBINE_UNICODE_SURROGATES_IN_UTF8
        JsonFactory factory = JsonFactory.builderWithJackson2Defaults()
                .build();

        assertFalse(factory.isEnabled(JsonWriteFeature.ESCAPE_FORWARD_SLASHES));
        assertFalse(factory.isEnabled(JsonWriteFeature.COMBINE_UNICODE_SURROGATES_IN_UTF8));
    }

    @Test
    public void testIsEnabledReadFeature() {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES)
                .build();

        assertTrue(factory.isEnabled(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES));

        // Test disable
        factory = JsonFactory.builder()
                .enable(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES)
                .disable(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES)
                .build();

        assertFalse(factory.isEnabled(JsonReadFeature.ALLOW_UNQUOTED_FIELD_NAMES));
    }

    @Test
    public void testIsEnabledWriteFeature() {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES)
                .build();

        assertTrue(factory.isEnabled(JsonWriteFeature.ESCAPE_FORWARD_SLASHES));
    }

    @Test
    public void testCreateParserFromString() throws Exception {
        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser("{\"key\": 1}");

        assertNotNull(parser);
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.PROPERTY_NAME, parser.nextToken());
        assertEquals("key", parser.currentName());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());

        parser.close();
    }

    @Test
    public void testCreateParserFromByteArray() throws Exception {
        JsonFactory factory = new JsonFactory();
        byte[] data = "{\"key\": 1}".getBytes("UTF-8");
        JsonParser parser = factory.createParser(data);

        assertNotNull(parser);
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        parser.close();
    }

    @Test
    public void testCreateParserFromInputStream() throws Exception {
        JsonFactory factory = new JsonFactory();
        byte[] data = "{\"a\":true}".getBytes("UTF-8");
        InputStream in = new ByteArrayInputStream(data);
        JsonParser parser = factory.createParser(in);

        assertNotNull(parser);
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        parser.close();
    }

    @Test
    public void testCreateGenerator() throws Exception {
        JsonFactory factory = new JsonFactory();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        JsonGenerator generator = factory.createGenerator(out);

        assertNotNull(generator);

        generator.writeStartObject();
        generator.writeName("field");
        generator.writeString("value");
        generator.writeEndObject();
        generator.close();

        assertEquals("{\"field\":\"value\"}", out.toString("UTF-8"));
    }

    @Test
    public void testCreateNonBlockingByteArrayParser() {
        JsonFactory factory = new JsonFactory();

        JsonParser parser = factory.createNonBlockingByteArrayParser(ObjectReadContext.empty());
        assertNotNull(parser);
    }

    @Test
    public void testCreateNonBlockingByteBufferParser() {
        JsonFactory factory = new JsonFactory();

        JsonParser parser = factory.createNonBlockingByteBufferParser(ObjectReadContext.empty());
        assertNotNull(parser);
    }

    @Test
    public void testConstructNameMatcher() {
        JsonFactory factory = new JsonFactory();
        List<Named> names = Arrays.asList(
            Named.fromString("id"),
            Named.fromString("name")
        );

        // Test standard matcher
        tools.jackson.core.sym.PropertyNameMatcher matcher = factory.constructNameMatcher(names, false);
        assertNotNull(matcher);

        // Verify it can match a known name
        int matchId = matcher.matchName("id");
        assertTrue("Expected valid match for 'id'", matchId >= 0);

        // Test Case Insensitive matcher
        tools.jackson.core.sym.PropertyNameMatcher ciMatcher = factory.constructCINameMatcher(names, false, Locale.US);
        assertNotNull(ciMatcher);

        // Verify case insensitive matching works (matches "ID" for "id")
        int matchUpperId = ciMatcher.matchName("ID");
        assertTrue("Expected valid match for 'ID' in case-insensitive matcher", matchUpperId >= 0);
    }
}

