/**
 * Tests for {@link JsonFactoryBuilder}.
 */
public class JsonFactoryBuilderTest {

    @Test
    public void testDefaultConstructorSetsDefaultValues() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        // Verify default character escapes is null
        assertNull(builder.characterEscapes());

        // Verify default root value separator is not null
        assertNotNull(builder.rootValueSeparator());
        assertEquals(" ", builder.rootValueSeparator().getValue());

        // Verify default highest non-escaped char is 0 (disabled)
        assertEquals(0, builder.highestNonEscapedChar());

        // Verify default quote char is double quote
        assertEquals('"', builder.quoteChar());
    }

    @Test
    public void testConstructorFromJsonFactoryCopiesSettings() {
        JsonFactory original = new JsonFactory();
        JsonFactoryBuilder builder = new JsonFactoryBuilder(original);

        // The builder should copy settings from original factory
        assertNotNull(builder);
    }

    @Test
    public void testEnableSingleJsonReadFeature() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.enable(JsonReadFeature.ALLOW_JAVA_COMMENTS);

        assertSame(builder, result);
    }

    @Test
    public void testEnableMultipleJsonReadFeatures() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.enable(
            JsonReadFeature.ALLOW_JAVA_COMMENTS,
            JsonReadFeature.ALLOW_SINGLE_QUOTES,
            JsonReadFeature.ALLOW_UNQUOTED_PROPERTY_NAMES);

        assertSame(builder, result);
    }

    @Test
    public void testDisableSingleJsonReadFeature() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.disable(JsonReadFeature.ALLOW_JAVA_COMMENTS);

        assertSame(builder, result);
    }

    @Test
    public void testDisableMultipleJsonReadFeatures() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.disable(
            JsonReadFeature.ALLOW_JAVA_COMMENTS,
            JsonReadFeature.ALLOW_SINGLE_QUOTES,
            JsonReadFeature.ALLOW_UNQUOTED_PROPERTY_NAMES);

        assertSame(builder, result);
    }

    @Test
    public void testConfigureJsonReadFeatureEnabled() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.configure(JsonReadFeature.ALLOW_JAVA_COMMENTS, true);

        assertSame(builder, result);
    }

    @Test
    public void testConfigureJsonReadFeatureDisabled() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();
        builder.enable(JsonReadFeature.ALLOW_JAVA_COMMENTS);

        JsonFactoryBuilder result = builder.configure(JsonReadFeature.ALLOW_JAVA_COMMENTS, false);

        assertSame(builder, result);
    }

    @Test
    public void testEnableSingleJsonWriteFeature() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.enable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES);

        assertSame(builder, result);
    }

    @Test
    public void testEnableMultipleJsonWriteFeatures() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.enable(
            JsonWriteFeature.ESCAPE_FORWARD_SLASHES,
            JsonWriteFeature.ESCAPE_NON_ASCII,
            JsonWriteFeature.WRITE_NUMBERS_AS_STRINGS);

        assertSame(builder, result);
    }

    @Test
