        JsonFactoryBuilder builder = new JsonFactoryBuilder();
        builder.enable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES);

        JsonFactoryBuilder result = builder.configure(JsonWriteFeature.ESCAPE_FORWARD_SLASHES, false);

        assertSame(builder, result);
    }

    @Test
    public void testConfigureForJackson2() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.configureForJackson2();

        assertSame(builder, result);
        // Verify specific settings are applied
        // ESCAPE_FORWARD_SLASHES should be disabled
        // COMBINE_UNICODE_SURROGATES_IN_UTF8 should be disabled
        // Should use thread local pool
    }

    @Test
    public void testCharacterEscapesWithNull() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.characterEscapes(null);

        assertSame(builder, result);
        assertNull(builder.characterEscapes());
    }

    @Test
    public void testCharacterEscapesWithNonNull() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();
        // Use a simple custom CharacterEscapes implementation for testing
        CharacterEscapes customEscapes = new CharacterEscapes() {
            @Override
            public int[] getEscapeCodesForAscii() {
                return standardAsciiEscapesForJSON();
            }
            @Override
            public SerializableString getEscapeSequence(int ch) {
                return null;
            }
        };

        JsonFactoryBuilder result = builder.characterEscapes(customEscapes);

        assertSame(builder, result);
        assertNotNull(builder.characterEscapes());
    }

