    public void testRootValueSeparatorWithNonNullString() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.rootValueSeparator(",");

        assertSame(builder, result);
        assertNotNull(builder.rootValueSeparator());
        assertEquals(",", builder.rootValueSeparator().getValue());
    }

    @Test
    public void testRootValueSeparatorWithNullSerializableString() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.rootValueSeparator((SerializableString) null);

        assertSame(builder, result);
        assertNull(builder.rootValueSeparator());
    }

    @Test
    public void testRootValueSeparatorWithNonNullSerializableString() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();
        SerializableString customSeparator = new SerializedString(";");

        JsonFactoryBuilder result = builder.rootValueSeparator(customSeparator);

        assertSame(builder, result);
        assertNotNull(builder.rootValueSeparator());
        assertEquals(";", builder.rootValueSeparator().getValue());
    }

    @Test
    public void testHighestNonEscapedCharWithZero() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.highestNonEscapedChar(0);

        assertSame(builder, result);
        assertEquals(0, builder.highestNonEscapedChar());
    }

    @Test
    public void testHighestNonEscapedCharWithNegativeValue() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.highestNonEscapedChar(-5);

        assertSame(builder, result);
        assertEquals(0, builder.highestNonEscapedChar());
    }

    @Test
    public void testHighestNonEscapedCharWithValueBetween1And126() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.highestNonEscapedChar(100);

        assertSame(builder, result);
        // Values between 1 and 126 should behave as 127
        assertEquals(127, builder.highestNonEscapedChar());
    }

    @Test
    public void testHighestNonEscapedCharWithValue127() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.highestNonEscapedChar(127);

        assertSame(builder, result);
        assertEquals(127, builder.highestNonEscapedChar());
    }

    @Test
    public void testHighestNonEscapedCharWithValueGreaterThan127() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.highestNonEscapedChar(200);

        assertSame(builder, result);
        assertEquals(200, builder.highestNonEscapedChar());
    }

    @Test
    public void testQuoteCharWithDefaultValue() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.quoteChar('"');

        assertSame(builder, result);
        assertEquals('"', builder.quoteChar());
    }

    @Test
    public void testQuoteCharWithSingleQuote() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.quoteChar('\'');

        assertSame(builder, result);
        assertEquals('\'', builder.quoteChar());
    }

    @Test
    public void testQuoteCharWithAsciiValue() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactoryBuilder result = builder.quoteChar('a');

        assertSame(builder, result);
        assertEquals('a', builder.quoteChar());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testQuoteCharWithUnicodeValueAbove7FThrows() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        builder.quoteChar((char) 0x80); // Above 0x7F should throw
    }

    @Test
    public void testBuildReturnsNonNullJsonFactory() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        JsonFactory result = builder.build();

        assertNotNull(result);
    }

    @Test
    public void testBuildWithCustomSettings() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder()
            .enable(JsonReadFeature.ALLOW_JAVA_COMMENTS)
            .enable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES)
            .characterEscapes(null)
            .rootValueSeparator(",")
            .highestNonEscapedChar(127)
            .quoteChar('"');

        JsonFactory factory = builder.build();

        assertNotNull(factory);
    }

    @Test
    public void testChainedCallsReturnThisBuilder() {
        JsonFactoryBuilder builder = new JsonFactoryBuilder();

        // Verify all setter methods return this for chaining
        assertSame(builder, builder.enable(JsonReadFeature.ALLOW_JAVA_COMMENTS));
        assertSame(builder, builder.disable(JsonReadFeature.ALLOW_JAVA_COMMENTS));
        assertSame(builder, builder.configure(JsonReadFeature.ALLOW_JAVA_COMMENTS, true));
        assertSame(builder, builder.enable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES));
        assertSame(builder, builder.disable(JsonWriteFeature.ESCAPE_FORWARD_SLASHES));
        assertSame(builder, builder.configure(JsonWriteFeature.ESCAPE_FORWARD_SLASHES, true));
        assertSame(builder, builder.configureForJackson2());
        assertSame(builder, builder.characterEscapes(null));
        assertSame(builder, builder.rootValueSeparator((String) null));
        assertSame(builder, builder.rootValueSeparator((SerializableString) null));
        assertSame(builder, builder.highestNonEscapedChar(0));
        assertSame(builder, builder.quoteChar('"'));
    }
}

