@RunWith(MockitoJUnitRunner.class)
public class JsonReadContextTest {

    @Mock
    private DupDetector mockDupDetector;

    @Mock
    private JsonParser mockParser;

    // --- Factory methods ---

    @Test
    public void testCreateRootContext() {
        DupDetector dups = DupDetector.rootDetector(mockParser);
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, dups);

        assertNull(ctx.getParent());
        assertTrue(ctx.inRoot());
        assertEquals(0, ctx.getNestingDepth());
        assertEquals(TokenStreamContext.TYPE_ROOT, ctx.typeDesc().equals("root") ? 0 : -1); // typeDesc returns string, use constants
    }

    // Actually, let's use the protected _type or the public methods inArray(), inObject(), etc.
    // TokenStreamContext has: inArray(), inObject(), inRoot().

    @Test
    public void testRootContextType() {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);
        assertTrue(ctx.inRoot());
        assertFalse(ctx.inArray());
        assertFalse(ctx.inObject());
    }

    @Test
    public void testCreateChildArrayContext() {
        JsonReadContext parent = JsonReadContext.createRootContext(1, 0, null);
        JsonReadContext child = parent.createChildArrayContext(2, 5);

        assertNotNull(child);
        assertTrue(child.inArray());
        assertFalse(child.inObject());
        assertEquals(parent, child.getParent());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testCreateChildObjectContext() {
        JsonReadContext parent = JsonReadContext.createRootContext(1, 0, null);
        JsonReadContext child = parent.createChildObjectContext(2, 5);

        assertNotNull(child);
        assertFalse(child.inArray());
        assertTrue(child.inObject());
        assertEquals(parent, child.getParent());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testChildContextReuse() {
        JsonReadContext parent = JsonReadContext.createRootContext(1, 0, null);

        JsonReadContext child1 = parent.createChildArrayContext(1, 1);
        JsonReadContext child2 = parent.createChildArrayContext(2, 2);

        // Should reuse the same instance
        assertSame(child1, child2);

        // Verify reset was called on the child
        // We can't easily verify reset was called unless we spy or check state, 
        // but checking state is easy enough (line/col updated).
        // Actually, the code does: ctxt.reset(TYPE_ARRAY, lineNr, colNr);
    }

    // --- reset ---

    @Test
    public void testResetClearsState() {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);

        // Set some state via reflection or helpers? 
        // We can use setCurrentName if we enable dup detector, but that requires parser.
        // Or use protected fields? No, can't touch protected fields from test in different package? 
        // Actually test is in same package if I put it in correct location? 
        // "src/test/java/tools/jackson/core/json/JsonReadContextTest.java"
        // Package is tools.jackson.core.json. Same package. I can access protected members.

        // Let's set state using API.
        // assignCurrentValue
        ctx.assignCurrentValue("testValue");

        // Call reset
        ctx.reset(TokenStreamContext.TYPE_OBJECT, 10, 20);

        // Check state
        // _currentName = null, _currentValue = null, _type = TYPE_OBJECT, etc.

        assertNull(ctx.currentValue());
        assertNull(ctx.currentName());

        // Verify type changed (inObject)
        assertTrue(ctx.inObject());
    }

    // --- expectComma ---

    @Test
    public void testExpectCommaRoot() {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);
        // Root context: type is TYPE_ROOT
        // expectComma logic: _type != TYPE_ROOT && ix > 0
        // For root, _type == TYPE_ROOT, so false.

        assertFalse(ctx.expectComma());
        assertFalse(ctx.expectComma());
    }

    @Test
    public void testExpectCommaArray() {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);
        JsonReadContext arrayCtx = ctx.createChildArrayContext(1, 1);

        // First element: index goes -1 -> 0. ix=0. 0 > 0 is false.
        assertFalse(arrayCtx.expectComma());

        // Second element: index goes 0 -> 1. ix=1. 1 > 0 is true.
        assertTrue(arrayCtx.expectComma());

        // Third element: index goes 1 -> 2. ix=2. 2 > 0 is true.
        assertTrue(arrayCtx.expectComma());
    }

    // --- setCurrentName ---

    @Test
    public void testSetCurrentNameNoDupDetector() throws Exception {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);
        ctx.setCurrentName("field");

        assertEquals("field", ctx.currentName());
        assertTrue(ctx.hasCurrentName());
    }

    @Test
    public void testSetCurrentNameWithDupDetectorNoDup() throws Exception {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, mockDupDetector);

        when(mockDupDetector.isDup("field")).thenReturn(false);

        ctx.setCurrentName("field");

        assertEquals("field", ctx.currentName());
        verify(mockDupDetector).isDup("field");
    }

    @Test(expected = StreamReadException.class)
    public void testSetCurrentNameWithDupDetectorDup() throws Exception {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, mockDupDetector);

        when(mockDupDetector.isDup("field")).thenReturn(true);
        // getSource is called in exception construction
        when(mockDupDetector.getSource()).thenReturn(mockParser);

        ctx.setCurrentName("field");
    }

    // --- clearAndGetParent ---

    @Test
    public void testClearAndGetParent() {
        JsonReadContext parent = JsonReadContext.createRootContext(1, 0, null);
        JsonReadContext child = parent.createChildObjectContext(1, 1);

        child.assignCurrentValue("value");
        assertNotNull(child.currentValue());

        JsonReadContext result = child.clearAndGetParent();

        assertNull(child.currentValue());
        assertEquals(parent, result);
    }

    // --- startLocation ---

    @Test
    public void testStartLocation() {
        JsonReadContext ctx = JsonReadContext.createRootContext(10, 20, null);

        ContentReference src = ContentReference.unknown();
        TokenStreamLocation loc = ctx.startLocation(src);

        assertNotNull(loc);
        assertEquals(10, loc.getLineNr());
        assertEquals(20, loc.getColumnNr());
    }

    // --- withDupDetector ---

    @Test
    public void testWithDupDetector() {
        JsonReadContext ctx = JsonReadContext.createRootContext(1, 0, null);
        assertNull(ctx.getDupDetector());

        JsonReadContext returned = ctx.withDupDetector(mockDupDetector);

        assertSame(ctx, returned);
        assertSame(mockDupDetector, ctx.getDupDetector());
    }
}

