package tools.jackson.core.json;

import static org.junit.Assert.*;

import org.junit.Test;

import tools.jackson.core.DupDetector;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.exc.StreamWriteException;

public class JsonWriteContextTest
{
    @Test
    public void testRootContextCreation() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);

        assertNotNull(root);
        assertNull(root.getParent());
        assertTrue(root.inRoot());
        assertFalse(root.inArray());
        assertFalse(root.inObject());
        assertEquals(-1, root.getCurrentIndex());
        assertEquals(0, root.getNestingDepth());
    }

    @Test
    public void testRootContextWithDupDetector() {
        DupDetector dd = new DupDetector(new Object());
        JsonWriteContext root = JsonWriteContext.createRootContext(dd);

        assertNotNull(root.getDupDetector());
    }

    @Test
    public void testChildArrayContextCreation() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        JsonWriteContext child = root.createChildArrayContext(null);

        assertNotNull(child);
        assertEquals(root, child.getParent());
        assertTrue(child.inArray());
        assertFalse(child.inObject());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testChildObjectContextCreation() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        JsonWriteContext child = root.createChildObjectContext(null);

        assertNotNull(child);
        assertEquals(root, child.getParent());
        assertTrue(child.inObject());
        assertFalse(child.inArray());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testChildContextReuse() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);

        // Create first child
        JsonWriteContext child1 = root.createChildArrayContext(null);
        // Create second child - should reuse same instance
        JsonWriteContext child2 = root.createChildArrayContext(null);

        assertSame(child1, child2);
    }

    @Test
    public void testNestingDepth() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        assertEquals(0, root.getNestingDepth());

        JsonWriteContext array = root.createChildArrayContext(null);
        assertEquals(1, array.getNestingDepth());

        JsonWriteContext object = array.createChildObjectContext(null);
        assertEquals(2, object.getNestingDepth());

        JsonWriteContext nestedArray = object.createChildArrayContext(null);
        assertEquals(3, nestedArray.getNestingDepth());
    }

    @Test
    public void testWriteNameInObjectContext() {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // First name should succeed
        int status = objectContext.writeName("firstName");
        assertEquals(JsonWriteContext.STATUS_OK_AS_IS, status);
        assertEquals("firstName", objectContext.currentName());
        assertTrue(objectContext.hasCurrentName());
    }

    @Test
    public void testWriteNameInObjectContextAfterComma() {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // First name
        objectContext.writeName("firstName");
        // Write value to reset _gotName
        objectContext.writeValue();

        // Second name should return STATUS_OK_AFTER_COMMA
        int status = objectContext.writeName("secondName");
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COMMA, status);
    }

    @Test
    public void testWriteNameExpectValueAfterName() {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // Write first name
        objectContext.writeName("firstName");

        // Try to write another name without writing value - should return STATUS_EXPECT_VALUE
        int status = objectContext.writeName("secondName");
        assertEquals(JsonWriteContext.STATUS_EXPECT_VALUE, status);
    }

    @Test
    public void testWriteNameInNonObjectContext() {
        JsonWriteContext arrayContext = JsonWriteContext.createRootContext(null)
                .createChildArrayContext(null);

        // Should return STATUS_EXPECT_VALUE in array context
        int status = arrayContext.writeName("someName");
        assertEquals(JsonWriteContext.STATUS_EXPECT_VALUE, status);
    }

    @Test
    public void testWriteValueInObjectContext() {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // Write name first
        objectContext.writeName("field");

        // Write value - should succeed
        int status = objectContext.writeValue();
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COLON, status);
    }

    @Test
    public void testWriteValueInObjectContextExpectName() {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // Try to write value without name - should fail
        int status = objectContext.writeValue();
        assertEquals(JsonWriteContext.STATUS_EXPECT_NAME, status);
    }

    @Test
    public void testWriteValueInArrayContext() {
        JsonWriteContext arrayContext = JsonWriteContext.createRootContext(null)
                .createChildArrayContext(null);

        // First value in array
        int status = arrayContext.writeValue();
        assertEquals(JsonWriteContext.STATUS_OK_AS_IS, status);

        // Second value in array
        status = arrayContext.writeValue();
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COMMA, status);
    }

    @Test
    public void testWriteValueInRootContext() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);

        // First value in root
        int status = root.writeValue();
        assertEquals(JsonWriteContext.STATUS_OK_AS_IS, status);

        // Second value in root
        status = root.writeValue();
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_SPACE, status);
    }

    @Test
    public void testClearAndGetParent() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        JsonWriteContext objectContext = root.createChildObjectContext(null);

        // Assign a value
        Object someValue = new Object();
        objectContext.assignCurrentValue(someValue);
        assertEquals(someValue, objectContext.currentValue());

        // Clear and get parent
        JsonWriteContext parent = objectContext.clearAndGetParent();

        assertEquals(root, parent);
        assertNull(objectContext.currentValue());
    }

    @Test
    public void testReset() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        JsonWriteContext child = root.createChildArrayContext("initialValue");

        // Write some values
        child.writeValue();
        child.writeValue();

        // Reset to object type
        child.reset(TokenStreamContext.TYPE_OBJECT, "newValue");

        assertTrue(child.inObject());
        assertFalse(child.inArray());
        assertEquals("newValue", child.currentValue());
        assertFalse(child.hasCurrentName());
        assertEquals(-1, child.getCurrentIndex());
    }

    @Test
    public void testCurrentValue() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        Object value = new Object();
        JsonWriteContext child = root.createChildArrayContext(value);

        assertEquals(value, child.currentValue());
    }

    @Test
    public void testAssignCurrentValue() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        JsonWriteContext child = root.createChildArrayContext(null);

        Object value = new Object();
        child.assignCurrentValue(value);

        assertEquals(value, child.currentValue());
    }

    @Test
    public void testWithDupDetector() {
        JsonWriteContext root = JsonWriteContext.createRootContext(null);
        assertNull(root.getDupDetector());

        DupDetector dd = new DupDetector(new Object());
        JsonWriteContext withDd = root.withDupDetector(dd);

        assertSame(root, withDd);
        assertEquals(dd, root.getDupDetector());
    }

    @Test(expected = StreamWriteException.class)
    public void testDuplicateNameDetection() throws Exception {
        JsonGenerator generator = new MockJsonGenerator();
        DupDetector dd = new DupDetector(generator);
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(dd)
                .createChildObjectContext(null);

        // Write first name
        objectContext.writeName("duplicate");

        // Write value to reset _gotName
        objectContext.writeValue();

        // Try to write duplicate name - should throw exception
        objectContext.writeName("duplicate");
    }

    @Test
    public void testNoDuplicateDetectionWithoutDetector() throws Exception {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // Write same name twice - should succeed without detector
        objectContext.writeName("duplicate");
        objectContext.writeValue();
        int status = objectContext.writeName("duplicate");

        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COMMA, status);
    }

    @Test
    public void testCurrentNameNoName() {
        JsonWriteContext arrayContext = JsonWriteContext.createRootContext(null)
                .createChildArrayContext(null);

        assertFalse(arrayContext.hasCurrentName());
        assertNull(arrayContext.currentName());
    }

    @Test
    public void testMultipleValuesInObject() throws Exception {
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(null)
                .createChildObjectContext(null);

        // First property
        objectContext.writeName("a");
        assertEquals(JsonWriteContext.STATUS_OK_AS_IS, objectContext.writeValue());

        // Second property
        objectContext.writeName("b");
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COMMA, objectContext.writeValue());

        // Third property
        objectContext.writeName("c");
        assertEquals(JsonWriteContext.STATUS_OK_AFTER_COMMA, objectContext.writeValue());

        // Check index
        assertEquals(2, objectContext.getCurrentIndex());
    }

    @Test
    public void testDupDetectorResetOnContextReset() {
        JsonGenerator generator = new MockJsonGenerator();
        DupDetector dd = new DupDetector(generator);
        JsonWriteContext objectContext = JsonWriteContext.createRootContext(dd)
                .createChildObjectContext(null);

        // Write a name to populate duplicate detector
        objectContext.writeName("someName");
        objectContext.writeValue();

        // Reset the context
        objectContext.reset(TokenStreamContext.TYPE_OBJECT, null);

        // Should be able to write the same name again after reset
        int status = objectContext.writeName("someName");
        assertEquals(JsonWriteContext.STATUS_OK_AS_IS, status);
    }

