package tools.jackson.core.json;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.io.Reader;
import java.io.StringReader;
import java.io.StringWriter;
import java.io.IOException;

import tools.jackson.core.Base64Variant;
import tools.jackson.core.JsonToken;
import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.SerializableString;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.CharsToNameCanonicalizer;

public class ReaderBasedJsonParserTest {

    private IOContext mockIOContext;
    private CharsToNameCanonicalizer mockSymbols;
    private ObjectReadContext readContext;

    @Before
    public void setUp() throws Exception {
        mockIOContext = mock(IOContext.class);
        mockSymbols = mock(CharsToNameCanonicalizer.class);
        readContext = ObjectReadContext.empty();

        // Setup mocks for IOContext
        when(mockIOContext.isResourceManaged()).thenReturn(false);
        when(mockIOContext.allocTokenBuffer()).thenReturn(new char[100]);
        when(mockIOContext.releaseTokenBuffer(any(char[].class))).thenReturn(null);

        // Setup mocks for CharsToNameCanonicalizer
        when(mockSymbols.hashSeed()).thenReturn(0);
        when(mockSymbols.willInternStrings()).thenReturn(false);
        // Simple implementation that returns string from buffer
        when(mockSymbols.findSymbol(any(char[].class), anyInt(), anyInt(), anyInt()))
            .thenAnswer(invocation -> {
                char[] buf = invocation.getArgument(0);
                int start = invocation.getArgument(1);
                int len = invocation.getArgument(2);
                return new String(buf, start, len);
            });
    }

    private ReaderBasedJsonParser createParser(String json) {
        char[] buffer = json.toCharArray();
        return new ReaderBasedJsonParser(
            readContext, 
            mockIOContext, 
            0, 
            0, 
            new StringReader(json), 
            mockSymbols, 
            buffer, 
            0, 
            buffer.length, 
            true
        );
    }

    @Test
    public void testParseSimpleObject() throws Exception {
        ReaderBasedJsonParser parser = createParser("{\"key\": \"value\"}");

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.PROPERTY_NAME, parser.nextToken());
        assertEquals("key", parser.currentName());

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getString());

        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        parser.close();
    }

    @Test
    public void testParseArray() throws Exception {
        ReaderBasedJsonParser parser = createParser("[1, true, null]");

        assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());

        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());

        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());

        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        parser.close();
    }

    @Test
    public void testNextName() throws Exception {
        ReaderBasedJsonParser parser = createParser("{\"foo\": 1}");

        parser.nextToken(); // START_OBJECT

        String name = parser.nextName();
        assertEquals("foo", name);

        // Verify value follows
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        parser.close();
    }

    @Test
    public void testNextNameWithSerializableString() throws Exception {
        ReaderBasedJsonParser parser = createParser("{\"test\": 1}");
        parser.nextToken(); // START_OBJECT

        SerializableString sstr = mock(SerializableString.class);
        when(sstr.getValue()).thenReturn("test");
        when(sstr.asQuotedChars()).thenReturn("\"test\"".toCharArray());

        boolean match = parser.nextName(sstr);
        assertTrue(match);
        assertEquals("test", parser.currentName());
        parser.close();
    }

    @Test
    public void testReleaseBuffered() throws Exception {
        // Provide extra content after the JSON value to test release
        ReaderBasedJsonParser parser = createParser("\"test\" extra");
        parser.nextToken(); // parses string, _inputPtr moves past string

        StringWriter writer = new StringWriter();
        int released = parser.releaseBuffered(writer);

        // The buffer should contain " extra"
        assertTrue(released > 0);
        assertTrue(writer.toString().contains("extra"));
        parser.close();
    }

    @Test
    public void testStreamReadInputSource() throws Exception {
        StringReader sr = new StringReader("{}");
        char[] buffer = "{}".toCharArray();
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
            readContext, mockIOContext, 0, 0, sr, mockSymbols, buffer, 0, 2, true);

        assertSame(sr, parser.streamReadInputSource());
        parser.close();
    }

    @Test
    public void testWillInternPropertyNames() throws Exception {
        when(mockSymbols.willInternStrings()).thenReturn(true);
        ReaderBasedJsonParser parser = createParser("{}");

        assertTrue(parser.willInternPropertyNames());

        when(mockSymbols.willInternStrings()).thenReturn(false);
        assertFalse(parser.willInternPropertyNames());
        parser.close();
    }

    @Test
    public void testGetBinaryValue() throws Exception {
        // "SGVsbG8=" is "Hello" in Base64
        ReaderBasedJsonParser parser = createParser("\"SGVsbG8=\"");
        parser.nextToken();

        Base64Variant variant = new Base64Variant("TEST", "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", true, '=', 76);
        byte[] data = parser.getBinaryValue(variant);

        String str = new String(data);
        assertEquals("Hello", str);
        parser.close();
    }

    @Test
    public void testNextBooleanValue() throws Exception {
        ReaderBasedJsonParser parser = createParser("true");
        Boolean val = parser.nextBooleanValue();
        assertEquals(Boolean.TRUE, val);

        parser = createParser("false");
        assertEquals(Boolean.FALSE, parser.nextBooleanValue());

        parser = createParser("123");
        assertNull(parser.nextBooleanValue());

        parser.close();
    }

    @Test
    public void testFinishToken() throws Exception {
        ReaderBasedJsonParser parser = createParser("\"test string\"");
        parser.nextToken();
        assertTrue(parser.hasCurrentToken());

        parser.finishToken();
        // _tokenIncomplete should be false now
        assertEquals("test string", parser.getString());
        parser.close();
    }

    @Test
    public void testEmptyInput() throws Exception {
        ReaderBasedJsonParser parser = createParser("");
        JsonToken token = parser.nextToken();
        assertNull(token);
        assertTrue(parser.isClosed());
    }

    @Test
    public void testGetStringOnPropertyName() throws Exception {
        ReaderBasedJsonParser parser = createParser("{\"key\": 1}");
