        bufferRecycler = new BufferRecycler();
        StreamReadConstraints readConstraints = StreamReadConstraints.defaults();
        StreamWriteConstraints writeConstraints = StreamWriteConstraints.defaults();
        ioContext = new IOContext(readConstraints, writeConstraints, 
                ErrorReportConfiguration.defaultConfiguration(),
                bufferRecycler, ContentReference.unknown(), false, JsonEncoding.UTF8);
        readContext = ObjectReadContext.empty();
        symbolTable = ByteQuadsCanonicalizer.createRoot();
    }

