    public void testWriteName() throws Exception {
        generator.writeStartObject();
        generator.writeName("field");
        generator.writeEndObject();
        generator.flush();
        assertEquals("{\"field\"}", getOutput());
    }

    @Test
    public void testWriteNameWithSerializableString() throws Exception {
        SerializableString serName = new SerializedString("myField");
        generator.writeStartObject();
        generator.writeName(serName);
        generator.writeEndObject();
        generator.flush();
        assertEquals("{\"myField\"}", getOutput());
    }

    @Test
    public void testWriteComplexObject() throws Exception {
        generator.writeStartObject();
        generator.writeName("key");
        generator.writeValue("value");
        generator.writeEndObject();
        generator.flush();
        // Note: writeValue writes raw value, but in context needs name first. 
        // Actually writeValue is not in JsonGenerator interface, let's use writeString
        // Reset
        outputStream.reset();

        generator.writeStartObject();
        generator.writeName("key");
        generator.writeString("value");
        generator.writeEndObject();
        generator.flush();
        assertEquals("{\"key\":\"value\"}", getOutput());
    }

    @Test
    public void testWriteRaw() throws Exception {
        generator.writeRaw("raw text");
        generator.flush();
        assertEquals("raw text", getOutput());
    }

    @Test
    public void testWriteRawCharArray() throws Exception {
        char[] chars = new char[] { 'a', 'b', 'c' };
        generator.writeRaw(chars, 0, 3);
        generator.flush();
        assertEquals("abc", getOutput());
    }

    @Test
    public void testWriteBinary() throws Exception {
        byte[] data = new byte[] { 1, 2, 3 }; // Simple bytes
        // Base64 for [1,2,3] is "AQID"
        generator.writeBinary(Base64Variants.getDefaultVariant(), data, 0, data.length);
        generator.flush();
        assertEquals("\"AQID\"", getOutput());
    }

    @Test
    public void testFlush() throws Exception {
        generator.writeNumber(1);
        generator.flush();
        // Verify something is in the stream before close
        assertTrue(outputStream.size() > 0);
    }

    @Test
    public void testStreamWriteOutputTarget() throws Exception {
        assertEquals(outputStream, generator.streamWriteOutputTarget());
    }

    @Test
    public void testStreamWriteOutputBuffered() throws Exception {
        // Initially 0
        assertEquals(0, generator.streamWriteOutputBuffered());

        generator.writeNumber(12345);
        // Should have written 5 bytes
        // Note: internal state might not be flushed to stream yet
        assertTrue(generator.streamWriteOutputBuffered() > 0);
    }

    @Test
    public void testWriteNumberAsString() throws Exception {
        // Test with format feature WRITE_NUMBERS_AS_STRINGS enabled
        int formatFeatures = JsonWriteFeature.collectDefaults() | JsonWriteFeature.WRITE_NUMBERS_AS_STRINGS.getMask();

        UTF8JsonGenerator gen = new UTF8JsonGenerator(
                objectWriteContext,
                mockIoContext,
                StreamWriteFeature.collectDefaults(),
                formatFeatures,
                outputStream,
                null, null, null, 0, '"'
        );

        gen.writeNumber(123);
        gen.flush();
        assertEquals("\"123\"", getOutput());
        gen.close();
    }
}

