package tools.jackson.core.json;

import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.ByteQuadsCanonicalizer;
import tools.jackson.core.util.TextBuffer;
import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.ErrorReportConfiguration;

import java.io.InputStream;
import java.io.OutputStream;
import java.io.ByteArrayOutputStream;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class UTF8StreamJsonParserTest {

    @Mock
    private ObjectReadContext mockReadCtxt;

    @Mock
    private IOContext mockIOContext;

    @Mock
    private InputStream mockInputStream;

    @Mock
    private ByteQuadsCanonicalizer mockSymbols;

    @Mock
    private StreamReadConstraints mockStreamReadConstraints;

    @Mock
    private ErrorReportConfiguration mockErrorReportConfiguration;

    private TextBuffer textBuffer;
    private UTF8StreamJsonParser parser;
    private byte[] inputBuffer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        textBuffer = new TextBuffer(null);

        // Mock IOContext methods used by the ParserBase constructor
        when(mockIOContext.constructReadConstrainedTextBuffer()).thenReturn(textBuffer);
        when(mockIOContext.streamReadConstraints()).thenReturn(mockStreamReadConstraints);
        when(mockIOContext.errorReportConfiguration()).thenReturn(mockErrorReportConfiguration);
        when(mockIOContext.isResourceManaged()).thenReturn(false);

        // Initialize a dummy input buffer
        inputBuffer = new byte[100];
        for (int i = 0; i < inputBuffer.length; i++) {
            inputBuffer[i] = (byte) i;
        }
    }

    private void createParser(int start, int end) {
        parser = new UTF8StreamJsonParser(
                mockReadCtxt,
                mockIOContext,
                0, // stdFeatures
                0, // formatReadFeatures
                mockInputStream,
                mockSymbols,
                inputBuffer,
                start,
                end,
                0, // bytesPreProcessed
                false // bufferRecyclable
        );
    }

    @Test
    public void testReleaseBufferedWithData() throws Exception {
        // Setup: Buffer has 10 bytes (from index 0 to 10)
        createParser(0, 10);

        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

        // Execute
        int count = parser.releaseBuffered(outputStream);

        // Verify
        assertEquals(10, count);
        byte[] written = outputStream.toByteArray();
        assertEquals(10, written.length);
        for (int i = 0; i < 10; i++) {
            assertEquals((byte) i, written[i]);
        }

        // Verify the internal pointer is moved (so next call returns 0)
        int nextCount = parser.releaseBuffered(outputStream);
        assertEquals(0, nextCount);
    }

    @Test
    public void testReleaseBufferedEmptyBuffer() throws Exception {
        // Setup: Buffer is empty (start == end)
        createParser(10, 10);

        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

        // Execute
        int count = parser.releaseBuffered(outputStream);

        // Verify
        assertEquals(0, count);
    }

    @Test
    public void testWillInternPropertyNamesWhenEnabled() throws Exception {
        when(mockSymbols.willInternStrings()).thenReturn(true);
        createParser(0, 0);

        assertTrue(parser.willInternPropertyNames());
    }

    @Test
    public void testWillInternPropertyNamesWhenDisabled() throws Exception {
        when(mockSymbols.willInternStrings()).thenReturn(false);
        createParser(0, 0);

        assertFalse(parser.willInternPropertyNames());
    }

    @Test
    public void testStreamReadInputSource() throws Exception {
        createParser(0, 0);

        Object source = parser.streamReadInputSource();

        assertSame(mockInputStream, source);
    }

    @Test
    public void testGetValueAsStringReturnsNullByDefault() throws Exception {
        createParser(0, 0);

        // Current token is null by default
        String result = parser.getValueAsString();

        assertNull(result);
    }
}

