package tools.jackson.core.json;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.io.StringReader;
import java.io.StringWriter;
import java.io.Writer;
import java.math.BigDecimal;
import java.math.BigInteger;

import tools.jackson.core.Base64Variant;
import tools.jackson.core.JsonWriteFeature;
import tools.jackson.core.ObjectWriteContext;
import tools.jackson.core.SerializableString;
import tools.jackson.core.StreamWriteFeature;
import tools.jackson.core.StreamWriteConstraints;
import tools.jackson.core.io.CharacterEscapes;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.PrettyPrinter;

/**
 * Unit tests for {@link WriterBasedJsonGenerator}.
 */
public class WriterBasedJsonGeneratorTest {

    private WriterBasedJsonGenerator generator;
    private StringWriter stringWriter;
    private IOContext ioCtxt;
    private ObjectWriteContext writeCtxt;

    @Before
    public void setUp() throws Exception {
        stringWriter = new StringWriter();

        // Mock ObjectWriteContext
        writeCtxt = mock(ObjectWriteContext.class);
        when(writeCtxt.getStreamWriteFeatures(anyInt())).thenAnswer(i -> i.getArgument(0));
        when(writeCtxt.getFormatWriteFeatures(anyInt())).thenAnswer(i -> i.getArgument(0));
        when(writeCtxt.getCharacterEscapes()).thenReturn(null);
        when(writeCtxt.hasPrettyPrinter()).thenReturn(false);
        when(writeCtxt.getPrettyPrinter()).thenReturn(null);
        when(writeCtxt.getRootValueSeparator(any(SerializableString.class))).thenReturn(null);

        // Mock IOContext
        ioCtxt = mock(IOContext.class);
        when(ioCtxt.allocConcatBuffer()).thenReturn(new char[4000]);
        when(ioCtxt.allocNameCopyBuffer(anyInt())).thenReturn(new char[2000]);
        when(ioCtxt.streamWriteConstraints()).thenReturn(StreamWriteConstraints.defaults());
        when(ioCtxt.isResourceManaged()).thenReturn(false);

        // Create generator with default features
        int streamFeatures = StreamWriteFeature.collectDefaults();
        int formatFeatures = JsonWriteFeature.collectDefaults();

        generator = new WriterBasedJsonGenerator(
                writeCtxt,
                ioCtxt,
                streamFeatures,
                formatFeatures,
                stringWriter,
                null, // rootValueSep
                null, // pp
                null, // charEsc
                0,    // maxNonEscaped
                '"'   // quoteChar
        );
    }

    @Test
    public void testStreamWriteOutputTarget() {
        assertEquals(stringWriter, generator.streamWriteOutputTarget());
    }

    @Test
    public void testStreamWriteOutputBufferedInitiallyZero() {
        assertEquals(0, generator.streamWriteOutputBuffered());
    }

    @Test
    public void testWriteString() throws Exception {
        String output = "test";
        generator.writeString(output);
        generator.flush();
        assertEquals("\"" + output + "\"", stringWriter.toString());
    }

    @Test
    public void testWriteStringWithEscapes() throws Exception {
        // Test escaping of quotes and backslash
        String input = "test\"quote\\slash";
        generator.writeString(input);
        generator.flush();
        // Default escaping: " -> \", \ -> \\
        assertEquals("\"test\\\"quote\\\\slash\"", stringWriter.toString());
    }

    @Test
    public void testWriteNumberInt() throws Exception {
        generator.writeNumber(123);
        generator.flush();
        assertEquals("123", stringWriter.toString());
    }

    @Test
    public void testWriteNumberLong() throws Exception {
        generator.writeNumber(12345678901L);
        generator.flush();
        assertEquals("12345678901", stringWriter.toString());
    }

    @Test
    public void testWriteNumberDouble() throws Exception {
        generator.writeNumber(1.5);
        generator.flush();
        assertEquals("1.5", stringWriter.toString());
    }

    @Test
    public void testWriteNumberBigDecimal() throws Exception {
        generator.writeNumber(new BigDecimal("123.456"));
        generator.flush();
        assertEquals("123.456", stringWriter.toString());
    }

    @Test
    public void testWriteBoolean() throws Exception {
        generator.writeBoolean(true);
        generator.flush();
        assertEquals("true", stringWriter.toString());

        stringWriter.getBuffer().setLength(0);
        generator.writeBoolean(false);
        generator.flush();
        assertEquals("false", stringWriter.toString());
    }

    @Test
    public void testWriteNull() throws Exception {
        generator.writeNull();
        generator.flush();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testWriteStartEndArray() throws Exception {
        generator.writeStartArray();
        generator.writeEndArray();
        generator.flush();
        assertEquals("[]", stringWriter.toString());
    }

    @Test
    public void testWriteStartEndObject() throws Exception {
        generator.writeStartObject();
        generator.writeEndObject();
        generator.flush();
        assertEquals("{}", stringWriter.toString());
    }

    @Test
    public void testWriteName() throws Exception {
        generator.writeStartObject();
        generator.writeName("field");
        generator.writeEndObject();
        generator.flush();
        assertEquals("{\"field\"}", stringWriter.toString());
    }

    @Test
    public void testWriteRaw() throws Exception {
        generator.writeRaw("raw text");
        generator.flush();
        assertEquals("raw text", stringWriter.toString());
    }

    @Test
    public void testWriteRawCharArray() throws Exception {
        char[] chars = {'r', 'a', 'w'};
        generator.writeRaw(chars, 0, 3);
        generator.flush();
        assertEquals("raw", stringWriter.toString());
    }

    @Test
    public void testWriteStringCharArray() throws Exception {
        char[] chars = {'t', 'e', 'x', 't'};
        generator.writeString(chars, 0, 4);
        generator.flush();
        assertEquals("\"text\"", stringWriter.toString());
    }

    @Test
    public void testWriteStringFromReader() throws Exception {
        StringReader reader = new StringReader("reader content");
        // Read max 100 chars (more than available)
        generator.writeString(reader, 100);
        generator.flush();
        assertEquals("\"reader content\"", stringWriter.toString());
    }

    @Test
    public void testWriteBinary() throws Exception {
        // Simple binary data [0, 1, 2] -> "AAEC"
        byte[] data = new byte[]{0, 1, 2};
        // Use default Base64Variant (Standard)
        // Note: writeBinary with byte[] uses default variant implicitly in JsonGenerator, 
        // but here we call the method with variant.
        // Base64Variants is not provided in imports, but writeBinary(byte[]) calls writeBinary(default, ...).
        // However, we can call the variant version if we construct one, but simpler to test the byte[] overload.
        generator.writeBinary(data, 0, data.length);
        generator.flush();
        // Standard Base64: A (0) -> QQ==, A (1) -> AQ==, C (2) -> Ag==
        // Actually: [0,1,2] -> 00 01 02 -> bits: 00000000 00000001 00000010
        // Base64: 000000 000001 000010 -> 0, 1, 2 -> "AAEC"
        assertEquals("\"AAEC\"", stringWriter.toString());
    }

    @Test
    public void testFlush() throws Exception {
        generator.writeString("flushTest");
        // Internal buffer might not be flushed yet
        generator.flush();
        // Verify content is in writer
        assertEquals("\"flushTest\"", stringWriter.toString());
    }

    @Test
    public void testStreamWriteOutputBufferedIncreases() throws Exception {
        // Initially 0
        assertEquals(0, generator.streamWriteOutputBuffered());

        generator.writeNumber(12345);
        // Should have content in buffer (not flushed yet)
        assertTrue(generator.streamWriteOutputBuffered() > 0);

        generator.flush();
        // After flush, buffered should be 0 (assuming it wrote everything)
        // Or it depends on implementation if it keeps copy. Usually 0.
        assertEquals(0, generator.streamWriteOutputBuffered());
    }
}

