    @Test
    public void testNonBlockingInputFeederReturnsSelf() {
        assertSame(parser, parser.nonBlockingInputFeeder());
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputEndBeforeStart() throws JacksonException {
        byte[] buf = new byte[10];
        // end (2) is before start (5)
        parser.feedInput(buf, 5, 2);
    }

    @Test(expected = JacksonException.class)
    public void testFeedInputAfterClosed() throws JacksonException {
        // Signal end of input
        parser.endOfInput();
        // Try to feed more input
        parser.feedInput(new byte[10], 0, 10);
    }

    @Test
    public void testFeedInputUndecodedBytes() throws JacksonException {
        // Feed 3 bytes: { }
        byte[] buf = new byte[]{'{', '}', ' '};
        parser.feedInput(buf, 0, 3);

        // Parse one byte (advances pointer to 1)
        parser.nextToken();

        // Pointer is now 1, End is 3. Still have undecoded bytes.
        // Attempting to feed should fail.
        try {
            parser.feedInput(new byte[10], 0, 10);
            fail("Expected JacksonException for undecoded bytes");
        } catch (JacksonException e) {
            assertTrue(e.getMessage().contains("Still have"));
        }
    }

    @Test
    public void testReleaseBuffered() throws JacksonException {
        // Feed 3 bytes: a b c
        byte[] buf = new byte[]{'a', 'b', 'c'};
        parser.feedInput(buf, 0, 3);

        // Consume first byte 'a' (advances ptr to 1)
        parser.nextToken();

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int released = parser.releaseBuffered(out);

        // Remaining bytes are 'b' and 'c'
        assertEquals(2, released);
        assertEquals("bc", out.toString());
    }

    @Test
    public void testReleaseBufferedEmpty() throws JacksonException {
        // Feed 1 byte
        byte[] buf = new byte[]{'x'};
        parser.feedInput(buf, 0, 1);

        // Consume it
        parser.nextToken();

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int released = parser.releaseBuffered(out);

        assertEquals(0, released);
    }

    @Test
    public void testNormalFeedInput() throws JacksonException {
        byte[] buf = new byte[]{'[', '1', ']', ' '};
        parser.feedInput(buf, 0, 4);

        // Verify constraints validation was called
        verify(mockStreamReadConstraints).validateDocumentLength(anyLong());
    }
}

