package tools.jackson.core.json.async;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;

import org.junit.Before;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;

import tools.jackson.core.ObjectReadContext;
import tools.jackson.core.io.IOContext;
import tools.jackson.core.sym.ByteQuadsCanonicalizer;

public class NonBlockingByteBufferJsonParserTest {

    private ObjectReadContext readContext;
    private IOContext ioContext;
    private ByteQuadsCanonicalizer sym;
    private NonBlockingByteBufferJsonParser parser;

    @Before
    public void setUp() {
        readContext = ObjectReadContext.empty();
        ioContext = mock(IOContext.class);
        when(ioContext.constructReadConstrainedTextBuffer()).thenReturn(new tools.jackson.core.util.TextBuffer(null));
        sym = ByteQuadsCanonicalizer.createRoot(64);
        parser = new NonBlockingByteBufferJsonParser(readContext, ioContext, 0, 0, sym);
    }

    @Test
    public void nonBlockingInputFeederReturnsSelf() {
        assertSame(parser, parser.nonBlockingInputFeeder());
    }

    @Test
    public void feedInputWithValidBuffer() throws Exception {
        ByteBuffer buffer = ByteBuffer.wrap("{\"test\":1}".getBytes("UTF-8"));

        parser.feedInput(buffer);

        // Verify buffer state is set correctly
        // The buffer position should now be at limit
        assertEquals(buffer.limit(), buffer.position());
    }

    @Test
    public void feedInputEndBeforeStartThrowsException() {
        ByteBuffer buffer = ByteBuffer.allocate(10);
        buffer.position(5);
        buffer.limit(3); // limit < position

        try {
            parser.feedInput(buffer);
            fail("Expected JacksonException");
        } catch (tools.jackson.core.JacksonException e) {
            assertTrue(e.getMessage().contains("Input end"));
        }
    }

    @Test
    public void feedInputWithUndecodedBytesThrowsException() throws Exception {
        // First, feed some input
        ByteBuffer buffer1 = ByteBuffer.wrap("{\"a".getBytes("UTF-8"));
        parser.feedInput(buffer1);

        // Try to feed more without consuming - should fail
        ByteBuffer buffer2 = ByteBuffer.wrap("\"b\":1}".getBytes("UTF-8"));
        try {
            parser.feedInput(buffer2);
            fail("Expected JacksonException");
        } catch (tools.jackson.core.JacksonException e) {
            assertTrue(e.getMessage().contains("Still have"));
        }
    }

    @Test
    public void feedInputAfterEndOfInputThrowsException() throws Exception {
        // First, feed some input
        ByteBuffer buffer = ByteBuffer.wrap("{}".getBytes("UTF-8"));
        parser.feedInput(buffer);

        // End input
        parser.endOfInput();

        // Try to feed more after endOfInput
        ByteBuffer buffer2 = ByteBuffer.wrap("{}".getBytes("UTF-8"));
        try {
            parser.feedInput(buffer2);
            fail("Expected JacksonException");
        } catch (tools.jackson.core.JacksonException e) {
            assertTrue(e.getMessage().contains("Already closed"));
        }
    }

    @Test
    public void releaseBufferedWithNoDataReturnsZero() throws Exception {
        ByteBuffer buffer = ByteBuffer.wrap("{}".getBytes("UTF-8"));
        parser.feedInput(buffer);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        int result = parser.releaseBuffered(baos);

        assertEquals(0, result);
    }

    @Test
    public void releaseBufferedWithDataWritesToStream() throws Exception {
        // Feed a JSON object and consume some of it
        ByteBuffer buffer = ByteBuffer.wrap("{\"key\":\"value\"}".getBytes("UTF-8"));
        parser.feedInput(buffer);

        // Read past some of the input
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "key"

        // Now release remaining buffered data
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        int result = parser.releaseBuffered(baos);

        assertTrue(result > 0);
    }

    @Test
    public void getNextSignedByteFromBuffer() throws Exception {
        byte[] data = new byte[] { 0x01, (byte)0xFF, 0x7F, (byte)0x80 };
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(0x01, parser.getNextSignedByteFromBuffer());
        assertEquals((byte)0xFF, parser.getNextSignedByteFromBuffer());
        assertEquals(0x7F, parser.getNextSignedByteFromBuffer());
        assertEquals((byte)0x80, parser.getNextSignedByteFromBuffer());
    }

    @Test
    public void getNextUnsignedByteFromBuffer() throws Exception {
        byte[] data = new byte[] { 0x01, (byte)0xFF, 0x7F, (byte)0x80 };
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(0x01, parser.getNextUnsignedByteFromBuffer());
        assertEquals(0xFF, parser.getNextUnsignedByteFromBuffer());
        assertEquals(0x7F, parser.getNextUnsignedByteFromBuffer());
        assertEquals(0x80, parser.getNextUnsignedByteFromBuffer());
    }

    @Test
    public void getByteFromBuffer() throws Exception {
        byte[] data = new byte[] { 0x01, 0x02, 0x03, 0x04 };
        ByteBuffer buffer = ByteBuffer.wrap(data);
        parser.feedInput(buffer);

        assertEquals(0x01, parser.getByteFromBuffer(0));
        assertEquals(0x02, parser.getByteFromBuffer(1));
        assertEquals(0x03, parser.getByteFromBuffer(2));
        assertEquals(0x04, parser.getByteFromBuffer(3));
    }

    @Test
    public void feedInputEmptyBuffer() throws Exception {
        ByteBuffer buffer = ByteBuffer.allocate(0);

        parser.feedInput(buffer);

        // Should not throw - empty buffer is valid
    }

    @Test
    public void feedInputWithZeroLengthBuffer() throws Exception {
        byte[] empty = new byte[0];
        ByteBuffer buffer = ByteBuffer.wrap(empty);

        parser.feedInput(buffer);

        assertEquals(0, buffer.position());
    }
}

