package tools.jackson.core.sym;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

import org.junit.Before;
import org.junit.Test;

import tools.jackson.core.util.Named;

import static org.junit.Assert.*;

/**
 * Unit tests for {@link BinaryNameMatcher}.
 */
public class BinaryNameMatcherTest {

    private BinaryNameMatcher matcher;

    @Before
    public void setUp() {
        // Setup method, though we will create new matchers in tests
    }

    // Factory helper
    private BinaryNameMatcher createMatcher(String... names) {
        List<String> list = new ArrayList<>();
        for (String name : names) {
            list.add(name);
        }
        return BinaryNameMatcher.construct(list);
    }

    // Helper to create Named list
    private List<Named> createNamedList(String... names) {
        List<Named> list = new ArrayList<>();
        for (String name : names) {
            list.add(Named.fromString(name));
        }
        return list;
    }

    @Test
    public void testEmptyMatcherSize() {
        matcher = createMatcher();
        assertEquals(0, matcher.size());
        assertTrue(matcher.primaryQuadCount() == 0);
    }

    @Test
    public void testSingleShortName() {
        matcher = createMatcher("Test");

        assertEquals(1, matcher.size());

        // Verify by name lookup
        assertEquals(0, matcher.matchName("Test"));
        assertEquals(-2, matcher.matchName("NoSuchName")); // MATCH_UNKNOWN_NAME
    }

    @Test
    public void testSingleMediumName() {
        String name = "12345678"; // 8 bytes
        matcher = createMatcher(name);

        assertEquals(1, matcher.size());
        assertEquals(0, matcher.matchName(name));
    }

    @Test
    public void testSingleLongName() {
        String name = "12345678901234"; // 14 bytes (> 12)
        matcher = createMatcher(name);

        assertEquals(1, matcher.size());
        assertEquals(0, matcher.matchName(name));
    }

    @Test
    public void testMultipleNamesAndCounts() {
        // Add enough to potentially trigger secondary buckets (16 entries usually)
        String[] names = {"a", "b", "c", "d", "e", "f", "g", "h",
                          "i", "j", "k", "l", "m", "n", "o", "p"};

        matcher = createMatcher(names);

        assertEquals(16, matcher.size());
        assertTrue(matcher.totalCount() > 0);

        // Verify name lookup
        assertEquals(0, matcher.matchName("a"));
        assertEquals(15, matcher.matchName("p"));
    }

    @Test
    public void testMatchByQuadShort() {
        matcher = createMatcher("Ab");

        // "Ab" is 2 bytes. 
        // _decodeLast for 2 bytes: (b[offset] & 0xFF) << 8 | (b[offset+1] & 0xFF) ?
        // Looking at _decodeLast: switch(bytes).
        // case 2: value = (value << 8) | (b[offset++] & 0xFF);
        // So 'A' (0x41) << 8 | 'b' (0x62) => 0x4162

        int[] quads = BinaryNameMatcher._quads("Ab");
        assertTrue(quads.length >= 1);

        int index = matcher.matchByQuad(quads[0]);
        assertEquals(0, index);
    }

    @Test
    public void testMatchByQuadMedium() {
        matcher = createMatcher("ABCDEF12"); // 8 bytes

        int[] quads = BinaryNameMatcher._quads("ABCDEF12");
        // Should be 2 quads
        assertEquals(2, quads.length);

        int index = matcher.matchByQuad(quads[0], quads[1]);
        assertEquals(0, index);
    }

    @Test
    public void testMatchByQuadLong() {
