package tools.jackson.core.sym;

import java.util.Arrays;

import org.junit.Test;

import tools.jackson.core.json.JsonFactory;
import tools.jackson.core.exc.StreamConstraintsException;

import static org.junit.Assert.*;

public class ByteQuadsCanonicalizerTest
{
    @Test
    public void testCreateRootDefault() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot();
        assertNotNull(root);
        assertEquals(0, root.size());
        assertTrue(root.isCanonicalizing());
    }

    @Test
    public void testCreateRootWithSeed() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(12345);
        assertNotNull(root);
        assertEquals(0, root.size());
        assertEquals(12345, root.hashSeed());
    }

    @Test
    public void testMakeChild() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int flags = JsonFactory.Feature.INTERN_PROPERTY_NAMES.getMask()
                | JsonFactory.Feature.FAIL_ON_SYMBOL_HASH_OVERFLOW.getMask()
                | JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask();
        ByteQuadsCanonicalizer child = root.makeChild(flags);

        assertNotNull(child);
        assertTrue(child.isCanonicalizing());
        assertFalse(child.willInternStrings());
    }

    @Test
    public void testMakeChildWithInternEnabled() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int flags = JsonFactory.Feature.INTERN_PROPERTY_NAMES.getMask()
                | JsonFactory.Feature.FAIL_ON_SYMBOL_HASH_OVERFLOW.getMask()
                | JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask();
        ByteQuadsCanonicalizer child = root.makeChild(flags);

        assertTrue(child.willInternStrings());
    }

    @Test
    public void testMakeChildOrPlaceholderWhenCanonicalizationDisabled() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int flags = 0; // CANONICALIZE_PROPERTY_NAMES disabled
        ByteQuadsCanonicalizer placeholder = root.makeChildOrPlaceholder(flags);

        assertNotNull(placeholder);
        assertFalse(placeholder.isCanonicalizing());
    }

    @Test
    public void testMakeChildOrPlaceholderWhenCanonicalizationEnabled() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int flags = JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask();
        ByteQuadsCanonicalizer child = root.makeChildOrPlaceholder(flags);

        assertNotNull(child);
        assertTrue(child.isCanonicalizing());
    }

    @Test
    public void testInitialSizeIsZero() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertEquals(0, root.size());
    }

    @Test
    public void testAddSingleQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41; // 'A'

        String name = root.addName("A", q1);

        assertEquals("A", name);
        assertEquals(1, root.size());
    }

    @Test
    public void testFindSingleQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41; // 'A'

        root.addName("A", q1);

        String found = root.findName(q1);
        assertEquals("A", found);
    }

    @Test
    public void testFindNonExistentSingleQuadName() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);

        String found = root.findName(0x41);

        assertNull(found);
    }

    @Test
    public void testAddTwoQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41; // 'A'
        int q2 = 0x42; // 'B'

        String name = root.addName("AB", q1, q2);

        assertEquals("AB", name);
        assertEquals(1, root.size());
    }

    @Test
    public void testFindTwoQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41;
        int q2 = 0x42;

        root.addName("AB", q1, q2);

        String found = root.findName(q1, q2);
        assertEquals("AB", found);
    }

    @Test
    public void testFindNonExistentTwoQuadName() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);

        String found = root.findName(0x41, 0x42);

        assertNull(found);
    }

    @Test
    public void testAddThreeQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41;
        int q2 = 0x42;
        int q3 = 0x43;

        String name = root.addName("ABC", q1, q2, q3);

        assertEquals("ABC", name);
        assertEquals(1, root.size());
    }

    @Test
    public void testFindThreeQuadName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int q1 = 0x41;
        int q2 = 0x42;
        int q3 = 0x43;

        root.addName("ABC", q1, q2, q3);

        String found = root.findName(q1, q2, q3);
        assertEquals("ABC", found);
    }

    @Test
    public void testAddLongName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int[] quads = new int[] { 0x41, 0x42, 0x43, 0x44, 0x45 };

        String name = root.addName("ABCDE", quads, quads.length);

        assertEquals("ABCDE", name);
        assertEquals(1, root.size());
    }

    @Test
    public void testFindLongName() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int[] quads = new int[] { 0x41, 0x42, 0x43, 0x44, 0x45 };

        root.addName("ABCDE", quads, quads.length);

        String found = root.findName(quads, quads.length);
        assertEquals("ABCDE", found);
    }

    @Test
    public void testFindNonExistentLongName() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int[] quads = new int[] { 0x41, 0x42, 0x43, 0x44, 0x45 };

        String found = root.findName(quads, quads.length);

        assertNull(found);
    }

    @Test
    public void testMultipleNames() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);

        root.addName("A", 0x41);
        root.addName("B", 0x42);
        root.addName("C", 0x43);

        assertEquals(3, root.size());
        assertEquals("A", root.findName(0x41));
        assertEquals("B", root.findName(0x42));
        assertEquals("C", root.findName(0x43));
    }

    @Test
    public void testCollisionHandling() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        // Force collision by using same hash (different quads but same hash)
        // This is hard to guarantee without knowing the hash algorithm
        // Just test that adding multiple names works
        for (int i = 0; i < 100; i++) {
            root.addName("name" + i, i);
        }
        assertEquals(100, root.size());
    }

    @Test
    public void testCalcHashSingleQuad() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int hash1 = root.calcHash(0x41);
        int hash2 = root.calcHash(0x41);
        assertEquals(hash1, hash2);
    }

    @Test
    public void testCalcHashTwoQuads() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int hash1 = root.calcHash(0x41, 0x42);
        int hash2 = root.calcHash(0x41, 0x42);
        assertEquals(hash1, hash2);
    }

    @Test
    public void testCalcHashThreeQuads() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int hash1 = root.calcHash(0x41, 0x42, 0x43);
        int hash2 = root.calcHash(0x41, 0x42, 0x43);
        assertEquals(hash1, hash2);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCalcHashArrayTooShort() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int[] quads = new int[] { 0x41, 0x42, 0x43 };
        root.calcHash(quads, 3);
    }

    @Test
    public void testCalcHashArrayValid() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int[] quads = new int[] { 0x41, 0x42, 0x43, 0x44 };
        int hash = root.calcHash(quads, 4);
        assertTrue(hash != 0);
    }

    @Test
    public void testMultiplyByFourFifths() {
        // Test the static utility method
        assertEquals(0, ByteQuadsCanonicalizer.multiplyByFourFifths(0));
        assertTrue(ByteQuadsCanonicalizer.multiplyByFourFifths(10) > 0);
    }

    @Test
    public void testBucketCount() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        int bucketCount = root.bucketCount();
        assertTrue(bucketCount >= 64); // DEFAULT_T_SIZE
    }

    @Test
    public void testPrimaryCountEmpty() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertEquals(0, root.primaryCount());
    }

    @Test
    public void testPrimaryCountAfterAdd() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        root.addName("A", 0x41);
        assertTrue(root.primaryCount() >= 1);
    }

    @Test
    public void testSecondaryCountEmpty() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertEquals(0, root.secondaryCount());
    }

    @Test
    public void testTertiaryCountEmpty() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertEquals(0, root.tertiaryCount());
    }

    @Test
    public void testTotalCountEmpty() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertEquals(0, root.totalCount());
    }

    @Test
    public void testTotalCountAfterAdd() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        root.addName("A", 0x41);
        root.addName("B", 0x42);
        root.addName("C", 0x43);
        assertEquals(3, root.totalCount());
    }

    @Test
    public void testToString() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        String str = root.toString();
        assertNotNull(str);
        assertTrue(str.contains("ByteQuadsCanonicalizer"));
        assertTrue(str.contains("size="));
    }

    @Test
    public void testMaybeDirtyInitial() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        assertFalse(root.maybeDirty());
    }

    @Test
    public void testMaybeDirtyAfterAdd() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        ByteQuadsCanonicalizer child = root.makeChild(JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask());

        child.addName("A", 0x41);

        assertTrue(child.maybeDirty());
    }

    @Test
    public void testReleaseNoParent() {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        root.release(); // Should not throw
    }

    @Test
    public void testReleaseWithParent() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);
        ByteQuadsCanonicalizer child = root.makeChild(JsonFactory.Feature.CANONICALIZE_PROPERTY_NAMES.getMask());

        child.addName("A", 0x41);
        child.release();

        // Child should be clean after release
        assertFalse(child.maybeDirty());
    }

    @Test
    public void testFindNameWithQLenLessThan4Delegates() throws StreamConstraintsException {
        ByteQuadsCanonicalizer root = ByteQuadsCanonicalizer.createRoot(100);

        root.addName("A", 0x41);
        root.addName("AB", 0x41, 0x42);
        root.addName("ABC", 0x41, 0x42, 0x43);

        int[] quads3 = new int[] { 0x41, 0x42, 0x43 };
        int[] quads2 = new int[] { 0x41, 0x42 };
        int[] quads1 = new int[] { 0x41 };

        assertEquals("ABC", root.findName(quads3, 3));
        assertEquals("AB", root.findName(quads2, 2));
        assertEquals("A", root.findName(quads1, 1));
    }

    @Test
    public void testHashSeedConsistency() {
        ByteQuadsCanonicalizer root1 = ByteQuadsCanonicalizer.createRoot(42);
        ByteQuadsCanonicalizer root2 = ByteQuadsCanonicalizer.createRoot(42);

        assertEquals(root1.hashSeed(), root2.hashSeed());
    }
}

