package tools.jackson.core.sym;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import tools.jackson.core.JsonFactory;
import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.TokenStreamFactory;
import tools.jackson.core.exc.StreamConstraintsException;

/**
 * Unit tests for {@link CharsToNameCanonicalizer}.
 */
public class CharsToNameCanonicalizerTest {

    @Test
    public void testRootCreation() {
        CharsToNameCanonicalizer root = CharsToNameCanonicalizer.createRoot(new JsonFactory());
        assertNotNull(root);
        assertEquals(0, root.size());
        assertEquals(64, root.bucketCount()); // Default size
    }

    @Test
    public void testFindSymbolBasic() {
        CharsToNameCanonicalizer root = CharsToNameCanonicalizer.createRoot(new JsonFactory());
        CharsToNameCanonicalizer table = root.makeChild();

        String result = table.findSymbol("test".toCharArray(), 0, 4, table.calcHash("test"));
        assertEquals("test", result);
        assertEquals(1, table.size());

        // Second call should return the same instance (canonicalized)
        String result2 = table.findSymbol("test".toCharArray(), 0, 4, table.calcHash("test"));
        assertSame(result, result2);
    }

    @Test
