package tools.jackson.core.sym;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

import org.junit.Test;

import tools.jackson.core.util.Named;

import static org.junit.Assert.*;

public class SimpleNameMatcherTest {

    @Test
    public void testBasicConstructAndMatch() {
        List<String> names = Arrays.asList("first", "second", "third");
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, names);

        assertTrue("Should find 'first'", matcher.matchName("first") >= 0);
        assertTrue("Should find 'second'", matcher.matchName("second") >= 0);
        assertTrue("Should find 'third'", matcher.matchName("third") >= 0);

        assertEquals("Should not find unknown name", PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("fourth"));
    }

    @Test
    public void testCaseSensitiveMatch() {
        List<String> names = Arrays.asList("Property", "Name");
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, names);

        // Exact match
        assertTrue(matcher.matchName("Property") >= 0);

        // Case mismatch
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("property"));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("PROPERTY"));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("Name"));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("NAME"));
    }

    @Test(expected = NullPointerException.class)
    public void testMatchWithNullNameThrows() {
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, Arrays.asList("valid"));
        // matchName(String) calls toMatch.hashCode() which throws NPE on null
        matcher.matchName(null);
    }

    @Test
    public void testConstructSkipsNullNames() {
        List<String> names = new ArrayList<>();
        names.add("valid1");
        names.add(null);
        names.add("valid2");

        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, names);

        assertTrue(matcher.matchName("valid1") >= 0);
        assertTrue(matcher.matchName("valid2") >= 0);
        // Note: we can't easily verify index assignment here without internal access, 
        // but verifying they exist is sufficient.
    }

    @Test
    public void testConstructCaseInsensitive() {
        List<String> names = Arrays.asList("Hello", "World");
        SimpleNameMatcher matcher = SimpleNameMatcher.constructCaseInsensitive(Locale.US, names);

        // Case insensitive matches
        assertTrue(matcher.matchName("Hello") >= 0);
        assertTrue(matcher.matchName("hello") >= 0);
        assertTrue(matcher.matchName("HELLO") >= 0);

        assertTrue(matcher.matchName("World") >= 0);
        assertTrue(matcher.matchName("world") >= 0);

        // Non-matches
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("Goodbye"));
    }

    @Test
    public void testMatchByQuadReturnsUnknown() {
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, Arrays.asList("name"));

        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchByQuad(1));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchByQuad(1, 2));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchByQuad(1, 2, 3));
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchByQuad(new int[]{1, 2, 3}, 3));
    }

    @Test
    public void testConstructFromWithNamed() {
        List<Named> namedList = new ArrayList<>();
        namedList.add(Named.fromString("namedProp"));
        namedList.add(new Named.StringAsNamed("anotherProp"));

        SimpleNameMatcher matcher = SimpleNameMatcher.constructFrom(Locale.US, namedList, false);

        assertTrue(matcher.matchName("namedProp") >= 0);
        assertTrue(matcher.matchName("anotherProp") >= 0);
    }

    @Test
    public void testEmptyList() {
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, new ArrayList<>());
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("anything"));
    }

    @Test
    public void testManyNamesWithCollisions() {
        // Add many names to force spillover and resizing logic
        List<String> names = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            names.add("name" + i);
        }
        SimpleNameMatcher matcher = SimpleNameMatcher.construct(Locale.US, names);

        for (int i = 0; i < 100; i++) {
            assertTrue("Should find name" + i, matcher.matchName("name" + i) >= 0);
        }
        assertEquals(PropertyNameMatcher.MATCH_UNKNOWN_NAME, matcher.matchName("name100"));
    }
}

