        assertNull(typeId.forValue);
        assertNull(typeId.forValueType);
        assertNull(typeId.id);
        assertNull(typeId.asProperty);
        assertNull(typeId.include);
        assertNull(typeId.valueShape);
        assertFalse(typeId.wrapperWritten);
        assertNull(typeId.extra);
    }

    @Test
    public void testConstructorWithValueAndShape() {
        Object value = new Object();
        JsonToken shape = JsonToken.START_OBJECT;

        WritableTypeId typeId = new WritableTypeId(value, shape);

        assertSame(value, typeId.forValue);
        assertNull(typeId.forValueType);
        assertNull(typeId.id);
        assertSame(shape, typeId.valueShape);
    }

    @Test
    public void testConstructorWithValueType() {
        Object value = new Object();
        Class<String> valueType = String.class;
        JsonToken shape = JsonToken.VALUE_STRING;

        WritableTypeId typeId = new WritableTypeId(value, valueType, shape);

        assertSame(value, typeId.forValue);
        assertSame(valueType, typeId.forValueType);
        assertNull(typeId.id);
        assertSame(shape, typeId.valueShape);
    }

    @Test
    public void testConstructorWithId() {
        Object value = new Object();
        JsonToken shape = JsonToken.START_ARRAY;
        Object id = "myTypeId";

        WritableTypeId typeId = new WritableTypeId(value, shape, id);

        assertSame(value, typeId.forValue);
        assertSame(id, typeId.id);
        assertSame(shape, typeId.valueShape);
    }

    @Test
    public void testInclusionEnumValues() {
        WritableTypeId.Inclusion[] inclusions = WritableTypeId.Inclusion.values();

        assertEquals(5, inclusions.length);
        assertNotNull(WritableTypeId.Inclusion.WRAPPER_ARRAY);
        assertNotNull(WritableTypeId.Inclusion.WRAPPER_OBJECT);
        assertNotNull(WritableTypeId.Inclusion.METADATA_PROPERTY);
        assertNotNull(WritableTypeId.Inclusion.PAYLOAD_PROPERTY);
        assertNotNull(WritableTypeId.Inclusion.PARENT_PROPERTY);
    }

    @Test
    public void testRequiresObjectContext() {
        assertFalse(WritableTypeId.Inclusion.WRAPPER_ARRAY.requiresObjectContext());
        assertFalse(WritableTypeId.Inclusion.WRAPPER_OBJECT.requiresObjectContext());
        assertTrue(WritableTypeId.Inclusion.METADATA_PROPERTY.requiresObjectContext());
        assertTrue(WritableTypeId.Inclusion.PAYLOAD_PROPERTY.requiresObjectContext());
        assertFalse(WritableTypeId.Inclusion.PARENT_PROPERTY.requiresObjectContext());
    }

    @Test
    public void testFieldMutability() {
        WritableTypeId typeId = new WritableTypeId();

        Object value = new Object();
        Class<?> valueType = Number.class;
        Object id = "testId";
        String property = "type";
        WritableTypeId.Inclusion inclusion = WritableTypeId.Inclusion.METADATA_PROPERTY;
        JsonToken shape = JsonToken.START_OBJECT;
        boolean wrapperWritten = true;
        Object extra = new Object();

        typeId.forValue = value;
        typeId.forValueType = valueType;
        typeId.id = id;
        typeId.asProperty = property;
        typeId.include = inclusion;
        typeId.valueShape = shape;
        typeId.wrapperWritten = wrapperWritten;
        typeId.extra = extra;

        assertSame(value, typeId.forValue);
        assertSame(valueType, typeId.forValueType);
        assertSame(id, typeId.id);
        assertSame(property, typeId.asProperty);
        assertSame(inclusion, typeId.include);
        assertSame(shape, typeId.valueShape);
        assertTrue(typeId.wrapperWritten);
        assertSame(extra, typeId.extra);
    }

    @Test
    public void testNullValues() {
        WritableTypeId typeId = new WritableTypeId(null, JsonToken.VALUE_NULL);

        assertNull(typeId.forValue);
        assertNull(typeId.id);
        assertEquals(JsonToken.VALUE_NULL, typeId.valueShape);
    }

    @Test
    public void testVariousValueShapes() {
        Object value = new Object();

        WritableTypeId arrayTypeId = new WritableTypeId(value, JsonToken.START_ARRAY);
        assertEquals(JsonToken.START_ARRAY, arrayTypeId.valueShape);

