        assertEquals(JsonToken.START_OBJECT, objectTypeId.valueShape);

        WritableTypeId stringTypeId = new WritableTypeId(value, JsonToken.VALUE_STRING);
        assertEquals(JsonToken.VALUE_STRING, stringTypeId.valueShape);

        WritableTypeId numberTypeId = new WritableTypeId(value, JsonToken.VALUE_NUMBER_INT);
        assertEquals(JsonToken.VALUE_NUMBER_INT, numberTypeId.valueShape);

        WritableTypeId boolTypeId = new WritableTypeId(value, JsonToken.VALUE_TRUE);
        assertEquals(JsonToken.VALUE_TRUE, boolTypeId.valueShape);
    }

    @Test
    public void testStringId() {
        Object value = new Object();
        String typeId = "com.example.MyClass";

        WritableTypeId writableTypeId = new WritableTypeId(value, JsonToken.START_OBJECT, typeId);

        assertSame(typeId, writableTypeId.id);
    }
