package tools.jackson.core.util;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.junit.Before;
import org.junit.Test;

public class BufferRecyclerTest {

    private BufferRecycler recycler;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
    }

    @Test
    public void testDefaultConstructor() {
        BufferRecycler br = new BufferRecycler();
        assertFalse(br.isLinkedWithPool());
    }

    @Test
    public void testProtectedConstructorWithCounts() {
        BufferRecycler br = new BufferRecycler(2, 2);
        assertFalse(br.isLinkedWithPool());
    }

    @Test
    public void testByteBufferAllocationDefaultSize() {
        byte[] buf = recycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER);
        assertNotNull(buf);
        assertTrue(buf.length >= 8000);
    }

    @Test
    public void testByteBufferAllocationWithMinSize() {
        byte[] buf = recycler.allocByteBuffer(BufferRecycler.BYTE_WRITE_ENCODING_BUFFER, 16000);
        assertNotNull(buf);
        assertTrue(buf.length >= 16000);
    }

    @Test
    public void testByteBufferAllocationMinSizeLessThanDefault() {
        byte[] buf = recycler.allocByteBuffer(BufferRecycler.BYTE_WRITE_CONCAT_BUFFER, 100);
        assertNotNull(buf);
        assertTrue(buf.length >= 2000);
    }

    @Test
    public void testCharBufferAllocationDefaultSize() {
        char[] buf = recycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER);
        assertNotNull(buf);
        assertTrue(buf.length >= 4000);
    }

    @Test
    public void testCharBufferAllocationWithMinSize() {
        char[] buf = recycler.allocCharBuffer(BufferRecycler.CHAR_CONCAT_BUFFER, 8000);
        assertNotNull(buf);
        assertTrue(buf.length >= 8000);
    }

    @Test
    public void testCharBufferAllocationMinSizeLessThanDefault() {
        char[] buf = recycler.allocCharBuffer(BufferRecycler.CHAR_TEXT_BUFFER, 50);
        assertNotNull(buf);
        assertTrue(buf.length >= 200);
    }

    @Test
    public void testByteBufferReleaseAndRealloc() {
        byte[] buf1 = recycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER);
        int len1 = buf1.length;
        recycler.releaseByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER, buf1);
        byte[] buf2 = recycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER);
        assertSame("Buffer should be recycled", buf1, buf2);
        assertTrue(buf2.length >= len1);
    }

    @Test
    public void testByteBufferReleaseWithLargerBuffer() {
        byte[] buf1 = recycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER);
        recycler.releaseByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER, buf1);
        byte[] largerBuf = new byte[16000];
        recycler.releaseByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER, largerBuf);
        byte[] buf2 = recycler.allocByteBuffer(BufferRecycler.BYTE_READ_IO_BUFFER);
        assertSame("Larger buffer should be retained", largerBuf, buf2);
    }

    @Test
    public void testCharBufferReleaseAndRealloc() {
        char[] buf1 = recycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER);
        int len1 = buf1.length;
        recycler.releaseCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER, buf1);
        char[] buf2 = recycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER);
        assertSame("Buffer should be recycled", buf1, buf2);
        assertTrue(buf2.length >= len1);
    }

    @Test
    public void testCharBufferReleaseWithLargerBuffer() {
        char[] buf1 = recycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER);
        recycler.releaseCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER, buf1);
        char[] largerBuf = new char[8000];
        recycler.releaseCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER, largerBuf);
        char[] buf2 = recycler.allocCharBuffer(BufferRecycler.CHAR_TOKEN_BUFFER);
        assertSame("Larger buffer should be retained", largerBuf, buf2);
    }

    @Test
    public void testByteBufferReleaseToEmptySlot() {
        byte[] buf = new byte[1000];
        recycler.releaseByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER, buf);
        byte[] retrieved = recycler.allocByteBuffer(BufferRecycler.BYTE_BASE64_CODEC_BUFFER);
        assertSame(buf, retrieved);
    }

    @Test
    public void testCharBufferReleaseToEmptySlot() {
        char[] buf = new char[1000];
        recycler.releaseCharBuffer(BufferRecycler.CHAR_NAME_COPY_BUFFER, buf);
        char[] retrieved = recycler.allocCharBuffer(BufferRecycler.CHAR_NAME_COPY_BUFFER);
        assertSame(buf, retrieved);
    }

    @Test
    public void testIsLinkedWithPoolInitiallyFalse() {
        assertFalse(recycler.isLinkedWithPool());
    }

    @Test
    public void testWithPoolLinksCorrectly() {
        @SuppressWarnings("unchecked")
        RecyclerPool<BufferRecycler> mockPool = mock(RecyclerPool.class);
