import tools.jackson.core.JacksonException;
import tools.jackson.core.JsonGenerator;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class DefaultIndenterTest {

    @Mock
    private JsonGenerator mockJsonGenerator;

    private DefaultIndenter defaultIndenter;

    @Before
    public void setUp() {
        defaultIndenter = new DefaultIndenter();
    }

    @Test
    public void testSysLfNotNull() {
        assertNotNull("SYS_LF should not be null", DefaultIndenter.SYS_LF);
    }

    @Test
    public void testSystemLinefeedInstanceNotNull() {
        assertNotNull("Static instance should not be null", DefaultIndenter.SYSTEM_LINEFEED_INSTANCE);
    }

    @Test
    public void testDefaultConstructorIndent() {
        DefaultIndenter di = new DefaultIndenter();
        assertEquals("Default indent should be 2 spaces", "  ", di.getIndent());
    }

    @Test
    public void testDefaultConstructorEol() {
        DefaultIndenter di = new DefaultIndenter();
        assertEquals("Default EOL should be system line separator", DefaultIndenter.SYS_LF, di.getEol());
    }

    @Test
    public void testCustomConstructor() {
        String indent = "\t";
        String eol = "\r\n";
        DefaultIndenter di = new DefaultIndenter(indent, eol);
        assertEquals("Custom indent should match", indent, di.getIndent());
        assertEquals("Custom EOL should match", eol, di.getEol());
    }

    @Test
    public void testWithLinefeedReturnsSameInstance() {
        // Calling with same EOL should return same instance
        String currentEol = defaultIndenter.getEol();
        assertSame("Should return same instance when EOL is unchanged", defaultIndenter, defaultIndenter.withLinefeed(currentEol));
    }

    @Test
    public void testWithLinefeedReturnsNewInstance() {
        // Calling with different EOL should return new instance
        String newEol = "\n";
        DefaultIndenter newIndenter = defaultIndenter.withLinefeed(newEol);

        assertNotSame("Should return different instance when EOL changes", defaultIndenter, newIndenter);
        assertEquals("New instance should have new EOL", newEol, newIndenter.getEol());
        // Original should be unchanged
        assertEquals("Original instance EOL should be unchanged", defaultIndenter.getEol(), defaultIndenter.getEol());
    }

    @Test
    public void testWithIndentReturnsSameInstance() {
        // Calling with same indent should return same instance
        String currentIndent = defaultIndenter.getIndent();
        assertSame("Should return same instance when indent is unchanged", defaultIndenter, defaultIndenter.withIndent(currentIndent));
    }

    @Test
    public void testWithIndentReturnsNewInstance() {
        // Calling with different indent should return new instance
        String newIndent = "--";
        DefaultIndenter newIndenter = defaultIndenter.withIndent(newIndent);

        assertNotSame("Should return different instance when indent changes", defaultIndenter, newIndenter);
        assertEquals("New instance should have new indent", newIndent, newIndenter.getIndent());
    }

    @Test
    public void testIsInline() {
        assertFalse("DefaultIndenter is not inline", defaultIndenter.isInline());
    }

    @Test
    public void testWriteIndentationWithLevelZero() throws JacksonException {
        // When level is 0, only EOL should be written
        defaultIndenter.writeIndentation(mockJsonGenerator, 0);

        verify(mockJsonGenerator).writeRaw(defaultIndenter.getEol());
        // No indentation should be written
        verifyNoMoreInteractions(mockJsonGenerator);
    }

    @Test
    public void testWriteIndentationWithNegativeLevel() throws JacksonException {
        // When level is negative, only EOL should be written (as per current implementation)
        defaultIndenter.writeIndentation(mockJsonGenerator, -5);

        verify(mockJsonGenerator).writeRaw(defaultIndenter.getEol());
        verifyNoMoreInteractions(mockJsonGenerator);
    }

    @Test
    public void testWriteIndentationWithLevelOne() throws JacksonException {
        // Default indent is "  " (2 chars). Level 1 -> 2 chars.
        defaultIndenter.writeIndentation(mockJsonGenerator, 1);

        String eol = defaultIndenter.getEol();
        verify(mockJsonGenerator).writeRaw(eol);

        // Verify indentation is written (2 chars from start of indents array)
        verify(mockJsonGenerator).writeRaw(any(char[].class), eq(0), eq(2));
        verifyNoMoreInteractions(mockJsonGenerator);
    }

    @Test
    public void testWriteIndentationWithLevelTwo() throws JacksonException {
        // Level 2 * 2 chars = 4 chars
        defaultIndenter.writeIndentation(mockJsonGenerator, 2);

        verify(mockJsonGenerator).writeRaw(defaultIndenter.getEol());
        verify(mockJsonGenerator).writeRaw(any(char[].class), eq(0), eq(4));
        verifyNoMoreInteractions(mockJsonGenerator);
    }

    @Test
    public void testWriteIndentationDeepLevel() throws JacksonException {
        // Default: 2 chars per level. INDENT_LEVELS = 16. Array size = 32.
        // Level 20 -> 40 chars needed.
        // Loop: 40 > 32 -> write 32, level = 8. Exit loop.
        // Write 8.
        defaultIndenter.writeIndentation(mockJsonGenerator, 20);

        verify(mockJsonGenerator).writeRaw(defaultIndenter.getEol());

        // First loop iteration: writes full array
        verify(mockJsonGenerator).writeRaw(any(char[].class), eq(0), eq(32));

        // Final write: remaining 8 chars
        verify(mockJsonGenerator).writeRaw(any(char[].class), eq(0), eq(8));

        verifyNoMoreInteractions(mockJsonGenerator);
    }
}

