        DefaultPrettyPrinter copy = new DefaultPrettyPrinter(original, separators);
        assertNotNull(copy);
    }

    @Test
    public void testNopIndenterInstance() {
        NopIndenter nop = NopIndenter.instance();
        assertNotNull(nop);
        assertSame(nop, NopIndenter.instance());
    }

    @Test
    public void testNopIndenterIsInline() {
