        assertSame(true, nop.isInline());
    }

    @Test
    public void testNopIndenterWriteIndentation() {
        NopIndenter nop = NopIndenter.instance();
        JsonGenerator gen = mock(JsonGenerator.class);
        // Should not throw and should not write anything
        nop.writeIndentation(gen, 5);
        nop.writeIndentation(gen, 0);
        nop.writeIndentation(gen, -1);
    }

    @Test
    public void testFixedSpaceIndenterInstance() {
        FixedSpaceIndenter fsi = FixedSpaceIndenter.instance();
        assertNotNull(fsi);
        assertSame(fsi, FixedSpaceIndenter.instance());
    }

    @Test
    public void testFixedSpaceIndenterIsInline() {
        FixedSpaceIndenter fsi = FixedSpaceIndenter.instance();
        assertSame(true, fsi.isInline());
    }

    @Test
    public void testFixedSpaceIndenterWriteIndentation() throws Exception {
        FixedSpaceIndenter fsi = FixedSpaceIndenter.instance();
        JsonGenerator gen = mock(JsonGenerator.class);
        fsi.writeIndentation(gen, 1);
        verify(gen, times(1)).writeRaw(' ');
    }

    @Test
    public void testIndentArraysWithNull() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentArraysWith(null);
        // Null should be replaced with NopIndenter
    }

    @Test
    public void testIndentArraysWithIndenter() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        NopIndenter nop = NopIndenter.instance();
        printer.indentArraysWith(nop);
    }

    @Test
    public void testIndentObjectsWithNull() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentObjectsWith(null);
        // Null should be replaced with NopIndenter
    }

    @Test
    public void testIndentObjectsWithIndenter() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        NopIndenter nop = NopIndenter.instance();
        printer.indentObjectsWith(nop);
    }

    @Test
    public void testWithArrayIndenterReturnsSameWhenSame() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Indenter indenter = printer.withArrayIndenter(null); // null converts to NopIndenter
        // When same indenter, should return same instance
        Indenter indenter2 = printer.withArrayIndenter(indenter);
        assertSame(indenter, indenter2);
    }

    @Test
    public void testWithArrayIndenterReturnsNewWhenDifferent() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Indenter original = printer.withArrayIndenter(null);
        NopIndenter newIndenter = NopIndenter.instance();
        Indenter result = printer.withArrayIndenter(newIndenter);
        assertNotSame(original, result);
    }

    @Test
    public void testWithObjectIndenterReturnsSameWhenSame() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Indenter indenter = printer.withObjectIndenter(null); // null converts to NopIndenter
        Indenter indenter2 = printer.withObjectIndenter(indenter);
        assertSame(indenter, indenter2);
    }

