    public void testWithObjectIndenterReturnsNewWhenDifferent() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Indenter original = printer.withObjectIndenter(null);
        NopIndenter newIndenter = NopIndenter.instance();
        Indenter result = printer.withObjectIndenter(newIndenter);
        assertNotSame(original, result);
    }

