    public void testWithSeparators() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        Separators separators = Separators.createDefaultInstance();
        DefaultPrettyPrinter result = printer.withSeparators(separators);
        assertNotNull(result);
        assertNotSame(printer, result);
    }

    @Test
    public void testCreateInstance() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        DefaultPrettyPrinter instance = printer.createInstance();
        assertNotNull(instance);
    }

    @Test(expected = IllegalStateException.class)
    public void testCreateInstanceThrowsForSubclass() {
        // Create a subclass that doesn't override createInstance
        DefaultPrettyPrinter subclass = new DefaultPrettyPrinter() {
            // Does not override createInstance
        };
        subclass.createInstance();
    }

    @Test
    public void testWriteRootValueSeparatorWithNull() {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);
        // Default uses default separators which should have a root separator
        printer.writeRootValueSeparator(gen);
        // Verify writeRaw was called with the root value separator
    }

    @Test
    public void testWriteStartObject() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        // Default indenter is not inline, so nesting should increase
        printer.writeStartObject(gen);

        verify(gen).writeRaw('{');
    }

    @Test
    public void testWriteStartObjectWithInlineIndenter() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentObjectsWith(NopIndenter.instance());

        JsonGenerator gen = mock(JsonGenerator.class);
        printer.writeStartObject(gen);

        // With inline indenter, nesting should NOT increase
        verify(gen).writeRaw('{');
    }

    @Test
    public void testWriteEndObjectWithEntries() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        // Simulate nesting by directly manipulating for test
        // Note: We can't easily test nesting without multiple calls, 
        // but we can verify the output

        // First start an object to set up nesting
        printer.writeStartObject(gen);

        // Then end with entries > 0
        printer.writeEndObject(gen, 1);

        verify(gen).writeRaw('}');
    }

    @Test
    public void testWriteEndObjectEmpty() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        // End object with 0 entries should write empty separator
        printer.writeEndObject(gen, 0);

        verify(gen).writeRaw(_getObjectEmptySeparator(printer));
        verify(gen).writeRaw('}');
    }

    @Test
    public void testWriteStartArray() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeStartArray(gen);

        verify(gen).writeRaw('[');
    }

    @Test
    public void testWriteStartArrayWithInlineIndenter() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentArraysWith(NopIndenter.instance());

        JsonGenerator gen = mock(JsonGenerator.class);
        printer.writeStartArray(gen);

        verify(gen).writeRaw('[');
    }

    @Test
    public void testWriteEndArrayWithValues() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeStartArray(gen);
        printer.writeEndArray(gen, 1);

        verify(gen).writeRaw(']');
    }

    @Test
    public void testWriteEndArrayEmpty() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeEndArray(gen, 0);

        verify(gen).writeRaw(_getArrayEmptySeparator(printer));
        verify(gen).writeRaw(']');
    }

    @Test
    public void testWriteObjectNameValueSeparator() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeObjectNameValueSeparator(gen);

        // Should write the separator (default is ": ")
        verify(gen).writeRaw(_getObjectNameValueSeparator(printer));
    }

    @Test
    public void testWriteObjectEntrySeparator() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeObjectEntrySeparator(gen);

        // Should write entry separator + indentation
        verify(gen).writeRaw(_getObjectEntrySeparator(printer));
    }

    @Test
    public void testWriteArrayValueSeparator() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.writeArrayValueSeparator(gen);

        // Should write element separator + indentation
        verify(gen).writeRaw(_getArrayElementSeparator(printer));
    }

    @Test
    public void testBeforeObjectEntries() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.beforeObjectEntries(gen);

        // Should call object indenter
    }

    @Test
    public void testBeforeArrayValues() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        printer.beforeArrayValues(gen);

        // Should call array indenter
    }

    @Test
    public void testFullObjectCycle() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        // Start object
        printer.writeStartObject(gen);

        // Before entries
        printer.beforeObjectEntries(gen);

        // Write name
        printer.writeObjectNameValueSeparator(gen);

        // Entry separator
        printer.writeObjectEntrySeparator(gen);

        // End object with 1 entry
        printer.writeEndObject(gen, 1);

        // Verify basic sequence
        verify(gen).writeRaw('{');
        verify(gen).writeRaw('}');
    }

    @Test
    public void testFullArrayCycle() throws Exception {
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        JsonGenerator gen = mock(JsonGenerator.class);

        // Start array
        printer.writeStartArray(gen);

        // Before values
        printer.beforeArrayValues(gen);

        // Value separator
        printer.writeArrayValueSeparator(gen);

        // End array with 1 value
        printer.writeEndArray(gen, 1);

        // Verify basic sequence
        verify(gen).writeRaw('[');
        verify(gen).writeRaw(']');
    }

    // Helper methods to access private fields via reflection or use defaults
    private String _getObjectEmptySeparator(DefaultPrettyPrinter printer) {
        // Use default from Separators
        return Separators.createDefaultInstance().getObjectEmptySeparator();
    }

    private String _getArrayEmptySeparator(DefaultPrettyPrinter printer) {
        return Separators.createDefaultInstance().getArrayEmptySeparator();
    }

    private String _getObjectNameValueSeparator(DefaultPrettyPrinter printer) {
        Separators sep = Separators.createDefaultInstance();
        return sep.getObjectNameValueSpacing().apply(sep.getObjectNameValueSeparator());
    }

    private String _getObjectEntrySeparator(DefaultPrettyPrinter printer) {
        Separators sep = Separators.createDefaultInstance();
        return sep.getObjectEntrySpacing().apply(sep.getObjectEntrySeparator());
    }

    private String _getArrayElementSeparator(DefaultPrettyPrinter printer) {
        Separators sep = Separators.createDefaultInstance();
        return sep.getArrayElementSpacing().apply(sep.getArrayElementSeparator());
    }
}

