package tools.jackson.core.util;

import static org.junit.Assert.*;

import org.junit.Test;

public class InternCacheTest {

    @Test
    public void testSingletonInstanceExists() {
        assertNotNull(InternCache.instance);
    }

    @Test
    public void testInternReturnsSameString() {
        String input = "testString";
        String result = InternCache.instance.intern(input);
        assertSame(input, result);
    }

    @Test
    public void testInternCachesRepeatedCalls() {
        String input = "cachedString";

        // First call should intern and cache
        String firstResult = InternCache.instance.intern(input);

        // Second call should return cached value
        String secondResult = InternCache.instance.intern(input);

        assertSame("Second call should return same object as first", firstResult, secondResult);
    }

    @Test
    public void testInternDifferentStrings() {
        String str1 = "stringOne";
        String str2 = "stringTwo";

        String result1 = InternCache.instance.intern(str1);
        String result2 = InternCache.instance.intern(str2);

        assertNotSame(result1, result2);
        assertEquals("stringOne", result1);
        assertEquals("stringTwo", result2);
    }

    @Test
    public void testInternEmptyString() {
        String empty = "";
        String result = InternCache.instance.intern(empty);

        assertEquals("", result);
        assertSame(empty, result);
    }

    @Test(expected = NullPointerException.class)
    public void testInternNullThrowsNullPointerException() {
        InternCache.instance.intern(null);
    }

    @Test
    public void testInternWithCustomCache() {
        InternCache customCache = new InternCache(10, 0.75f, 2);

        String result = customCache.intern("customTest");

        assertEquals("customTest", result);
    }

    @Test
    public void testCacheExtendsConcurrentHashMap() {
        assertTrue(InternCache.instance instanceof java.util.concurrent.ConcurrentHashMap);
    }

    @Test
    public void testDefaultMaxEntriesConstant() {
        // Verify DEFAULT_MAX_ENTRIES is used
        assertEquals(280, InternCache.class.getDeclaredField("DEFAULT_MAX_ENTRIES").getInt(null));
    }
}

