package tools.jackson.core.util;

import org.junit.Test;

import static org.junit.Assert.*;

public class JacksonFeatureSetTest {

    private enum TestFeature implements JacksonFeature {
        FEATURE_A(0, true),
        FEATURE_B(1, false),
        FEATURE_C(2, true),
        FEATURE_D(3, false);

        private final int _mask;
        private final boolean _defaultState;

        TestFeature(int index, boolean defaultState) {
            _mask = 1 << index;
            _defaultState = defaultState;
        }

        @Override
        public boolean enabledByDefault() {
            return _defaultState;
        }

        @Override
        public int getMask() {
            return _mask;
        }

        @Override
        public boolean enabledIn(int flags) {
            return (flags & _mask) != 0;
        }
    }

    @Test
    public void testFromDefaultsWithDefaultEnabledFeatures() {
        TestFeature[] features = TestFeature.values();
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromDefaults(features);

        assertTrue(set.isEnabled(TestFeature.FEATURE_A));
        assertTrue(set.isEnabled(TestFeature.FEATURE_C));
        assertFalse(set.isEnabled(TestFeature.FEATURE_B));
        assertFalse(set.isEnabled(TestFeature.FEATURE_D));
    }

    @Test
    public void testFromDefaultsThrowsWhenTooManyFeatures() {
        TestFeature[] manyFeatures = new TestFeature[32];
        for (int i = 0; i < 32; i++) {
            manyFeatures[i] = TestFeature.values()[i % 4];
        }

        try {
            JacksonFeatureSet.fromDefaults(manyFeatures);
            fail("Expected IllegalArgumentException for more than 31 features");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("too many entries"));
            assertTrue(e.getMessage().contains("31"));
        }
    }

    @Test
    public void testFromBitmask() {
        int bitmask = TestFeature.FEATURE_A.getMask() | TestFeature.FEATURE_B.getMask();
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(bitmask);

        assertTrue(set.isEnabled(TestFeature.FEATURE_A));
        assertTrue(set.isEnabled(TestFeature.FEATURE_B));
        assertFalse(set.isEnabled(TestFeature.FEATURE_C));
    }

    @Test
    public void testWithEnablesFeature() {
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(0);
        JacksonFeatureSet<TestFeature> newSet = set.with(TestFeature.FEATURE_A);

        assertNotSame(set, newSet);
        assertTrue(newSet.isEnabled(TestFeature.FEATURE_A));
    }

    @Test
    public void testWithReturnsSameInstanceWhenAlreadyEnabled() {
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(TestFeature.FEATURE_A.getMask());
        JacksonFeatureSet<TestFeature> newSet = set.with(TestFeature.FEATURE_A);

        assertSame(set, newSet);
    }

    @Test
    public void testWithoutDisablesFeature() {
        int bitmask = TestFeature.FEATURE_A.getMask() | TestFeature.FEATURE_B.getMask();
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(bitmask);
        JacksonFeatureSet<TestFeature> newSet = set.without(TestFeature.FEATURE_A);

        assertNotSame(set, newSet);
        assertFalse(newSet.isEnabled(TestFeature.FEATURE_A));
        assertTrue(newSet.isEnabled(TestFeature.FEATURE_B));
    }

    @Test
    public void testWithoutReturnsSameInstanceWhenAlreadyDisabled() {
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(0);
        JacksonFeatureSet<TestFeature> newSet = set.without(TestFeature.FEATURE_A);

        assertSame(set, newSet);
    }

    @Test
    public void testIsEnabledReturnsCorrectValue() {
        int bitmask = TestFeature.FEATURE_A.getMask() | TestFeature.FEATURE_C.getMask();
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(bitmask);

        assertTrue(set.isEnabled(TestFeature.FEATURE_A));
        assertFalse(set.isEnabled(TestFeature.FEATURE_B));
        assertTrue(set.isEnabled(TestFeature.FEATURE_C));
        assertFalse(set.isEnabled(TestFeature.FEATURE_D));
    }

    @Test
    public void testAsBitmask() {
        int bitmask = TestFeature.FEATURE_A.getMask() | TestFeature.FEATURE_B.getMask();
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(bitmask);

        assertEquals(bitmask, set.asBitmask());
    }

    @Test
    public void testEmptySet() {
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(0);

        assertFalse(set.isEnabled(TestFeature.FEATURE_A));
        assertFalse(set.isEnabled(TestFeature.FEATURE_B));
        assertEquals(0, set.asBitmask());
    }

    @Test
    public void testFullSet() {
        int allBits = 0;
        for (TestFeature f : TestFeature.values()) {
            allBits |= f.getMask();
        }
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(allBits);

        for (TestFeature f : TestFeature.values()) {
            assertTrue(f.name() + " should be enabled", set.isEnabled(f));
        }
    }

    @Test
    public void testChainedMutations() {
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(0);

        JacksonFeatureSet<TestFeature> withA = set.with(TestFeature.FEATURE_A);
        JacksonFeatureSet<TestFeature> withAandB = withA.with(TestFeature.FEATURE_B);
        JacksonFeatureSet<TestFeature> withoutA = withAandB.without(TestFeature.FEATURE_A);

        assertFalse(set.isEnabled(TestFeature.FEATURE_A));
        assertFalse(set.isEnabled(TestFeature.FEATURE_B));

        assertTrue(withA.isEnabled(TestFeature.FEATURE_A));
        assertFalse(withA.isEnabled(TestFeature.FEATURE_B));

        assertTrue(withAandB.isEnabled(TestFeature.FEATURE_A));
        assertTrue(withAandB.isEnabled(TestFeature.FEATURE_B));

        assertFalse(withoutA.isEnabled(TestFeature.FEATURE_A));
        assertTrue(withoutA.isEnabled(TestFeature.FEATURE_B));
    }

    @Test
    public void testFromDefaultsWithAllDisabled() {
        TestFeature[] allDisabled = new TestFeature[] {
            new TestFeatureWithDefaults(false, false, false)
        };
    }

    private enum TestFeatureWithDefaults implements JacksonFeature {
        F1(0, false),
        F2(1, false),
        F3(2, false);

        private final int _mask;
        private final boolean _defaultState;

        TestFeatureWithDefaults(int index, boolean defaultState) {
            _mask = 1 << index;
            _defaultState = defaultState;
        }

        @Override
        public boolean enabledByDefault() {
            return _defaultState;
        }

        @Override
        public int getMask() {
            return _mask;
        }

        @Override
        public boolean enabledIn(int flags) {
            return (flags & _mask) != 0;
        }
    }

    @Test
    public void testFromDefaultsWithAllFeaturesDisabled() {
        TestFeatureWithDefaults[] features = TestFeatureWithDefaults.values();
        JacksonFeatureSet<TestFeatureWithDefaults> set = JacksonFeatureSet.fromDefaults(features);

        assertFalse(set.isEnabled(TestFeatureWithDefaults.F1));
        assertFalse(set.isEnabled(TestFeatureWithDefaults.F2));
        assertFalse(set.isEnabled(TestFeatureWithDefaults.F3));
    }

    @Test
    public void testMaxFeaturesEdgeCase() {
        int maxBitmask = 0;
        for (int i = 0; i < 31; i++) {
            maxBitmask |= (1 << i);
        }
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(maxBitmask);

        assertEquals(maxBitmask, set.asBitmask());
    }
}

