        TestFeatureWithDefaults[] features = TestFeatureWithDefaults.values();
        JacksonFeatureSet<TestFeatureWithDefaults> set = JacksonFeatureSet.fromDefaults(features);

        assertFalse(set.isEnabled(TestFeatureWithDefaults.F1));
        assertFalse(set.isEnabled(TestFeatureWithDefaults.F2));
        assertFalse(set.isEnabled(TestFeatureWithDefaults.F3));
    }

    @Test
    public void testMaxFeaturesEdgeCase() {
        int maxBitmask = 0;
        for (int i = 0; i < 31; i++) {
            maxBitmask |= (1 << i);
        }
        JacksonFeatureSet<TestFeature> set = JacksonFeatureSet.fromBitmask(maxBitmask);

        assertEquals(maxBitmask, set.asBitmask());
    }
}

