public class JsonGeneratorDelegateTest {

    private JsonGenerator mockDelegate;

    @Before
    public void setUp() {
        mockDelegate = mock(JsonGenerator.class);

        when(mockDelegate.currentValue()).thenReturn(null);
        when(mockDelegate.getSchema()).thenReturn(null);
        when(mockDelegate.version()).thenReturn(new Version(1, 2, 3, "", null, null));
        when(mockDelegate.streamWriteOutputTarget()).thenReturn(null);
        when(mockDelegate.streamWriteOutputBuffered()).thenReturn(0);
        when(mockDelegate.canWriteTypeId()).thenReturn(false);
        when(mockDelegate.canWriteObjectId()).thenReturn(false);
        when(mockDelegate.canOmitProperties()).thenReturn(true);
        when(mockDelegate.canWriteComments()).thenReturn(false);
        when(mockDelegate.has(any(StreamWriteCapability.class))).thenReturn(false);
        when(mockDelegate.streamWriteCapabilities()).thenReturn(mock(JacksonFeatureSet.class));
        when(mockDelegate.isEnabled(any(StreamWriteFeature.class))).thenReturn(false);
        when(mockDelegate.streamWriteFeatures()).thenReturn(0);
        when(mockDelegate.getHighestNonEscapedChar()).thenReturn(0);
        when(mockDelegate.getCharacterEscapes()).thenReturn(null);
        when(mockDelegate.getPrettyPrinter()).thenReturn(null);
        when(mockDelegate.streamWriteContext()).thenReturn(mock(TokenStreamContext.class));
        when(mockDelegate.objectWriteContext()).thenReturn(ObjectWriteContext.empty());
        when(mockDelegate.isClosed()).thenReturn(false);
    }

