package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

import tools.jackson.core.SerializableString;
import tools.jackson.core.io.CharacterEscapes;
import tools.jackson.core.io.SerializedString;

public class JsonpCharacterEscapesTest {

    @Test
    public void testSingletonReturnsNonNull() {
        JsonpCharacterEscapes instance = JsonpCharacterEscapes.instance();
        assertNotNull("instance() should not return null", instance);
    }

    @Test
    public void testSingletonReturnsSameInstance() {
        JsonpCharacterEscapes instance1 = JsonpCharacterEscapes.instance();
        JsonpCharacterEscapes instance2 = JsonpCharacterEscapes.instance();
        assertSame("instance() should return the same instance", instance1, instance2);
    }

    @Test
    public void testGetEscapeSequenceFor2028() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        SerializableString seq = esc.getEscapeSequence(0x2028);
        assertNotNull("Escape sequence for U+2028 should not be null", seq);
        assertEquals("Escape sequence value should be \\\\u2028", "\\u2028", seq.getValue());
    }

    @Test
    public void testGetEscapeSequenceFor2029() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        SerializableString seq = esc.getEscapeSequence(0x2029);
        assertNotNull("Escape sequence for U+2029 should not be null", seq);
        assertEquals("Escape sequence value should be \\\\u2029", "\\u2029", seq.getValue());
    }

    @Test
    public void testGetEscapeSequenceForOtherCharsReturnsNull() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        // test various characters: 0, 1, 0x2027, 0x202A, 0xFFFF, -1
        assertNull("Escape sequence for 0 should be null", esc.getEscapeSequence(0));
        assertNull("Escape sequence for 0x2027 should be null", esc.getEscapeSequence(0x2027));
        assertNull("Escape sequence for 0x202A should be null", esc.getEscapeSequence(0x202A));
        assertNull("Escape sequence for 0xFFFF should be null", esc.getEscapeSequence(0xFFFF));
        assertNull("Escape sequence for -1 should be null", esc.getEscapeSequence(-1));
    }

    @Test
    public void testGetEscapeCodesForAscii() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        int[] codes = esc.getEscapeCodesForAscii();
        assertNotNull("getEscapeCodesForAscii should not return null", codes);
        assertEquals("Escape codes length should be 128", 128, codes.length);
        // Verify that the array equals the standard escapes
        int[] standard = CharacterEscapes.standardAsciiEscapesForJSON();
        assertArrayEquals("Escape codes should match standard ASCII escapes", standard, codes);
    }

    @Test
    public void testEscapeSequenceValueIsSerializedString() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        SerializableString seq = esc.getEscapeSequence(0x2028);
        assertTrue("Escape sequence for 0x2028 should be instance of SerializedString", seq instanceof SerializedString);
        SerializableString seq2 = esc.getEscapeSequence(0x2029);
        assertTrue("Escape sequence for 0x2029 should be instance of SerializedString", seq2 instanceof SerializedString);
    }

    // Additional test: verify that getEscapeCodesForAscii returns the same reference as static field
    @Test
    public void testGetEscapeCodesForAsciiReturnsStaticArray() {
        JsonpCharacterEscapes esc = JsonpCharacterEscapes.instance();
        int[] codes = esc.getEscapeCodesForAscii();
        // static field asciiEscapes is not accessible directly, but we can verify it's the same array as returned by standardAsciiEscapesForJSON()?
        // The static field is assigned to result of standardAsciiEscapesForJSON() which returns a copy.
