package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonRecyclerPoolsTest {

    @Test
    public void testDefaultPool() {
        RecyclerPool<BufferRecycler> pool = JsonRecyclerPools.defaultPool();
        assertNotNull(pool);
        // Default is ConcurrentDequePool
        assertTrue(pool instanceof JsonRecyclerPools.ConcurrentDequePool);
    }

    @Test
    public void testNonRecyclingPoolSingleton() {
        RecyclerPool<BufferRecycler> p1 = JsonRecyclerPools.nonRecyclingPool();
        RecyclerPool<BufferRecycler> p2 = JsonRecyclerPools.nonRecyclingPool();
        assertSame("nonRecyclingPool should return global singleton", p1, p2);
    }

    @Test
    public void testThreadLocalPoolSingleton() {
        RecyclerPool<BufferRecycler> p1 = JsonRecyclerPools.threadLocalPool();
        RecyclerPool<BufferRecycler> p2 = JsonRecyclerPools.threadLocalPool();
        assertSame("threadLocalPool should return global singleton", p1, p2);
    }

    @Test
    public void testSharedConcurrentDequePoolSingleton() {
        RecyclerPool<BufferRecycler> p1 = JsonRecyclerPools.sharedConcurrentDequePool();
        RecyclerPool<BufferRecycler> p2 = JsonRecyclerPools.sharedConcurrentDequePool();
        assertSame("sharedConcurrentDequePool should return global singleton", p1, p2);
    }

    @Test
    public void testNewConcurrentDequePoolReturnsNew() {
        RecyclerPool<BufferRecycler> p1 = JsonRecyclerPools.newConcurrentDequePool();
        RecyclerPool<BufferRecycler> p2 = JsonRecyclerPools.newConcurrentDequePool();
        assertNotSame("newConcurrentDequePool should return new instances", p1, p2);
    }

    @Test
    public void testSharedBoundedPoolSingleton() {
        RecyclerPool<BufferRecycler> p1 = JsonRecyclerPools.sharedBoundedPool();
        RecyclerPool<BufferRecycler> p2 = JsonRecyclerPools.sharedBoundedPool();
        assertSame("sharedBoundedPool should return global singleton", p1, p2);
    }

    @Test
    public void testNewBoundedPoolCapacity() {
        int capacity = 42;
        RecyclerPool<BufferRecycler> pool = JsonRecyclerPools.newBoundedPool(capacity);
        assertTrue(pool instanceof JsonRecyclerPools.BoundedPool);
        JsonRecyclerPools.BoundedPool boundedPool = (JsonRecyclerPools.BoundedPool) pool;
        // Access package-private method or just rely on behavior? 
        // The base class has capacity() method, but it's not on the interface.
        // Let's check behavior: acquire/release cycles.
    }

    // Wait, I need to check if `capacity()` is accessible. 
    // `BoundedPool` extends `BoundedPoolBase` which has `capacity()`.
    // `BoundedPool` doesn't override it. So yes.

    @Test(expected = IllegalArgumentException.class)
    public void testNewBoundedPoolZeroSize() {
        JsonRecyclerPools.newBoundedPool(0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testNewBoundedPoolNegativeSize() {
        JsonRecyclerPools.newBoundedPool(-5);
    }

    @Test
    public void testNonRecyclingBehavior() {
        RecyclerPool<BufferRecycler> pool = JsonRecyclerPools.nonRecyclingPool();
        BufferRecycler b1 = pool.acquirePooled();
        BufferRecycler b2 = pool.acquirePooled();
        assertNotSame("NonRecyclingPool should create new instances", b1, b2);
    }

    @Test
    public void testConcurrentDequePoolRecycling() {
        RecyclerPool<BufferRecycler> pool = JsonRecyclerPools.newConcurrentDequePool();

        BufferRecycler b1 = pool.acquirePooled();
        pool.releasePooled(b1);

        BufferRecycler b2 = pool.acquirePooled();

        assertSame("ConcurrentDequePool should recycle", b1, b2);
    }

    @Test
    public void testBoundedPoolRecycling() {
        int capacity = 5;
        RecyclerPool<BufferRecycler> pool = JsonRecyclerPools.newBoundedPool(capacity);

        // BoundedPool is bounded by ArrayBlockingQueue
        BufferRecycler b1 = pool.acquirePooled();
        pool.releasePooled(b1);

        BufferRecycler b2 = pool.acquirePooled();

        assertSame("BoundedPool should recycle", b1, b2);
    }

    @Test
    public void testBoundedPoolCapacity() {
        int capacity = 10;
        JsonRecyclerPools.BoundedPool pool = JsonRecyclerPools.newBoundedPool(capacity);
        // The cast is safe because we just created it
        assertEquals(capacity, pool.capacity());
    }
}

