package tools.jackson.core.util;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import tools.jackson.core.JsonGenerator;
import tools.jackson.core.JacksonException;
import tools.jackson.core.util.Separators;
import tools.jackson.core.util.Separators.Spacing;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Tests for {@link MinimalPrettyPrinter}.
 */
@RunWith(MockitoJUnitRunner.class)
public class MinimalPrettyPrinterTest {

    @Mock
    private JsonGenerator jsonGenerator;

    @Test
    public void testDefaultConstructorSetsDefaultSeparators() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        // Verify default behavior by checking outputs
        printer.writeStartObject(jsonGenerator);
        verify(jsonGenerator).writeRaw('{');
    }

    @Test
    public void testCustomRootSeparatorConstructor() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter("|");
        printer.writeRootValueSeparator(jsonGenerator);
        verify(jsonGenerator).writeRaw("|");
    }

    @Test
    public void testSetRootValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.setRootValueSeparator("\n");
        printer.writeRootValueSeparator(jsonGenerator);
        verify(jsonGenerator).writeRaw("\n");
    }

    @Test
    public void testSetSeparators() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        Separators custom = new Separators('!', '@', '#');
        MinimalPrettyPrinter result = printer.setSeparators(custom);

        assertSame(printer, result);

        // Verify custom separators are used
        printer.writeObjectNameValueSeparator(jsonGenerator);
        verify(jsonGenerator).writeRaw('!');

        printer.writeObjectEntrySeparator(jsonGenerator);
        verify(jsonGenerator).writeRaw('@');

        printer.writeArrayValueSeparator(jsonGenerator);
        verify(jsonGenerator).writeRaw('#');
    }

    @Test
    public void testWriteRootValueSeparatorWithNullDoesNothing() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.setRootValueSeparator(null);
        printer.writeRootValueSeparator(jsonGenerator);
        verify(jsonGenerator, never()).writeRaw(anyString());
    }

    @Test
    public void testWriteStartObject() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeStartObject(jsonGenerator);
        verify(jsonGenerator).writeRaw('{');
    }

    @Test
    public void testWriteEndObject() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeEndObject(jsonGenerator, 1);
        verify(jsonGenerator).writeRaw('}');
    }

    @Test
    public void testWriteStartArray() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeStartArray(jsonGenerator);
        verify(jsonGenerator).writeRaw('[');
    }

    @Test
    public void testWriteEndArray() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeEndArray(jsonGenerator, 1);
        verify(jsonGenerator).writeRaw(']');
    }

    @Test
    public void testDefaultObjectNameValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeObjectNameValueSeparator(jsonGenerator);
        // Default separator is ':'
        verify(jsonGenerator).writeRaw(':');
    }

    @Test
    public void testDefaultObjectEntrySeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeObjectEntrySeparator(jsonGenerator);
        // Default separator is ','
        verify(jsonGenerator).writeRaw(',');
    }

    @Test
    public void testDefaultArrayValueSeparator() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.writeArrayValueSeparator(jsonGenerator);
        // Default separator is ','
        verify(jsonGenerator).writeRaw(',');
    }

    @Test
    public void testBeforeObjectEntriesDoesNothing() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.beforeObjectEntries(jsonGenerator);
        // Verify no interaction (no writeRaw calls)
        verifyNoInteractions(jsonGenerator);
    }

    @Test
    public void testBeforeArrayValuesDoesNothing() throws JacksonException {
        MinimalPrettyPrinter printer = new MinimalPrettyPrinter();
        printer.beforeArrayValues(jsonGenerator);
        verifyNoInteractions(jsonGenerator);
    }
}

