package tools.jackson.core.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import org.junit.Before;
import org.junit.Test;

import tools.jackson.core.StreamReadConstraints;
import tools.jackson.core.exc.StreamConstraintsException;

public class ReadConstrainedTextBufferTest {

    private static final int MAX_STRING_LENGTH = 100;

    private StreamReadConstraints constraints;
    private BufferRecycler bufferRecycler;
    private ReadConstrainedTextBuffer buffer;

    @Before
    public void setUp() {
        constraints = StreamReadConstraints.unlimited();
        bufferRecycler = new BufferRecycler();
    }

    @Test
    public void testValidateStringLengthWithinLimit() throws Exception {
        constraints = new StreamReadConstraints.Builder().maxStringLength(MAX_STRING_LENGTH).build();
        buffer = new ReadConstrainedTextBuffer(constraints, bufferRecycler);

        // Use reflection to call protected method
        java.lang.reflect.Method method = ReadConstrainedTextBuffer.class.getSuperclass()
                .getDeclaredMethod("validateStringLength", int.class);
        method.setAccessible(true);
        method.invoke(buffer, MAX_STRING_LENGTH);
        method.invoke(buffer, 50);
        method.invoke(buffer, 0);
    }

    @Test
    public void testValidateStringLengthExceedsLimit() throws Exception {
        constraints = new StreamReadConstraints.Builder().maxStringLength(MAX_STRING_LENGTH).build();
        buffer = new ReadConstrainedTextBuffer(constraints, bufferRecycler);

        java.lang.reflect.Method method = ReadConstrainedTextBuffer.class.getSuperclass()
                .getDeclaredMethod("validateStringLength", int.class);
        method.setAccessible(true);

        try {
            method.invoke(buffer, MAX_STRING_LENGTH + 1);
            fail("Expected StreamConstraintsException");
        } catch (java.lang.reflect.InvocationTargetException e) {
            assertEquals(StreamConstraintsException.class, e.getCause().getClass());
        }
    }

    @Test
    public void testValidateStringLengthAtBoundary() throws Exception {
        constraints = new StreamReadConstraints.Builder().maxStringLength(MAX_STRING_LENGTH).build();
        buffer = new ReadConstrainedTextBuffer(constraints, bufferRecycler);

        java.lang.reflect.Method method = ReadConstrainedTextBuffer.class.getSuperclass()
                .getDeclaredMethod("validateStringLength", int.class);
        method.setAccessible(true);

        // Should not throw at exactly the limit
        method.invoke(buffer, MAX_STRING_LENGTH);
    }

    @Test
    public void testValidateStringLengthWithUnlimitedConstraints() throws Exception {
        constraints = StreamReadConstraints.unlimited();
        buffer = new ReadConstrainedTextBuffer(constraints, bufferRecycler);

        java.lang.reflect.Method method = ReadConstrainedTextBuffer.class.getSuperclass()
                .getDeclaredMethod("validateStringLength", int.class);
        method.setAccessible(true);

        // Should not throw even with large values when unlimited
        method.invoke(buffer, Integer.MAX_VALUE);
    }

    @Test
    public void testValidateStringLengthZeroLength() throws Exception {
        constraints = new StreamReadConstraints.Builder().maxStringLength(MAX_STRING_LENGTH).build();
        buffer = new ReadConstrainedTextBuffer(constraints, bufferRecycler);

        java.lang.reflect.Method method = ReadConstrainedTextBuffer.class.getSuperclass()
                .getDeclaredMethod("validateStringLength", int.class);
        method.setAccessible(true);

        // Zero length should be valid
        method.invoke(buffer, 0);
    }

    @Test
    public void testConstructorWithNullConstraints() {
        buffer = new ReadConstrainedTextBuffer(null, bufferRecycler);
        // Verify buffer was created (null constraints will cause NPE when validating)
        java.lang.reflect.Method method;
        try {
            method = ReadConstrainedTextBuffer.class.getSuperclass()
                    .getDeclaredMethod("validateStringLength", int.class);
            method.setAccessible(true);
            method.invoke(buffer, 1);
            fail("Expected NullPointerException");
        } catch (java.lang.reflect.InvocationTargetException e) {
            assertEquals(NullPointerException.class, e.getCause().getClass());
        }
    }
}

