        Separators result = original.withArrayElementSeparator(';');

        assertNotSame(original, result);
        assertEquals(';', result.getArrayElementSeparator());
    }

    @Test
    public void testWithArrayElementSpacingSameValue() {
        Separators original = new Separators();
        Separators result = original.withArrayElementSpacing(Separators.Spacing.NONE);

        assertSame(original, result);
    }

    @Test
    public void testWithArrayElementSpacingDifferentValue() {
        Separators original = new Separators();
        Separators result = original.withArrayElementSpacing(Separators.Spacing.BOTH);

        assertNotSame(original, result);
        assertEquals(Separators.Spacing.BOTH, result.getArrayElementSpacing());
    }

    @Test
    public void testWithArrayEmptySeparatorSameValue() {
        Separators original = new Separators();
        Separators result = original.withArrayEmptySeparator(" ");

        assertSame(original, result);
    }

    @Test
    public void testWithArrayEmptySeparatorDifferentValue() {
        Separators original = new Separators();
        Separators result = original.withArrayEmptySeparator("[]");

        assertNotSame(original, result);
        assertEquals("[]", result.getArrayEmptySeparator());
    }

    @Test
    public void testSpacingEnumNone() {
        assertEquals("", Separators.Spacing.NONE.spacesBefore());
        assertEquals("", Separators.Spacing.NONE.spacesAfter());
        assertEquals(",", Separators.Spacing.NONE.apply(','));
    }

    @Test
    public void testSpacingEnumBefore() {
        assertEquals(" ", Separators.Spacing.BEFORE.spacesBefore());
        assertEquals("", Separators.Spacing.BEFORE.spacesAfter());
        assertEquals(" ,", Separators.Spacing.BEFORE.apply(','));
    }

    @Test
    public void testSpacingEnumAfter() {
        assertEquals("", Separators.Spacing.AFTER.spacesBefore());
        assertEquals(" ", Separators.Spacing.AFTER.spacesAfter());
        assertEquals(", ", Separators.Spacing.AFTER.apply(','));
    }

    @Test
    public void testSpacingEnumBoth() {
        assertEquals(" ", Separators.Spacing.BOTH.spacesBefore());
        assertEquals(" ", Separators.Spacing.BOTH.spacesAfter());
        assertEquals(" , ", Separators.Spacing.BOTH.apply(','));
    }

    @Test
    public void testChainedWithMethods() {
        Separators original = new Separators();
        Separators result = original
                .withRootSeparator("-")
                .withObjectNameValueSeparator('=')
                .withObjectNameValueSpacing(Separators.Spacing.AFTER)
                .withObjectEntrySeparator(';')
                .withObjectEntrySpacing(Separators.Spacing.BEFORE)
                .withObjectEmptySeparator("{}")
                .withArrayElementSeparator('|')
                .withArrayElementSpacing(Separators.Spacing.BOTH)
                .withArrayEmptySeparator("[]");

        assertNotSame(original, result);
        assertEquals("-", result.getRootSeparator());
        assertEquals('=', result.getObjectNameValueSeparator());
        assertEquals(Separators.Spacing.AFTER, result.getObjectNameValueSpacing());
        assertEquals(';', result.getObjectEntrySeparator());
        assertEquals(Separators.Spacing.BEFORE, result.getObjectEntrySpacing());
        assertEquals("{}", result.getObjectEmptySeparator());
        assertEquals('|', result.getArrayElementSeparator());
        assertEquals(Separators.Spacing.BOTH, result.getArrayElementSpacing());
        assertEquals("[]", result.getArrayEmptySeparator());
    }

    @Test
    public void testDefaultSpacingValues() {
        Separators separators = new Separators();

        assertEquals(Separators.Spacing.BOTH, separators.getObjectNameValueSpacing());
        assertEquals(Separators.Spacing.NONE, separators.getObjectEntrySpacing());
        assertEquals(Separators.Spacing.NONE, separators.getArrayElementSpacing());
    }

    @Test
    public void testDefaultSeparatorValues() {
        Separators separators = new Separators();

        assertEquals(" ", separators.getRootSeparator());
        assertEquals(" ", separators.getObjectEmptySeparator());
        assertEquals(" ", separators.getArrayEmptySeparator());
    }
}

