package tools.jackson.core.util;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.run.MockitoJUnitRunner;

import tools.jackson.core.JsonParser;
import tools.jackson.core.TokenStreamContext;
import tools.jackson.core.exc.StreamReadException;
import tools.jackson.core.io.ContentReference;
import tools.jackson.core.json.DupDetector;

@RunWith(MockitoJUnitRunner.class)
public class SimpleStreamReadContextTest {

    @Test
    public void testCreateRootContext() {
        DupDetector dups = mock(DupDetector.class);
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, dups);

        assertNotNull(context);
        assertNull(context.getParent());
        assertNull(context.currentName());
        assertFalse(context.hasCurrentName());
        assertNull(context.currentValue());
        assertEquals(0, context.getNestingDepth());
        assertEquals(0, context.getEntryCount());
    }

    @Test
    public void testCreateRootContextWithDefaultLineCol() {
        DupDetector dups = mock(DupDetector.class);
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(dups);

        assertNotNull(context);
        assertNull(context.getParent());
    }

    @Test
    public void testCreateChildArrayContext() {
        DupDetector dups = mock(DupDetector.class);
        DupDetector childDups = mock(DupDetector.class);
        when(dups.child()).thenReturn(childDups);

        SimpleStreamReadContext parent = SimpleStreamReadContext.createRootContext(1, 0, dups);
        SimpleStreamReadContext child = parent.createChildArrayContext(2, 5);

        assertNotNull(child);
        assertEquals(TokenStreamContext.TYPE_ARRAY, child.typeDesc());
        assertEquals(parent, child.getParent());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testCreateChildObjectContext() {
        DupDetector dups = mock(DupDetector.class);
        DupDetector childDups = mock(DupDetector.class);
        when(dups.child()).thenReturn(childDups);

        SimpleStreamReadContext parent = SimpleStreamReadContext.createRootContext(1, 0, dups);
        SimpleStreamReadContext child = parent.createChildObjectContext(3, 10);

        assertNotNull(child);
        assertEquals(TokenStreamContext.TYPE_OBJECT, child.typeDesc());
        assertEquals(parent, child.getParent());
        assertEquals(1, child.getNestingDepth());
    }

    @Test
    public void testChildContextRecyclingForArray() {
        DupDetector dups = mock(DupDetector.class);

        SimpleStreamReadContext parent = SimpleStreamReadContext.createRootContext(1, 0, dups);

        SimpleStreamReadContext firstChild = parent.createChildArrayContext(1, 0);
        SimpleStreamReadContext secondChild = parent.createChildArrayContext(2, 0);

        assertSame("Should recycle the same child context instance", firstChild, secondChild);
    }

    @Test
    public void testChildContextRecyclingForObject() {
        DupDetector dups = mock(DupDetector.class);

        SimpleStreamReadContext parent = SimpleStreamReadContext.createRootContext(1, 0, dups);

        SimpleStreamReadContext firstChild = parent.createChildObjectContext(1, 0);
        SimpleStreamReadContext secondChild = parent.createChildObjectContext(2, 0);

        assertSame("Should recycle the same child context instance", firstChild, secondChild);
    }

    @Test
    public void testCurrentValue() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        assertNull(context.currentValue());

        Object value = new Object();
        context.assignCurrentValue(value);
        assertSame(value, context.currentValue());
    }

    @Test
    public void testCurrentName() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        assertNull(context.currentName());
        assertFalse(context.hasCurrentName());
    }

    @Test
    public void testSetCurrentName() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        context.setCurrentName("testName");

        assertEquals("testName", context.currentName());
        assertTrue(context.hasCurrentName());
    }

    @Test
    public void testSetCurrentNameWithDuplicateDetectionThrowsException() throws StreamReadException {
        DupDetector dups = mock(DupDetector.class);
        when(dups.isDup("name")).thenReturn(true);

        JsonParser parser = mock(JsonParser.class);
        when(dups.getSource()).thenReturn(parser);

        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, dups);

        try {
            context.setCurrentName("name");
            fail("Expected StreamReadException for duplicate name");
        } catch (StreamReadException e) {
            assertTrue(e.getMessage().contains("Duplicate"));
            assertTrue(e.getMessage().contains("name"));
        }
    }

    @Test
    public void testSetCurrentNameNoDuplicate() throws StreamReadException {
        DupDetector dups = mock(DupDetector.class);
        when(dups.isDup("name")).thenReturn(false);

        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, dups);
        context.setCurrentName("name");

        assertEquals("name", context.currentName());
    }

    @Test
    public void testSetCurrentNameWithNullDupDetector() throws StreamReadException {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        context.setCurrentName("name");

        assertEquals("name", context.currentName());
    }

    @Test
    public void testValueRead() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        assertEquals(0, context.valueRead());
        assertEquals(1, context.valueRead());
        assertEquals(2, context.valueRead());
    }

    @Test
    public void testValueReadIndexInitialization() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        assertEquals(0, context.getCurrentIndex());
    }

    @Test
    public void testRollbackValueRead() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(1, 0, null);

        context.valueRead();
        context.valueRead();
        context.valueRead();
        assertEquals(2, context.getCurrentIndex());

        assertEquals(1, context.rollbackValueRead());
        assertEquals(0, context.rollbackValueRead());
        assertEquals(-1, context.rollbackValueRead());
        assertEquals(-1, context.rollbackValueRead());
    }

    @Test
    public void testClearAndGetParent() {
        DupDetector dups = mock(DupDetector.class);

        SimpleStreamReadContext root = SimpleStreamReadContext.createRootContext(1, 0, dups);
        SimpleStreamReadContext child = root.createChildObjectContext(1, 0);

        child.assignCurrentValue(new Object());

        SimpleStreamReadContext parent = child.clearAndGetParent();

        assertNull(child.currentValue());
        assertEquals(root, parent);
    }

