    public void testStartLocation() {
        SimpleStreamReadContext context = SimpleStreamReadContext.createRootContext(5, 10, null);

        ContentReference contentRef = ContentReference.unknown();
        tools.jackson.core.TokenStreamLocation location = context.startLocation(contentRef);

