    @Test
    public void testNestedContexts() {
        DupDetector dups = mock(DupDetector.class);
        DupDetector childDups = mock(DupDetector.class);
        when(dups.child()).thenReturn(childDups);

        SimpleStreamReadContext root = SimpleStreamReadContext.createRootContext(1, 0, dups);
        SimpleStreamReadContext arrayContext = root.createChildArrayContext(1, 0);
        SimpleStreamReadContext objectContext = arrayContext.createChildObjectContext(1, 0);

        assertEquals(root, objectContext.getParent());
        assertEquals(arrayContext, objectContext.getParent().getParent());
        assertEquals(2, objectContext.getNestingDepth());
    }

    @Test
    public void testInArray() {
        DupDetector dups = mock(DupDetector.class);
        DupDetector childDups = mock(DupDetector.class);
        when(dups.child()).thenReturn(childDups);

        SimpleStreamReadContext root = SimpleStreamReadContext.createRootContext(1, 0, dups);
        SimpleStreamReadContext arrayContext = root.createChildArrayContext(1, 0);

        assertTrue(arrayContext.inArray());
