import java.io.StringWriter;
import java.math.BigDecimal;
import java.util.Arrays;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class TextBufferTest {

    private BufferRecycler recycler;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
    }

    // --- Constructor tests ---

    @Test
    public void testDefaultConstructor() {
        TextBuffer buffer = new TextBuffer(recycler);
        assertEquals(0, buffer.size());
        assertEquals(0, buffer.getTextOffset());
        assertNotNull(buffer.bufferRecycler());
    }

    @Test
    public void testFromInitial() {
        char[] initial = "Hello".toCharArray();
        TextBuffer buffer = TextBuffer.fromInitial(initial);
        assertEquals(5, buffer.size());
        assertEquals("Hello", buffer.toString());
        // Verify it's using the provided segment
        assertSame(initial, buffer.getBufferWithoutReset());
    }

    // --- Size and Offset tests ---

    @Test
    public void testSizeAfterAppend() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test");
        assertEquals(4, buffer.size());
    }

    @Test
    public void testSizeAfterResetWithString() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("TestString");
        assertEquals(10, buffer.size());
    }

    @Test
    public void testGetTextOffsetWithSharedBuffer() {
        char[] data = "0123456789".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 2, 5);

        assertEquals(2, buffer.getTextOffset()); // Offset is 2
        assertEquals(5, buffer.size());
        assertEquals("23456", buffer.toString());
    }

    @Test
    public void testGetTextOffsetWithLocalBuffer() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test");

        assertEquals(0, buffer.getTextOffset());
    }

    @Test
    public void testHasTextAsCharactersWithStringResult() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("Test");

        // When result is String, hasTextAsCharacters should return false (because it's more efficient to return String)
        assertFalse(buffer.hasTextAsCharacters());
    }

    @Test
    public void testHasTextAsCharactersWithBuffer() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test");

        assertTrue(buffer.hasTextAsCharacters());
    }

    // --- Reset and Clear tests ---

    @Test
    public void testResetWithEmpty() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Some content");
        buffer.resetWithEmpty();

        assertEquals(0, buffer.size());
        assertNull(buffer.getTextBuffer());
    }

    @Test
    public void testResetWithChar() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWith('X');

        assertEquals(1, buffer.size());
        assertEquals("X", buffer.toString());
    }

    @Test
    public void testResetWithShared() {
        char[] data = "SharedData".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 0, 5);

        assertEquals(5, buffer.size());
        assertSame(data, buffer.getTextBuffer()); // Should return the shared reference
    }

    @Test
    public void testResetWithCopy() {
        char[] original = "Original".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithCopy(original, 0, 8);

        assertEquals(8, buffer.size());
        assertEquals("Original", buffer.toString());
        // Modifying original should not affect buffer
        original[0] = 'O';
        assertEquals("Original", buffer.toString());
    }

    @Test
    public void testResetWithString() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("TestString");

        assertEquals("TestString", buffer.contentsAsString());
    }

    @Test
    public void testResetWithCopyString() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithCopy("CopyString", 4, 6);

        assertEquals("String", buffer.toString());
    }

    // --- Append and Expand tests ---

    @Test
    public void testAppendChar() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append('A');
        buffer.append('B');

        assertEquals(2, buffer.size());
        assertEquals("AB", buffer.toString());
    }

    @Test
    public void testAppendCharArray() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append(new char[]{'A', 'B', 'C'}, 0, 3);

        assertEquals(3, buffer.size());
        assertEquals("ABC", buffer.toString());
    }

    @Test
    public void testAppendString() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Hello", 0, 5);

        assertEquals(5, buffer.size());
        assertEquals("Hello", buffer.toString());
    }

    @Test
    public void testAppendToSharedBuffer() {
        char[] data = "Shared".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 0, 6);

        // Appending should trigger unshare (copy)
        buffer.append("More");

        assertEquals(10, buffer.size());
        assertEquals("SharedMore", buffer.toString());
        // Ensure it doesn't use the original shared array anymore
        assertNotSame(data, buffer.getTextBuffer());
    }

    @Test
    public void testExpandCurrentSegment() {
        TextBuffer buffer = new TextBuffer(recycler);
        char[] seg = buffer.getCurrentSegment();
        int originalLen = seg.length;

        // Expand
        char[] expanded = buffer.expandCurrentSegment();

        assertTrue(expanded.length > originalLen);
    }

    @Test
    public void testExpandCurrentSegmentWithMinSize() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.getCurrentSegment(); // init

        char[] expanded = buffer.expandCurrentSegment(1000);

        assertTrue(expanded.length >= 1000);
    }

    // --- Segment Management tests ---

    @Test
    public void testFinishCurrentSegment() {
        TextBuffer buffer = new TextBuffer(recycler);
        // Fill first segment
        char[] first = buffer.getCurrentSegment();
        Arrays.fill(first, 'A');
        buffer.setCurrentLength(first.length);

        // Finish it
        char[] second = buffer.finishCurrentSegment();
        assertEquals(0, buffer.getCurrentSegmentSize());

        // Fill second
        Arrays.fill(second, 'B');
        buffer.setCurrentLength(second.length);

        // Verify aggregation
        assertEquals(first.length + second.length, buffer.size());
    }

    @Test
    public void testEmptyAndGetCurrentSegment() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("SomeText");

        char[] seg = buffer.emptyAndGetCurrentSegment();

        assertEquals(0, buffer.size());
        assertNotNull(seg);
    }

    @Test
    public void testSetCurrentAndReturn() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Initial");

        String result = buffer.setCurrentAndReturn(4); // Limit to 4 chars

        assertEquals("Init", result);
        assertEquals(4, buffer.size());
    }

    // --- Content Retrieval tests ---

    @Test
    public void testGetTextBuffer() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test");

        char[] buf = buffer.getTextBuffer();

        assertEquals("Test", new String(buf));
    }

    @Test
    public void testGetTextBufferEmpty() {
        TextBuffer buffer = new TextBuffer(recycler);
        char[] buf = buffer.getTextBuffer();

        assertEquals(0, buf.length);
    }

    @Test
    public void testContentsAsStringMultipleSegments() {
        TextBuffer buffer = new TextBuffer(recycler);
        // Force multiple segments
        String s1 = "Seg1";
        String s2 = "Seg2";
        // Create a buffer with MIN_SEGMENT_LEN roughly
        while (buffer.size() < TextBuffer.MIN_SEGMENT_LEN) {
            buffer.append(s1);
        }
        buffer.append(s2);

        String result = buffer.contentsAsString();
        assertTrue(result.startsWith("Seg1"));
        assertTrue(result.endsWith("Seg2"));
    }

    @Test
    public void testContentsAsArray() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("ArrayContent");

        char[] result = buffer.contentsAsArray();

        assertEquals("ArrayContent", new String(result));
    }

    @Test
    public void testContentsToWriter() throws IOException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Writer");

        StringWriter sw = new StringWriter();
        int count = buffer.contentsToWriter(sw);

        assertEquals(6, count);
        assertEquals("Writer", sw.toString());
    }

    // --- Number Parsing tests ---

    @Test
    public void testContentsAsInt() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("123");

        int result = buffer.contentsAsInt(false);

        assertEquals(123, result);
    }

    @Test
    public void testContentsAsIntNegative() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("123");

        int result = buffer.contentsAsInt(true); // Simulate negative

        assertEquals(-123, result);
    }

    @Test
    public void testContentsAsLong() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("12345678901");

        long result = buffer.contentsAsLong(false);

        assertEquals(12345678901L, result);
    }

    @Test
    public void testContentsAsDouble() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("1.5");

        double result = buffer.contentsAsDouble(false);

        assertEquals(1.5, result, 0.0);
    }

    @Test
    public void testContentsAsFloat() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("2.5");

        float result = buffer.contentsAsFloat(false);

        assertEquals(2.5f, result, 0.0);
    }

    @Test
    public void testContentsAsDecimal() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("123.456");

        BigDecimal result = buffer.contentsAsDecimal(false);

        assertEquals(new BigDecimal("123.456"), result);
    }

    // --- Release tests ---

    @Test
    public void testReleaseBuffers() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Data");

        buffer.releaseBuffers();

        // Current segment should be released and set to null
        assertNull(buffer.getBufferWithoutReset());
    }

    @Test
    public void testReleaseBuffersWithEmpty() {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.releaseBuffers(); // Should not fail

        assertEquals(0, buffer.size());
    }

    // --- Trim tests ---

    @Test
    public void testFinishAndReturnWithTrim() throws Exception {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Value   "); // 3 spaces

        String result = buffer.finishAndReturn(5, true); // Last 3 are spaces

        assertEquals("Value", result);
    }
}

