package tools.jackson.core.util;

import java.io.IOException;
import java.io.StringWriter;
import java.math.BigDecimal;
import java.util.Arrays;

import org.junit.Before;
import org.junit.Test;

import tools.jackson.core.JacksonException;

import static org.junit.Assert.*;

public class TextBufferTest {

    private BufferRecycler recycler;

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
    }

    // --- Constructor tests ---

    @Test
    public void testDefaultConstructor() {
        TextBuffer buffer = new TextBuffer(recycler);
        assertEquals(0, buffer.size());
        assertEquals(0, buffer.getTextOffset());
        assertNotNull(buffer.bufferRecycler());
    }

    @Test
    public void testFromInitial() {
        char[] initial = "Hello".toCharArray();
        TextBuffer buffer = TextBuffer.fromInitial(initial);
        assertEquals(5, buffer.size());
        assertEquals("Hello", buffer.toString());
        // Verify it's using the provided segment
        assertSame(initial, buffer.getBufferWithoutReset());
    }

    // --- Size and Offset tests ---

    @Test
    public void testSizeAfterAppend() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test", 0, 4);
        assertEquals(4, buffer.size());
    }

    @Test
    public void testSizeAfterResetWithString() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("TestString");
        assertEquals(10, buffer.size());
    }

    @Test
    public void testGetTextOffsetWithSharedBuffer() throws JacksonException {
        char[] data = "0123456789".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 2, 5);

        assertEquals(2, buffer.getTextOffset()); // Offset is 2
        assertEquals(5, buffer.size());
        assertEquals("23456", buffer.toString());
    }

    @Test
    public void testGetTextOffsetWithLocalBuffer() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test", 0, 4);

        assertEquals(0, buffer.getTextOffset());
    }

    @Test
    public void testHasTextAsCharactersWithStringResult() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("Test");

        // When result is String, hasTextAsCharacters should return false (because it's more efficient to return String)
        assertFalse(buffer.hasTextAsCharacters());
    }

    @Test
    public void testHasTextAsCharactersWithBuffer() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test", 0, 4);

        assertTrue(buffer.hasTextAsCharacters());
    }

    // --- Reset and Clear tests ---

    @Test
    public void testResetWithEmpty() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Some content", 0, 12);
        buffer.resetWithEmpty();

        assertEquals(0, buffer.size());
        // Note: getTextBuffer may return the existing array instance, not null, 
        // as resetWithEmpty only resets size/offsets but does not deallocate the segment.
    }

    @Test
    public void testResetWithChar() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWith('X');

        assertEquals(1, buffer.size());
        assertEquals("X", buffer.toString());
    }

    @Test
    public void testResetWithShared() throws JacksonException {
        char[] data = "SharedData".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 0, 5);

        assertEquals(5, buffer.size());
        assertSame(data, buffer.getTextBuffer()); // Should return the shared reference
    }

    @Test
    public void testResetWithCopy() throws JacksonException {
        char[] original = "Original".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithCopy(original, 0, 8);

        assertEquals(8, buffer.size());
        assertEquals("Original", buffer.toString());
        // Modifying original should not affect buffer
        original[0] = 'O';
        assertEquals("Original", buffer.toString());
    }

    @Test
    public void testResetWithString() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithString("TestString");

        assertEquals("TestString", buffer.contentsAsString());
    }

    @Test
    public void testResetWithCopyString() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithCopy("CopyString", 4, 6);

        assertEquals("String", buffer.toString());
    }

    // --- Append and Expand tests ---

    @Test
    public void testAppendChar() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append('A');
        buffer.append('B');

        assertEquals(2, buffer.size());
        assertEquals("AB", buffer.toString());
    }

    @Test
    public void testAppendCharArray() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append(new char[]{'A', 'B', 'C'}, 0, 3);

        assertEquals(3, buffer.size());
        assertEquals("ABC", buffer.toString());
    }

    @Test
    public void testAppendString() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Hello", 0, 5);

        assertEquals(5, buffer.size());
        assertEquals("Hello", buffer.toString());
    }

    @Test
    public void testAppendToSharedBuffer() throws JacksonException {
        char[] data = "Shared".toCharArray();
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.resetWithShared(data, 0, 6);

        // Appending should trigger unshare (copy)
        buffer.append("More", 0, 4);

        assertEquals(10, buffer.size());
        assertEquals("SharedMore", buffer.toString());
        // Ensure it doesn't use the original shared array anymore
        assertNotSame(data, buffer.getTextBuffer());
    }

    @Test
    public void testExpandCurrentSegment() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        char[] seg = buffer.getCurrentSegment();
        int originalLen = seg.length;

        // Expand
        char[] expanded = buffer.expandCurrentSegment();

        assertTrue(expanded.length > originalLen);
    }

    @Test
    public void testExpandCurrentSegmentWithMinSize() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.getCurrentSegment(); // init

        char[] expanded = buffer.expandCurrentSegment(1000);

        assertTrue(expanded.length >= 1000);
    }

    // --- Segment Management tests ---

    @Test
    public void testFinishCurrentSegment() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        // Fill first segment
        char[] first = buffer.getCurrentSegment();
        Arrays.fill(first, 'A');
        buffer.setCurrentLength(first.length);

        // Finish it
        char[] second = buffer.finishCurrentSegment();
        assertEquals(0, buffer.getCurrentSegmentSize());

        // Fill second
        Arrays.fill(second, 'B');
        buffer.setCurrentLength(second.length);

        // Verify aggregation
        assertEquals(first.length + second.length, buffer.size());
    }

    @Test
    public void testEmptyAndGetCurrentSegment() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("SomeText", 0, 9);

        char[] seg = buffer.emptyAndGetCurrentSegment();

        assertEquals(0, buffer.size());
        assertNotNull(seg);
    }

    @Test
    public void testSetCurrentAndReturn() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Initial", 0, 7);

        String result = buffer.setCurrentAndReturn(4); // Limit to 4 chars

        assertEquals("Init", result);
        assertEquals(4, buffer.size());
    }

    // --- Content Retrieval tests ---

    @Test
    public void testGetTextBuffer() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Test", 0, 4);

        char[] buf = buffer.getTextBuffer();

        assertEquals("Test", new String(buf));
    }

    @Test
    public void testGetTextBufferEmpty() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        char[] buf = buffer.getTextBuffer();

        assertEquals(0, buf.length);
    }

    @Test
    public void testContentsAsStringMultipleSegments() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        // Force multiple segments
        String s1 = "Seg1";
        String s2 = "Seg2";
        // Create a buffer with MIN_SEGMENT_LEN roughly
        while (buffer.size() < TextBuffer.MIN_SEGMENT_LEN) {
            buffer.append(s1, 0, s1.length());
        }
        buffer.append(s2, 0, s2.length());

        String result = buffer.contentsAsString();
        assertTrue(result.startsWith("Seg1"));
        assertTrue(result.endsWith("Seg2"));
    }

    @Test
    public void testContentsAsArray() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("ArrayContent", 0, 12);

        char[] result = buffer.contentsAsArray();

        assertEquals("ArrayContent", new String(result));
    }

    @Test
    public void testContentsToWriter() throws IOException, JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Writer", 0, 6);

        StringWriter sw = new StringWriter();
        int count = buffer.contentsToWriter(sw);

        assertEquals(6, count);
        assertEquals("Writer", sw.toString());
    }

    // --- Number Parsing tests ---

    @Test
    public void testContentsAsInt() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("123", 0, 3);

        int result = buffer.contentsAsInt(false);

        assertEquals(123, result);
    }

    @Test
    public void testContentsAsIntNegative() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        // The 'neg' parameter indicates the content starts with a minus sign
        buffer.append("-123", 0, 4);

        int result = buffer.contentsAsInt(true); 

        assertEquals(-123, result);
    }

    @Test
    public void testContentsAsLong() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("12345678901", 0, 11);

        long result = buffer.contentsAsLong(false);

        assertEquals(12345678901L, result);
    }

    @Test
    public void testContentsAsDouble() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("1.5", 0, 3);

        double result = buffer.contentsAsDouble(false);

        assertEquals(1.5, result, 0.0);
    }

    @Test
    public void testContentsAsFloat() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("2.5", 0, 3);

        float result = buffer.contentsAsFloat(false);

        assertEquals(2.5f, result, 0.0);
    }

    @Test
    public void testContentsAsDecimal() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("123.456", 0, 7);

        BigDecimal result = buffer.contentsAsDecimal(false);

        assertEquals(new BigDecimal("123.456"), result);
    }

    // --- Release tests ---

    @Test
    public void testReleaseBuffers() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Data", 0, 4);

        buffer.releaseBuffers();

        // Current segment should be released and set to null
        assertNull(buffer.getBufferWithoutReset());
    }

    @Test
    public void testReleaseBuffersWithEmpty() throws JacksonException {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.releaseBuffers(); // Should not fail

        assertEquals(0, buffer.size());
    }

    // --- Trim tests ---

    @Test
    public void testFinishAndReturnWithTrim() throws Exception {
        TextBuffer buffer = new TextBuffer(recycler);
        buffer.append("Value   ", 0, 8); // 3 spaces

        String result = buffer.finishAndReturn(5, true); // Last 3 are spaces

        assertEquals("Value", result);
    }
}

package tools.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import tools.jackson.core.Version;

public class VersionUtilTest {

    @Test
    public void testParseVersion_NullString_ReturnsUnknownVersion() {
        Version result = VersionUtil.parseVersion(null, "groupId", "artifactId");
        assertEquals(Version.unknownVersion(), result);
    }

    @Test
    public void testParseVersion_EmptyString_ReturnsUnknownVersion() {
        Version result = VersionUtil.parseVersion("", "groupId", "artifactId");
        assertEquals(Version.unknownVersion(), result);
    }

    @Test
    public void testParseVersion_WhitespaceOnlyString_ReturnsUnknownVersion() {
        Version result = VersionUtil.parseVersion("   ", "groupId", "artifactId");
        assertEquals(Version.unknownVersion(), result);
    }

    @Test
    public void testParseVersion_ValidVersionString_ReturnsParsedVersion() {
        Version result = VersionUtil.parseVersion("1.2.3", "com.example", "my-artifact");

        assertEquals(1, result.getMajorVersion());
        assertEquals(2, result.getMinorVersion());
        assertEquals(3, result.getPatchLevel());
        assertEquals("com.example", result.getGroupId());
        assertEquals("my-artifact", result.getArtifactId());
    }

    @Test
    public void testParseVersion_VersionWithSnapshotInfo_ReturnsParsedVersion() {
        Version result = VersionUtil.parseVersion("1.2.3-SNAPSHOT", "group", "artifact");

        assertEquals(1, result.getMajorVersion());
        assertEquals(2, result.getMinorVersion());
        assertEquals(3, result.getPatchLevel());
        assertEquals("SNAPSHOT", result.getSnapshotInfo());
    }

    @Test
    public void testParseVersion_VersionWithDifferentSeparators_UsesFirstSeparator() {
        // Pattern splits on [-_./;:] - tests with different separators
        Version result = VersionUtil.parseVersion("2-0-1", "g", "a");

        assertEquals(2, result.getMajorVersion());
        assertEquals(0, result.getMinorVersion());
        assertEquals(1, result.getPatchLevel());
    }

    @Test
    public void testParseVersion_VersionWithUnderscoreSeparator_ReturnsParsedVersion() {
        Version result = VersionUtil.parseVersion("1_0_0", "g", "a");

        assertEquals(1, result.getMajorVersion());
        assertEquals(0, result.getMinorVersion());
        assertEquals(0, result.getPatchLevel());
    }

    @Test
    public void testParseVersion_VersionWithDotSeparator_ReturnsParsedVersion() {
        Version result = VersionUtil.parseVersion("1.2.3", "g", "a");

        assertEquals(1, result.getMajorVersion());
        assertEquals(2, result.getMinorVersion());
        assertEquals(3, result.getPatchLevel());
    }

    @Test
    public void testParseVersion_OnlyMajorVersion_PatchAndMinorAreZero() {
        Version result = VersionUtil.parseVersion("5", "g", "a");

        assertEquals(5, result.getMajorVersion());
        assertEquals(0, result.getMinorVersion());
        assertEquals(0, result.getPatchLevel());
    }

    @Test
    public void testParseVersion_MajorAndMinorOnly_PatchIsZero() {
        Version result = VersionUtil.parseVersion("3.7", "g", "a");

        assertEquals(3, result.getMajorVersion());
        assertEquals(7, result.getMinorVersion());
        assertEquals(0, result.getPatchLevel());
    }

    @Test
    public void testParseVersion_NullGroupIdAndArtifactId_UsesEmptyString() {
        Version result = VersionUtil.parseVersion("1.0.0", null, null);

        assertEquals("", result.getGroupId());
        assertEquals("", result.getArtifactId());
    }

    @Test
    public void testParseVersionPart_NullString_ReturnsZero() {
        int result = VersionUtil.parseVersionPart(null);
        assertEquals(0, result);
    }

    @Test
    public void testParseVersionPart_EmptyString_ReturnsZero() {
        int result = VersionUtil.parseVersionPart("");
        assertEquals(0, result);
    }

    @Test
    public void testParseVersionPart_OnlyDigits_ReturnsParsedNumber() {
        assertEquals(123, VersionUtil.parseVersionPart("123"));
    }

    @Test
    public void testParseVersionPart_DigitsWithLeadingNonDigits_ReturnsZero() {
        assertEquals(0, VersionUtil.parseVersionPart("abc123"));
    }

    @Test
    public void testParseVersionPart_DigitsFollowedByNonDigits_OnlyParsesLeadingDigits() {
        assertEquals(123, VersionUtil.parseVersionPart("123abc"));
    }

    @Test
    public void testParseVersionPart_DigitsInMiddle_StopsAtNonDigit() {
        assertEquals(12, VersionUtil.parseVersionPart("12a3"));
    }

    @Test
    public void testParseVersionPart_OnlyNonDigits_ReturnsZero() {
        assertEquals(0, VersionUtil.parseVersionPart("abc"));
    }

    @Test
    public void testParseVersionPart_LargeNumber_ReturnsParsedValue() {
        assertEquals(2147483647, VersionUtil.parseVersionPart("2147483647"));
    }

    @Test
    public void testParseVersionPart_VersionStringPart_ParsesCorrectly() {
        // Simulates parsing "1" from "1.2.3"
        assertEquals(1, VersionUtil.parseVersionPart("1"));
    }

    @Test
    public void testThrowInternal_ThrowsIllegalStateException() {
        try {
            VersionUtil.throwInternal();
            fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            assertTrue(e.getMessage().contains("Internal error"));
        }
    }

    @Test
    public void testThrowInternalReturnAny_ThrowsIllegalStateException() {
        try {
            VersionUtil.throwInternalReturnAny();
            fail("Expected IllegalStateException");
        } catch (IllegalStateException e) {
            assertTrue(e.getMessage().contains("Internal error"));
        }
    }

    @Test
    public void testVersionFor_ClassWithoutPackageVersion_ReturnsUnknownVersion() {
        // Use a class that is guaranteed not to have a PackageVersion in its package
        Version result = VersionUtil.versionFor(String.class);
        assertEquals(Version.unknownVersion(), result);
    }

    @Test
    public void testVersionFor_NullClass_HandlesGracefully() {
        // The method will try to get package of null, which should trigger exception handling
        // and return unknownVersion
        Version result = VersionUtil.versionFor(null);
        assertEquals(Version.unknownVersion(), result);
    }

    @Test
    public void testVersionFor_PrimitiveClass_HandlesGracefully() {
        // Primitive classes like int.class don't have a package
        Version result = VersionUtil.versionFor(int.class);
        assertEquals(Version.unknownVersion(), result);
    }
}

